pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A post_residual that is too small to hold any plausible future item (gap < 10)
    // is pure waste: penalize it quadratically.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * (10 - post_residual) as f64 * 2.0;
    }
    // Gaps that can't fit the known next item are also partially wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }
    // Gaps that exactly fit the next item are gold: reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // --- Tight fit reward ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // --- Open-bin pressure: prefer denser packing when many bins are open ---
    score += open_bins_count as f64 * 0.4;

    // Deviation from mean residual: bins far below mean are "almost full",
    // using them is good; bins far above mean are roomy, deprioritize slightly.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // --- New-bin candidate: make the empty bin moderately attractive only
    // when the item is large or no good fit exists ---
    if bin_residual == bin_capacity {
        score += 4.0 + (100.0 - item_size as f64) * 0.05;
    }

    // --- Slight stream-progression bias: pack tighter as stream advances ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

