    // waste but too small for typical future items.
    if post_residual > 0 && post_residual < 40 {
        let pr = post_residual as f64;
        if next_item_size == 0 || (next_item_size as f64) > pr {
            if pr < mean_residual - 3.0 && pr > 6.0 {
                score += (mean_residual - pr) * (0.6 + 0.8 * progress);
            }
        }
    }

    // Late-stream compaction squeeze: leftover residual space is unlikely to
    // be reused near the end, so push harder toward zero-waste placements.
    if progress > 0.75 && post_residual > 0 {
        score += post_residual as f64 * (progress - 0.75) * 4.0;
    }

    // Keep near-perfect packs on small items preferred over spreading.
    if bin_residual > item_size && bin_residual - item_size <= 2 && item_size <= 10 {
        score -= 8.0;
    }

    // New mutation: divisibility-friendly residuals (10/25/50) are easier
    // targets for future items; reward them modestly.
    if post_residual > 0 && post_residual <= 50
        && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 12.0;
    }

    // New mutation: when the next item exactly equals the mean residual,
    // favor bins whose post-residual equals the mean (fleet-consistent state).
    if next_item_size as f64 == mean_residual && post_residual as f64 == mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
