        score += 8.0;
    } else if post_residual < 60 {
        score += 20.0;
    } else {
        score += 35.0;
    }

    // Exact fit is ideal regardless of everything else.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space is worse late in the stream (less chance to fill it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score -= 20.0 * progress;
    } else if post_residual >= 60 {
        score += 15.0 * progress;
    }

