    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over spreading.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (compactness).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let bad_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 45.0 + bad_fits * -60.0 + open_bins_count as f64 * 0.5
            - if post_residual == bin_capacity { 0.0 } else { 0.0 };
        // If the next item is huge, a fresh bin is fine.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    score
}

