    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fraction.
    // Classes: 0 (perfect fit), 1 (tiny gap 1-10), 2 (small 11-25), 3 (medium 26-50), 4 (large >50).
    let class = if post_residual == 0 { 0u32 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 25 { 2 }
        else if post_residual <= 50 { 3 }
        else { 4 };

    // Reward tight fits strongly.
    score -= match class {
        0 => 60.0,
        1 => 40.0,
        2 => 22.0,
        3 => 8.0,
        _ => 0.0,
    };

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= if gap == 0 { 55.0 } else if gap <= 10 { 35.0 } else { 15.0 };
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportional to wasted potential.
        score += (next_item_size as f64) * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // fits well. Penalize the fresh bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // If some open bin would leave a usable residual (>= next item or small gap),
            // discourage the new bin.
            let any_good = fitting_bins_count > 1 || post_residual == 0;
            score += if any_good { 45.0 } else { 12.0 };
        }
        // Early in the stream, having a fresh bin is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Modular harmonics on post_residual: leftovers divisible into common item sizes
    // (10,20,25,50) are more reusable.
    if post_residual > 0 {
        let reusable = post_residual % 10 == 0 || post_residual % 25 == 0 || post_residual == 50;
        if reusable { score -= 10.0; }
        // Penalize awkward prime-ish gaps.
        if post_residual % 10 != 0 && post_residual < 20 { score += 5.0; }
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual (fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Scale by number of open bins to avoid bin proliferation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small to hold even the smallest
    // possible item (<= 1) are pure waste; residuals below the lookahead
    // item's size are also likely waste.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if (post_residual as f64) < mean_residual * 0.25 {
        // Tiny unusable gap: penalize heavily.
        score += 40.0;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // reward this placement (keeps a chain going).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual cannot host the next item: mild penalty unless zero.
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (avoid scattering); with few open bins, new bins are cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64 / (1.0 + progress * 4.0)).min(6.0);
    score += pressure * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to a fresh bin's usefulness (i.e., current fit is bad).
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item would leave a big useful residual anyway, opening
        // a new bin is fine.
        if post_residual as f64 >= mean_residual {
            score -= 20.0;
        }
    }

    // Prefer tighter fits generally: reward small post_residual quadratically.
    score -= ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(2) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the NEXT item exactly fills the leftover.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Next item fits here too: mild reward proportional to how snugly.
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space that the next item cannot use: penalize.
            score += 30.0 + 0.5 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize wasting a nearly-full bin on a tiny item (bad residual economy).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio < 0.35 && bin_residual != bin_capacity {
        score += 80.0 * (0.35 - fill_ratio);
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious;
    // avoid dumping large items into them unless it's a perfect fit.
    let rel = post_residual as f64 - mean_residual;
    if rel > 0.0 {
        score += 0.3 * rel;
    } else {
        score += 0.6 * rel; // below-mean residual => penalize more (score decreases? no: rel negative lowers score)
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early
    // in the stream or when no existing bin fits well (large post_residual everywhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Baseline cost of a new bin; make it unattractive unless item is large.
        score = 60.0 - 0.4 * item_size as f64 + 40.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin leaves room for the next item too: slight bonus.
            score -= 10.0;
        }
        // If many bins are open already, discourage proliferation.
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small leftover space.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * (1.0 - tight) * (1.0 - tight) * (1.0 - tight);

    // Exact or near-exact fill: strong reward.
    if post_residual < 5 {
        score -= 80.0;
    } else if post_residual == 0 {
        score -= 150.0;
    }

    // Lookahead: reward if leftover can host the next item, penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to the next item's needs.
            score += 12.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last chance: this is the only bin that fits; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty so among many candidates only truly good fits win.
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Discourage leaving residuals that are hard to reuse (odd narrow bands).
    let r = post_residual;
    if r > 0 && r < 10 {
        score += 15.0; // tiny slivers are almost dead space
    }

    // Time horizon: early in the stream, keep bins flexible (favor moderate residuals);
    // late in the stream, prioritize closing bins out aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 40.0 * t * (1.0 - tight);
    score += 10.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins -> prefer filling existing ones;
    // few open bins with large mean residual -> tolerate opening new space.
    if open_bins_count > 4 {
        score -= 8.0 * ((open_bins_count as f64 - 4.0).min(10.0));
    }
    if mean_residual > (item_size as f64) * 1.5 {
        score -= 10.0; // plenty of slack overall; use it
    } else if mean_residual < (item_size as f64) * 0.6 && bin_residual == bin_capacity {
        score -= 20.0; // bins are tight overall; a fresh bin is valuable
    }

    // New-bin candidate: only attractive if it enables a much better long-term layout.
    if bin_residual == bin_capacity {
        // Base penalty: prefer reusing bins when reasonable fits exist.
        score += 35.0;
        // But if the item is large and would leave a very awkward remainder in any open bin,
        // opening a fresh bin can win.
        if item_size >= 60 && post_residual >= 0 {
            let waste_if_forced = 0.0f64;
            let _ = waste_if_forced;
            score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        }
        // Last item: never open a new bin.
        if next_item_size == 0 && step_index + 1 == total_items {
            score += 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: waste potential, mildly devalued as stream progresses (reuse old bins matters more early).
    let mut score = post / cap * (1.0 - 0.3 * progress);

    // Non-linear polynomial coupling: penalize large residuals super-linearly,
    // but soften when the stream is near its end (few future items to fill gaps).
    let p2 = post / cap * post / cap;
    let p3 = p2 * post / cap;
    score += 0.8 * p2 + 0.5 * p3 * (1.0 - progress);

    // Tight fits rewarded, with smooth interaction with progress.
    let tightness = (item_size as f64 / bin_residual as f64).clamp(0.0, 1.0);
    score -= 1.5 * tightness * tightness * (0.5 + 0.5 * progress);

    // Lookahead coupling: if next item fits the post-residual, strongly reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fill = nxt / post.max(1.0);
            score -= 0.9 * fill * (1.0 - progress);
        } else {
            // Next item cannot use leftover: penalize proportionally to leftover size.
            score += 0.4 * (post / cap) * (nxt / cap);
        }
    }

    // Scarcity bonus: last fitting bin gets a smooth discount.
    if fitting_bins_count == 1 {
        score -= 0.6 * (1.0 - post / cap);
    }

    // Mean-residual coupling: avoid bins that deviate strongly below mean (would strand space).
    let dev = (post - mean_residual) / cap;
    score += 0.25 * dev * dev * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline; slight penalty to discourage opening unless leftovers are big.
    if bin_residual == bin_capacity {
        score = 0.55 + 0.1 * (1.0 - progress) - 0.5 * (post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which tenth of capacity it occupies
    let item_class = (item_size / 10).max(1);
    let post_class = post_residual / 10;

    // Reward tight fits: exact fill is best
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize post_residual in the "dead zone" classes: residuals that few
    // item sizes (1..100) can still use. Class 1 (1..=10) is usable by tiny
    // items only; classes near 50 are the most reusable.
    let reusability = match post_class {
        0 => 0.0_f64,
        1 => 0.2,
        2 => 0.5,
        3 => 0.7,
        4 => 0.9,
        5 => 1.0,
        6 => 0.9,
        7 => 0.75,
        8 => 0.6,
        9 => 0.45,
        _ => 0.3,
    };
    score -= 12.0 * reusability;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / 50.0).max(0.0);
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // would leave very poor residuals. Compare against mean residual.
    if bin_residual == bin_capacity {
        let mean_post = (mean_residual - item_size as f64).max(0.0);
        // new bin leaves residual 100-item_size; only attractive if existing
        // bins would end up with tiny unusable residuals
        if mean_post > 40.0 {
            score -= 10.0;
        } else {
            score += 30.0 + 20.0 * (1.0 - mean_post / 40.0);
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // many open bins: discourage more
        score += 2.0 * open_bins_count as f64;
    }

    // Modulo harmonic bonus: items whose size divides capacity nicely
    // (multiples of 20/25/50) pair well; reward bins whose residual is a
    // multiple of 10 after placement.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Integer-division threshold: penalize leaving residual in (10,20) range
    // where only small items fit
    if post_residual > 10 && post_residual < 20 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps left after placement are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits: filling the bin nearly exactly is excellent.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Perfect-fit lookahead: if the next item exactly consumes the post residual,
    // strongly favor this bin (chained tight packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this gap anyway; slight penalty proportional to gap waste.
        score += post_residual as f64 * 0.15;
    }

    // Last-chance bonus: this is the only open bin that fits; using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: penalize spreading across many bins mildly,
    // encouraging consolidation into fewer bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin is attractive only if the item
    // is large or fits among open bins are poor.
    if bin_residual == bin_capacity {
        score += 25.0; // default cost of opening a new bin
        if item_size > 60 {
            score -= 30.0; // large items are fine in a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
    }

    // Alignment with the fleet: prefer bins whose residual is close to the mean
    // (keeps residuals homogeneous and packable by future items).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.3;

    // Early in the stream, be a bit more liberal about opening bins
    // (future flexibility); later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= progress * 20.0;
    } else {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward for leaving (near-)zero post residual.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let lookahead_gap = post_residual as i64 - next_item_size as i64;
        if lookahead_gap == 0 {
            score -= 60.0; // chain: next item perfectly fills remainder
        } else if lookahead_gap > 0 && (lookahead_gap as u32) <= 10 {
            score -= 15.0; // next item leaves small usable gap
        } else if lookahead_gap < 0 && (-lookahead_gap) <= 10 {
            score += 10.0; // next item barely doesn't fit: mild penalty
        }

        // Coupling with mean residual: prefer bins whose post_residual stays close to mean
        let mean_gap = (post_residual as f64 - mean_residual).abs();
        score += 0.3 * mean_gap;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize wasting a large residual on a small item (dead space creation).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_ratio * waste_ratio;

    // New-bin candidate: make it unattractive unless all open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If nothing else fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Late in stream: tighten packing, avoid opening bins unnecessarily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - waste_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Near-perfect fit bonus (residual too small for any plausible future item)
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0 + (10 - post_residual) as f64;
    }

    // Lookahead coupling: reward if next item fits into post_residual (chain packing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + next_item_size as f64 * 0.5;
        } else {
            // penalize leaving residual that is awkwardly just below next item
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            if post_residual < next_item_size {
                score += gap * 0.3;
            }
        }
    } else {
        // last item: any residual is dead space; prefer tightest
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when fit into existing bins is terrible
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty for opening a new bin
        score += 20.0;
        // more attractive early (amortize bin over long stream) and when few bins open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        score -= 2.0 * (open_bins_count.min(10) as f64);
        // if many bins fit, opening new bin is wasteful
        if fitting_bins_count > 2 {
            score += 25.0 * (fitting_bins_count as f64);
        }
        // if mean residual is large, open bins have room; penalize new bin
        score += mean_residual * 0.5;
    } else {
        // existing bin: mild preference toward fuller bins (best-fit style)
        score += (bin_capacity - bin_residual) as f64 * 0.05;
        // favor bins whose residual is close to mean (balance), slight regularizer
        score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;
    }

    // Time-horizon shaping: late in stream, minimize waste aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.5 + 1.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, warped by smooth polynomial in progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear penalty on small post residuals (dead space), amplified late in stream
    let dead = (1.0 - norm_pr).powi(3);
    score -= dead * 40.0 * (0.5 + progress);

    // Reward tight fits: post residual near zero
    score -= (1.0 - norm_pr).powi(2) * (item_size as f64) * 0.3;

    // Lookahead coupling: penalize if next item fits poorly in post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score += gap * 0.2 * (1.0 - progress);
        if nx <= pr {
            score -= 10.0 * (1.0 - nx / cap) * (0.5 + progress);
        } else {
            score += 8.0 * (nx / cap) * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else {
        score += 5.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean residual coupling: prefer bins deviating from mean (consolidation)
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: penalize unless post residual would be very usable
    if bin_residual == bin_capacity {
        let usability = (norm_pr * (1.0 - norm_pr) * 4.0).powi(2);
        score += 60.0 - 30.0 * usability * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that pair well with
    // typical item sizes (10..80 multiples and common remainders) are cheap.
    let post_class = post_residual % 10;
    let waste_penalty = match post_class {
        0 => -6.0,                  // perfectly reusable slot
        5 => -2.0,                  // still composable with halves
        1 | 9 => 3.0,               // near-dead edges
        2 | 8 => 1.5,
        _ => 0.0,
    };
    score += waste_penalty;

    // Integer-division thresholds on post_residual: classify usability.
    let usable = post_residual / 10; // number of smallest items it could still host
    if usable == 0 && post_residual > 0 {
        score += 25.0;               // dead space: residual below min item size
    } else if usable <= 2 {
        score += 4.0;
    }

    // Reward tight fits (capacity fractions).
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_frac;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly prefer this bin (harmonic pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let pair_waste = post_residual - next_item_size;
            if pair_waste <= 5 { score -= 12.0; }
            else if pair_waste > 50 { score += 6.0; }
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer consolidating into bins already below the mean residual
    // (keeps a few large-capacity bins open for big items).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Early in the stream, tolerate opening bins (explore); later, pack tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, or when item is large and
        // no open bin offers a good fit.
        let exploration = 12.0 * (1.0 - progress);
        score -= exploration;
        if item_size >= 50 { score -= 5.0; }
        if fitting_bins_count > 0 && post_residual < 20 { score += 20.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A post_residual that is too small to hold any plausible future item (gap < 10)
    // is pure waste: penalize it quadratically.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * (10 - post_residual) as f64 * 2.0;
    }
    // Gaps that can't fit the known next item are also partially wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }
    // Gaps that exactly fit the next item are gold: reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // --- Tight fit reward ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // --- Open-bin pressure: prefer denser packing when many bins are open ---
    score += open_bins_count as f64 * 0.4;

    // Deviation from mean residual: bins far below mean are "almost full",
    // using them is good; bins far above mean are roomy, deprioritize slightly.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // --- New-bin candidate: make the empty bin moderately attractive only
    // when the item is large or no good fit exists ---
    if bin_residual == bin_capacity {
        score += 4.0 + (100.0 - item_size as f64) * 0.05;
    }

    // --- Slight stream-progression bias: pack tighter as stream advances ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect 2-step fit: post_residual exactly equals next item size.
        if (post_residual as i64) == (next_item_size as i64) {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits here after this placement: reward closeness of match.
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / 80.0).max(0.0);
        } else {
            // Next item will NOT fit in residual: penalize, worse if residual is large dead space.
            let miss = (next_item_size - post_residual) as f64;
            score += 15.0 + 0.4 * miss;
        }

        // Combined 2-step chain: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 50.0;
        }

        // Compare post_residual against mean residual across open bins.
        if post < mean_residual {
            score -= 0.5 * (mean_residual - post);
        } else {
            score += 0.3 * (post - mean_residual);
        }
    } else {
        // Last item: strongly prefer tightest fill.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.2 * post_residual as f64;
    }

    // Discourage opening new bins when many bins are already open and fit exists.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: if the next item fits into the post_residual, reward leaving that gap;
    // otherwise penalize a post_residual that is too small to be useful.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual < item_size + next_item_size {
            // chain fit: this placement enables the next item in the same bin
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // dead space relative to the upcoming item
            let waste_frac = post_residual as f64 / next_item_size as f64;
            score += 8.0 * (1.0 - waste_frac);
        }
    } else {
        // last item: any residual is pure waste; minimize it hard
        score += 0.0;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit this item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening new bins when plenty of capacity exists across open bins.
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of a fresh bin plus crowding adjustment
        score += 55.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // late in the stream, opening bins is cheaper than fragmenting
        score -= 20.0 * progress;
        if mean_residual < item_size as f64 {
            score -= 15.0; // open bins are nearly full, new bin is good
        }
    } else {
        // mildly prefer bins with residuals close to the item (best-fit sharpening)
        let diff = (bin_residual - item_size) as f64;
        score += 0.15 * diff;
        // spread preference: pick bins below mean residual to keep balance
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    // Slight global pressure: with many open bins, favor consolidation into existing bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) emphasis
    let mut score = pr * (1.0 + norm_pr * (1.0 - progress));

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (0.5 + 2.0 * progress * (1.0 - progress) * 4.0);
    score += coupling * cap * 0.5;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * item_size as f64 * (0.2 + 0.6 * progress);

    // Penalize dead space that cannot fit the next item (smooth hinge)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += gap * (0.5 + 0.5 * progress);
        // Reward leaving room exactly for the next item
        let match_bonus = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= match_bonus.max(0.0) * 8.0 * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + progress);
    }

    // Mild preference for consolidating into fewer bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    // New-bin candidate: keep it attractive only when existing residuals are poor
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        let openness = (mean_norm - norm_pr).abs();
        score += 5.0 + 20.0 * (1.0 - openness.min(1.0)) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit core), scaled.
    score = post_residual as f64 * 1.0;

    // Harmonic class of the resulting residual: modulo-10 classes.
    // Residuals that are "useful" for typical item sizes (multiples of 10)
    // should be rewarded; awkward residues penalized.
    let pr = post_residual as f64;
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -8.0,                       // perfectly reusable residual
        1 | 9 => 6.0,                    // worst: nearly nothing usable
        2 | 8 => 3.0,
        3 | 7 => 1.0,
        4 | 6 => -1.0,
        _ => 0.0,                        // 5: half-slot, moderately useful
    };
    score += class_penalty;

    // Integer-division thresholds: how many "typical" items (size 10..20)
    // could still fit? Reward bins that can host >=1 more item.
    let slots10 = post_residual / 10;
    if slots10 == 0 && post_residual > 0 {
        score += 10.0; // dead space below smallest item
    } else if slots10 >= 2 {
        score -= 2.0 * slots10 as f64;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next fits: reward proportional to how tight the chain is
            let tightness = (post_residual - next_item_size) as f64;
            score -= 10.0 - tightness * 0.3;
        } else {
            // next item won't fit here; slight penalty if residual is large
            // (wasted capacity relative to the known future demand)
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += gap * 0.5; // near-miss: painful near-fit
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default score.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin: its full residual as potential waste,
        // softened as stream progresses (sunk-cost reasoning).
        score = bin_capacity as f64 * 0.6;
        // If many open bins with large mean residual, discourage new bins.
        score += (open_bins_count as f64).sqrt() * 2.0;
        // But if nothing fits well (post_residual of alternatives high),
        // the new bin competes naturally via its score.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0; // later in stream: more willing to open bins? no—
        // actually late in stream we prefer consolidating; flip:
        score += progress * 20.0;
    }

    // Mean-residual context: when open bins are generally empty-ish,
    // prefer filling them (penalize choosing a bin far from mean fit).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Small tie-breaker toward tighter fits scaled by capacity fraction.
    score += (post_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible follow-up item are "dead". Penalize them super-linearly.
    let dead_threshold = 10.0f64; // smallest item size
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: best possible outcome
    }

    // Reward tight fits: fraction of bin_residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 18.0;

    // Lookahead: if next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_tightness = next_item_size as f64 / post_residual as f64;
        score -= lookahead_tightness * 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space relative to the known next item — penalize.
        score += 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: penalize opening new bins when many are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with open_bins_count.
        score += 15.0 + 4.0 * open_bins_count as f64;
        // Allow new bin only if it promises a very large residual for the future
        // and current bins are nearly full on average.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 30.0;
        }
    } else {
        // Mild reward for using existing bins when open count is high.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Stream progression: early on, be slightly more willing to open bins
    // (build diversity); later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    } else {
        score += progress * 5.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (i.e., more filled bins), draining the nearly-full ones first.
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fit (small post_residual already favored by base).

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this placement is a perfect chain -> strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - chain_gap / bin_capacity as f64);
        if chain_gap == 0.0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit in this bin after placement: penalize dead space
        // that is too small to be useful for anything typical.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 8.0; // tiny unusable sliver
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // "almost full" -> prefer packing them (close bins early).
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (res - mean_residual) / mean_residual;
        if rel < 0.0 {
            score += 3.0 * rel; // below mean residual -> reward (subtract)
        } else {
            score += 1.5 * rel; // above mean -> mild penalty
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make an empty bin moderately attractive so
    // it wins only when open bins give poor fits.
    if bin_residual == bin_capacity {
        score -= 5.0;
        // Early in stream, opening bins is cheap; late in stream prefer reuse.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If next item is large and current item is small, a fresh bin keeps
        // flexibility for the big item.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 15.0;
        }
    }

    // Fragmentation penalty: post_residual in awkward mid-range is wasteful.
    let pr = post_residual;
    if pr >= 1 && pr < 10 {
        score += 6.0;
    } else if pr >= 10 && pr < 20 {
        score += 2.0;
    } else if pr >= 50 {
        score -= 2.0; // large leftover remains usable
    }

    // Slight preference to fill bins when many bins are open.
    score += 0.5 * open_bins_count as f64 * (res / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: if post_residual is small, strongly favor this bin.
    let tight_bonus = 30.0 * (-post_residual as f64 / 20.0).exp();
    score -= tight_bonus;

    // Penalize leaving residual that no plausible item can fill:
    // if post_residual is below the minimum item size (1), it's perfect; if it's
    // small but nonzero, it risks becoming dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // awkward sliver of space
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64);
        } else {
            // Next item cannot use this bin's leftover; slight penalty proportional
            // to wasted potential.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is discouraged when decent fits exist, but attractive
        // when the item would leave a large residual elsewhere anyway.
        // Baseline: new bin costs a bit.
        score += 15.0;
        // But if this item is huge relative to capacity, a fresh bin is natural.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= 15.0 * (1.0 - progress);
        // If many bins are open and mean residual is high, prefer reusing them.
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
        score += (mean_residual / bin_capacity as f64).max(0.0) * 10.0;
    } else {
        // Mild reward for keeping bin count low by reusing existing bins.
        score -= 2.0;
        // Prefer filling bins whose residual is already low (consolidation).
        score -= (1.0 - bin_residual as f64 / bin_capacity as f64) * 6.0;
        // Late in the stream, avoid creating new bins even more strongly.
        if progress > 0.8 {
            score -= 5.0;
        }
    }

    // Global balance: if mean residual is high, encourage using up space.
    if !is_new_bin && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = (pr / cap).clamp(0.0, 1.0);

    // Base: prefer tight fits via non-linear decay of post-residual.
    let mut score = (fit * std::f64::consts::PI).sin() * cap * 0.5;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; later, dead space is heavily penalized.
    let waste_penalty = pr * pr / cap * (0.4 + 1.6 * progress * progress);
    score += waste_penalty;

    // Perfect-fill reward, stronger as stream progresses.
    if post_residual == 0 {
        score -= 25.0 + 25.0 * progress;
    }

    // Last-chance bin: reward smoothly, scaled by how much space is left.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 12.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr - nxt).max(0.0);
        let coupling = (fits_next / cap) * (pr / cap) * 20.0;
        score -= coupling * (0.5 + 0.5 * progress);
    }

    // Mildly penalize spreading across many open bins early; relax later.
