    } else {
        score += ((bin_residual as f64 - mean_residual).abs()) * 0.35;
        score -= progress * 8.0;
    }

    // Reward placements that move a bin's residual toward the fleet mean.
    let dr_before = (bin_residual as f64 - mean_residual).abs();
    let dr_after = (post_residual as f64 - mean_residual).abs();
    if dr_after < dr_before {
        score -= (dr_before - dr_after) * 0.4;
