        score -= 70.0;
    }

    // Progress-driven consolidation pressure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 + progress);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 20.0 + 40.0 * progress;
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
        if item_size > 60 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        } else if fitting_bins_count == 1 && post_residual >= 8 {
            score += 35.0;
        }
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score += 15.0;
        }
        if fitting_bins_count > 0 {
            let item = item_size as f64;
            let cap = bin_capacity as f64;
            if item > 0.6 * cap && item > mean_residual + 8.0 {
                score -= 12.0 * progress;
            }
            let waste_ratio = (bin_residual - item_size) as f64 / cap;
            if waste_ratio > 0.30 && item / cap > 0.5 {
                score -= 18.0;
            }
            if waste_ratio > 0.45 && next_item_size > 0 && (bin_residual - item_size) < next_item_size {
                score -= 10.0 * (1.0 - progress);
            }
            if waste_ratio > 0.38 && (bin_residual - item_size) as f64 > mean_residual * 1.6 {
                score -= 14.0 * (1.0 - 0.5 * progress);
            }
            // Spawn-bias calibration: fresh bins more attractive when the
            // fleet is fragmented and the item is big; scaled down as the
            // stream matures so late stream favors sealing existing bins.
            let fleet_fragmentation = open_bins_count as f64 * mean_residual / cap.max(1.0);
            if fleet_fragmentation > 1.5 && item / cap > 0.55 {
                score -= (fleet_fragmentation - 1.5) * 4.5 * (1.0 - 0.6 * progress);
            }
            // Crowded-fleet fresh-bin justification.
            let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
            if crowded > 3.0 && item / cap > 0.45 {
                score -= 8.0 + 6.0 * progress;
            }
            if mean_residual < 12.0 && item / cap > 0.7 {
                score -= 10.0 + 8.0 * progress;
            }
            if next_item_size > 0 && next_item_size > mean_residual as u32 && item > next_item_size {
                score -= 6.0 * (1.0 - progress);
            }
            // Mutation: spawn-vs-seal gap arbitration — compare the gap a
            // fresh bin would leave against the best gap any open bin could
            // leave; only spawn when the fresh-bin gap is clearly tighter.
            let fresh_gap = bin_capacity - item_size;
            if fitting_bins_count > 0 {
                let best_open_gap = bin_capacity; // upper bound; refined by waste terms below
                let _ = best_open_gap;
                if fresh_gap as f64 > mean_residual * 2.5 && item / cap < 0.6 {
                    score += 14.0 + 10.0 * progress;
                }
            }
        }
    } else {
        // Prefer bins with residual close to the fleet mean (packable by future items).
        score += ((bin_residual as f64 - mean_residual).abs()) * 0.35;
        score -= progress * 8.0;
    }

    // Reward placements that move a bin's residual toward the fleet mean.
    let dr_before = (bin_residual as f64 - mean_residual).abs();
    let dr_after = (post_residual as f64 - mean_residual).abs();
    if dr_after < dr_before {
        score -= (dr_before - dr_after) * 0.4;
    }

    // Exact-fit bonus scaled by item size.
    if post_residual == 0 {
        score -= item_size as f64 * 0.15;
    }

    // Penalize leaving gaps that neither fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * (0.5 + 1.5 * progress);
    }

    // Prefer the bin whose post-residual best matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / bin_capacity.max(1) as f64) * 6.0;
    }

    // Perfect handoff chain reward, deepened late in the stream.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0 * (0.5 + progress);
    }

    // Avoid creating residuals in the "unfillable band".
    if post_residual > 0 && post_residual < 40 {
        let pr = post_residual as f64;
        if next_item_size == 0 || (next_item_size as f64) > pr {
            if pr < mean_residual - 3.0 && pr > 6.0 {
                score += (mean_residual - pr) * (0.6 + 0.8 * progress);
            }
        }
    }

    // Residual-pairing lookahead.
    if next_item_size > 0 && post_residual > next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap <= 3 {
            score -= 12.0 + 10.0 * progress;
        }
    }

    // Late-stream compaction squeeze.
    if progress > 0.75 && post_residual > 0 {
        score += post_residual as f64 * (progress - 0.75) * 4.0;
    }

    // Discourage spreading small items off near-perfect packs.
    if bin_residual > item_size && bin_residual - item_size <= 2 && item_size <= 10 {
        score -= 8.0;
    }

    // Waste-fraction penalty on open bins.
    if bin_residual < bin_capacity && post_residual > 0 {
        let waste_frac = post_residual as f64 / bin_residual.max(1) as f64;
        score += waste_frac * 6.0 * (1.0 - progress);
    }

    // Density-ratio compaction.
    if bin_residual < bin_capacity {
        let consumed_frac = item_size as f64 / bin_residual.max(1) as f64;
        if consumed_frac > 0.7 {
            score -= (consumed_frac - 0.7) * 30.0 * (1.2 - progress);
        }
    }

    // Near-exact residual targeting.
    if post_residual > 0 && post_residual <= 12 {
        score -= 5.0 * (1.0 - progress) + 3.0 * progress;
    }

    // Dead-gap oracle.
    if post_residual > 0 && post_residual < 30 {
        let pr = post_residual as f64;
        let next_blocks = next_item_size > 0 && (next_item_size as f64) > pr;
        if next_blocks && pr < mean_residual * 0.8 {
            score += (mean_residual * 0.8 - pr) * (0.5 + progress);
        }
    }

    // Residual ladder smoothing.
    if post_residual > 0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
    }

    // Two-item lookahead chain with bin pressure.
    if next_item_size > 0 && next_item_size == post_residual && open_bins_count > 4 {
        score -= 8.0;
    }

    // Stranded-gap accounting.
    if post_residual > 0 && post_residual < 20 {
        let pr = post_residual as f64;
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Adaptive tight-band bonus.
    if next_item_size > 0 && post_residual > next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover <= 5 && open_bins_count >= 2 {
            score -= (6.0 - leftover as f64) * (1.5 + 0.25 * open_bins_count.min(12) as f64);
        }
    }

    // Harmony coupling.
    if bin_residual < bin_capacity && next_item_size > 0 && post_residual >= next_item_size {
        let consumed_frac = item_size as f64 / bin_residual.max(1) as f64;
        let reusable = (post_residual - next_item_size) as f64;
        if consumed_frac > 0.5 && reusable <= 10.0 {
            score -= consumed_frac * (10.0 - reusable) * (0.6 + 0.8 * progress);
        }
    }

    // Endgame exactness.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Dead-space variance squeeze.
    if post_residual > 0 && post_residual < 15 {
        let pr = post_residual as f64;
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Residual-continuity bonus.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if (pr - mean_residual).abs() <= 6.0 && pr >= 5.0 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Bin-count-aware exactness.
    if post_residual == 0 && open_bins_count > 6 {
        score -= 6.0 + open_bins_count.min(20) as f64 * 0.5;
    }

    // Residual-divisibility lookahead.
    if next_item_size > 1 && post_residual > 0 && post_residual >= next_item_size {
        let q = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 && q >= 1 {
            score -= (q as f64).min(4.0) * 4.0 * (1.0 - 0.5 * progress);
        } else if rem <= 2 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Dead-space floor guard.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if ns > pr {
            let unreachable = (ns - pr).min(pr) as f64;
            score += unreachable * 0.35 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // Fragmentation-weighted consolidation.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let pr = post_residual as f64;
        let reusable = next_item_size > 0 && (next_item_size as u32) <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-sweep pairing.
    if next_item_size > 0 && post_residual > next_item_size {
        let sweep = post_residual - next_item_size;
        if sweep as f64 > mean_residual * 1.5 {
            score += (sweep as f64 - mean_residual * 1.5) * 0.25 * (1.0 - progress);
        }
    }

    // Late-stream seal-or-spawn arbitration.
    if progress > 0.7 && bin_residual == bin_capacity && fitting_bins_count > 0 {
        let best_possible_gap = bin_residual.saturating_sub(item_size);
        if best_possible_gap <= 10 {
            score += 30.0 * (progress - 0.7) * 3.0;
        }
    }

    // Mutation: dead-space budget accounting — track the cumulative dead
    // space this placement would strand relative to what remains of the
    // stream; penalize placements whose stranded gap cannot be absorbed by
    // the next item AND exceeds the typical reusable residual band, with
    // weight growing as reusable opportunities shrink.
    if post_residual > 0 && bin_residual < bin_capacity {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        let absorbable = next_item_size > 0 && ns <= pr && (pr - ns) <= 12.0;
        let mean_absorbable = pr >= mean_residual - 1.0 && pr <= mean_residual + 12.0;
        if !absorbable && !mean_absorbable {
            let remaining = (total_items.saturating_sub(step_index)) as f64;
            let opportunity = 1.0 / (1.0 + remaining / 50.0);
            score += pr * 0.10 * (1.0 + opportunity);
        }
    }

    // Mutation: dual-item chain shaping — when the next item nearly fills
    // the post-residual but leaves a gap in the 1..=6 band, and the fleet
    // has few open bins, deepen the reward to force tight two-item chains
    // instead of leaving mid-sized residuals for uncertain future items.
    if next_item_size > 0 && post_residual > next_item_size {
        let chain_gap = post_residual - next_item_size;
        if (1..=6).contains(&chain_gap) && open_bins_count <= 5 {
            score -= (7.0 - chain_gap as f64) * (2.0 + 1.5 * progress);
        }
    }

    // Mutation: mid-stream residual capping — bins whose post-residual
    // exceeds both the next item and 1.4x the mean residual are likely to
    // strand space mid-stream; push items toward tighter bins instead.
    if next_item_size > 0
        && post_residual > next_item_size
        && (post_residual as f64) > mean_residual * 1.4
        && progress < 0.7
    {
        score += (post_residual as f64 - mean_residual * 1.4) * 0.35;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Sharper dead-space tiers: tiny gaps are nearly unfillable waste.
    if post_residual > 0 && post_residual < 8 {
        score += 80.0;
    } else if post_residual < 16 {
        score += 25.0;
    } else if post_residual < 25 {
        score += 8.0;
    }

    // Aggressive tight-fit rewards.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 4 {
        score -= 55.0;
    }

    // Two-step lookahead on the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size < post_residual {
            let future_gap = post_residual - next_item_size;
            if future_gap < 8 {
                score += 20.0;
            } else {
                score -= 10.0;
            }
        } else {
            score += post_residual as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Progress-driven consolidation pressure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 + progress);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 20.0 + 40.0 * progress;
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
        if item_size > 60 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        } else if fitting_bins_count == 1 && post_residual >= 8 {
            score += 35.0;
        }
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score += 15.0;
        }
        if fitting_bins_count > 0 {
            let item = item_size as f64;
            let cap = bin_capacity as f64;
            if item > 0.6 * cap && item > mean_residual + 8.0 {
                score -= 12.0 * progress;
            }
            let waste_ratio = (bin_residual - item_size) as f64 / cap;
            if waste_ratio > 0.30 && item / cap > 0.5 {
                score -= 18.0;
            }
            if waste_ratio > 0.45 && next_item_size > 0 && (bin_residual - item_size) < next_item_size {
                score -= 10.0 * (1.0 - progress);
            }
            if waste_ratio > 0.38 && (bin_residual - item_size) as f64 > mean_residual * 1.6 {
                score -= 14.0 * (1.0 - 0.5 * progress);
            }
            // Spawn-bias calibration — fresh bins are more attractive when the
            // fleet is fragmented (many open bins with large residuals) and the
            // item is big; scaled down as the stream matures.
            let fleet_fragmentation = open_bins_count as f64 * mean_residual / cap.max(1.0);
            if fleet_fragmentation > 1.5 && item / cap > 0.55 {
                score -= (fleet_fragmentation - 1.5) * 4.5 * (1.0 - 0.6 * progress);
            }
            // Crowded-fleet fresh-bin justification.
            let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
            if crowded > 3.0 && item / cap > 0.45 {
                score -= 8.0 + 6.0 * progress;
            }
            if mean_residual < 12.0 && item / cap > 0.7 {
                score -= 10.0 + 8.0 * progress;
            }
            if next_item_size > 0 && next_item_size > mean_residual as u32 && item > next_item_size {
                score -= 6.0 * (1.0 - progress);
            }
        }
    } else {
        // Prefer bins with residual close to the fleet mean (packable by future items).
        score += ((bin_residual as f64 - mean_residual).abs()) * 0.35;
        score -= progress * 8.0;
    }

    // Reward placements that move a bin's residual toward the fleet mean.
    let dr_before = (bin_residual as f64 - mean_residual).abs();
    let dr_after = (post_residual as f64 - mean_residual).abs();
    if dr_after < dr_before {
        score -= (dr_before - dr_after) * 0.4;
    }

    // Exact-fit bonus scaled by item size — big items filling a bin exactly
    // are the most valuable placements.
    if post_residual == 0 {
        score -= item_size as f64 * 0.15;
    }

    // Penalize leaving gaps that neither fit the next item nor any small
    // residual item, weighted by how much of the stream remains.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * (0.5 + 1.5 * progress);
    }

    // Prefer the bin whose post-residual best matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / bin_capacity.max(1) as f64) * 6.0;
    }

    // Perfect handoff chain reward, deepened late in the stream.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0 * (0.5 + progress);
    }

    // Avoid creating residuals in the "unfillable band".
    if post_residual > 0 && post_residual < 40 {
        let pr = post_residual as f64;
        if next_item_size == 0 || (next_item_size as f64) > pr {
            if pr < mean_residual - 3.0 && pr > 6.0 {
                score += (mean_residual - pr) * (0.6 + 0.8 * progress);
            }
        }
    }

    // Residual-pairing lookahead: next item leaves a tiny unfillable chain gap
    // — this bin is a near-perfect chain target.
    if next_item_size > 0 && post_residual > next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap <= 3 {
            score -= 12.0 + 10.0 * progress;
        }
    }

    // Late-stream compaction squeeze: leftover residual space is unlikely to
    // be reused near the end, so weight raw post_residual more heavily.
    if progress > 0.75 && post_residual > 0 {
        score += post_residual as f64 * (progress - 0.75) * 4.0;
    }

    // Discourage spreading small items off near-perfect packs.
    if bin_residual > item_size && bin_residual - item_size <= 2 && item_size <= 10 {
        score -= 8.0;
    }

    // Waste-fraction penalty on open bins.
    if bin_residual < bin_capacity && post_residual > 0 {
        let waste_frac = post_residual as f64 / bin_residual.max(1) as f64;
        score += waste_frac * 6.0 * (1.0 - progress);
    }

    // Density-ratio compaction — reward placements whose consumed
    // fraction of the bin's residual is high.
    if bin_residual < bin_capacity {
        let consumed_frac = item_size as f64 / bin_residual.max(1) as f64;
        if consumed_frac > 0.7 {
            score -= (consumed_frac - 0.7) * 30.0 * (1.2 - progress);
        }
    }

    // Near-exact residual targeting.
    if post_residual > 0 && post_residual <= 12 {
        score -= 5.0 * (1.0 - progress) + 3.0 * progress;
    }

    // Dead-gap oracle.
    if post_residual > 0 && post_residual < 30 {
        let pr = post_residual as f64;
        let next_blocks = next_item_size > 0 && (next_item_size as f64) > pr;
        if next_blocks && pr < mean_residual * 0.8 {
            score += (mean_residual * 0.8 - pr) * (0.5 + progress);
        }
    }

    // Residual ladder smoothing.
    if post_residual > 0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
    }

    // Two-item lookahead chain with bin pressure.
    if next_item_size > 0 && next_item_size == post_residual && open_bins_count > 4 {
        score -= 8.0;
    }

    // Stranded-gap accounting: triple-sealed gaps penalized quadratically.
    if post_residual > 0 && post_residual < 20 {
        let pr = post_residual as f64;
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Adaptive tight-band bonus: post-residual just above the next item
    // leaves a small reusable remainder; reward grows with open-bin count.
    if next_item_size > 0 && post_residual > next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover <= 5 && open_bins_count >= 2 {
            score -= (6.0 - leftover as f64) * (1.5 + 0.25 * open_bins_count.min(12) as f64);
        }
    }

    // Harmony coupling: consumed density combined with next-item reusability.
    if bin_residual < bin_capacity && next_item_size > 0 && post_residual >= next_item_size {
        let consumed_frac = item_size as f64 / bin_residual.max(1) as f64;
        let reusable = (post_residual - next_item_size) as f64;
        if consumed_frac > 0.5 && reusable <= 10.0 {
            score -= consumed_frac * (10.0 - reusable) * (0.6 + 0.8 * progress);
        }
    }

    // Endgame exactness: near the end, only near-exact fits matter.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Dead-space variance squeeze — escalate quadratically as stream advances.
    if post_residual > 0 && post_residual < 15 {
        let pr = post_residual as f64;
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Residual-continuity bonus.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if (pr - mean_residual).abs() <= 6.0 && pr >= 5.0 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Bin-count-aware exactness.
    if post_residual == 0 && open_bins_count > 6 {
        score -= 6.0 + open_bins_count.min(20) as f64 * 0.5;
    }

    // Residual-divisibility lookahead — a post-residual that is an integer
    // multiple of the next item enables a perfect chain fill.
    if next_item_size > 1 && post_residual > 0 && post_residual >= next_item_size {
        let q = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 && q >= 1 {
            score -= (q as f64).min(4.0) * 4.0 * (1.0 - 0.5 * progress);
        } else if rem <= 2 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Dead-space floor guard — residuals that no realistic item can ever
    // fill are permanent waste.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if ns > pr {
            let unreachable = (ns - pr).min(pr) as f64;
            score += unreachable * 0.35 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // Fragmentation-weighted consolidation — when the fleet is highly
    // fragmented, tighten the squeeze on placements that strand mid-sized
    // dead gaps, pushing items into bins they nearly fill instead of spreading.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let pr = post_residual as f64;
        let reusable = next_item_size > 0 && (next_item_size as u32) <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Residual-sweep pairing — prefer bins that keep the residual aligned
    // with the fleet's typical leftover scale, enabling multi-item sweeps.
    if next_item_size > 0 && post_residual > next_item_size {
        let sweep = post_residual - next_item_size;
        if sweep as f64 > mean_residual * 1.5 {
            score += (sweep as f64 - mean_residual * 1.5) * 0.25 * (1.0 - progress);
        }
    }

    // Late-stream seal-or-spawn arbitration: near the end, opening a new bin
    // is only justified if the item cannot nearly fill any open bin; deepen
    // the existing-bin preference so residual space is consumed first.
    if progress > 0.7 && bin_residual == bin_capacity && fitting_bins_count > 0 {
        let best_possible_gap = bin_residual.saturating_sub(item_size);
        if best_possible_gap <= 10 {
            score += 30.0 * (progress - 0.7) * 3.0;
        }
        // Mutation: extend the seal-bias earlier and widen the near-fill band,
        // calibrated by how reusable the best open-bin gap would be for the
        // next item — a reusable gap is a strong reason NOT to spawn.
        if progress > 0.55 {
            let band = 10.0 + 20.0 * (progress - 0.55);
            if (best_possible_gap as f64) <= band {
                let reusability = if next_item_size > 0 && best_possible_gap >= next_item_size {
                    1.0 - (best_possible_gap - next_item_size) as f64 / band
                } else {
                    0.5
                };
                score += (progress - 0.55) * 40.0 * reusability;
            }
        }
    }

    // Mutation: mid-stream gap-shape matching — when the item would leave a
    // post-residual that exactly matches the mean residual scale, the bin
    // becomes a prime target for the fleet's typical leftover items; reward
    // this alignment proportionally to remaining stream length.
    if bin_residual < bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let align = 1.0 - ((pr - mean_residual) / (mean_residual + 4.0)).abs().min(1.0);
