            score -= (align - 0.75) * 22.0 * (1.0 - 0.4 * progress);
        }
    }

    // Mutation: oversized-item spawn guard refinement — very large items
    // relative to the mean residual should spawn fresh bins more freely
    // mid-stream (avoid wedging them into partially filled bins that then
    // strand unusable slivers), but never when an open bin fits them exactly.
