            score += 35.0;
        }
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score += 15.0;
        }
        if fitting_bins_count > 0 {
            let item = item_size as f64;
            let cap = bin_capacity as f64;
            if item > 0.6 * cap && item > mean_residual + 8.0 {
                score -= 12.0 * progress;
            }
            let waste_ratio = (bin_residual - item_size) as f64 / cap;
            if waste_ratio > 0.30 && item / cap > 0.5 {
                score -= 18.0;
            }
            if waste_ratio > 0.45 && next_item_size > 0 && (bin_residual - item_size) < next_item_size {
                score -= 10.0 * (1.0 - progress);
            }
            if waste_ratio > 0.38 && (bin_residual - item_size) as f64 > mean_residual * 1.6 {
                score -= 14.0 * (1.0 - 0.5 * progress);
            }
            // Fresh-bin spawn-bias calibration: fleet fragmentation justifies
            // spawning for large items early, but late stream seals instead.
            let fleet_fragmentation = open_bins_count as f64 * mean_residual / cap.max(1.0);
            if fleet_fragmentation > 1.5 && item / cap > 0.55 {
                score -= (fleet_fragmentation - 1.5) * 4.5 * (1.0 - 0.6 * progress);
            }
            if mean_residual < 12.0 && item / cap > 0.7 {
                score -= 10.0 + 8.0 * progress;
            }
            // Late-stream seal-or-spawn arbitration: opening a new bin is only
            // justified if the item cannot nearly fill any open bin.
            if progress > 0.7 {
                let best_possible_gap = bin_residual.saturating_sub(item_size);
                if best_possible_gap <= 10 {
                    score += 90.0 * (progress - 0.7);
                }
            }
        }
    } else {
        // Prefer bins with residual close to the fleet mean (packable by future items).
        score += ((bin_residual as f64 - mean_residual).abs()) * 0.35;
        score -= progress * 8.0;
    }

    // Reward placements that move a bin's residual toward the fleet mean.
    let dr_before = (bin_residual as f64 - mean_residual).abs();
    let dr_after = (post_residual as f64 - mean_residual).abs();
    if dr_after < dr_before {
        score -= (dr_before - dr_after) * 0.4;
    }

    // Exact-fit bonus scaled by item size.
    if post_residual == 0 {
        score -= item_size as f64 * 0.15;
        if open_bins_count > 6 {
            score -= 6.0 + open_bins_count.min(20) as f64 * 0.5;
        }
    }

    // Penalize leaving gaps that neither fit the next item nor any small
    // residual item, weighted by how much of the stream remains.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * (0.5 + 1.5 * progress);
    }

    // Prefer the bin whose post-residual best matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / bin_capacity.max(1) as f64) * 6.0;
    }

    // Perfect handoff chain reward, deepened late in the stream.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0 * (0.5 + progress);
        if open_bins_count > 4 {
            score -= 8.0;
        }
    }

    // Avoid creating residuals in the "unfillable band".
    if post_residual > 0 && post_residual < 40 {
        let pr = post_residual as f64;
        if next_item_size == 0 || (next_item_size as f64) > pr {
            if pr < mean_residual - 3.0 && pr > 6.0 {
                score += (mean_residual - pr) * (0.6 + 0.8 * progress);
            }
        }
    }

    // Residual-pairing lookahead: next item leaves a tiny unfillable chain gap.
    if next_item_size > 0 && post_residual > next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap <= 3 {
            score -= 12.0 + 10.0 * progress;
