            }
        }
    }

    // Near-exact residual targeting.
    if post_residual > 0 && post_residual <= 12 {
        score -= 5.0 * (1.0 - progress) + 3.0 * progress;
    }

    // Dead-gap oracle: penalize post-residuals sealed against next item and fleet mean.
    if post_residual > 0 && post_residual < 30 {
        let pr = post_residual as f64;
        let next_blocks = next_item_size > 0 && (next_item_size as f64) > pr;
        if next_blocks && pr < mean_residual * 0.8 {
            score += (mean_residual * 0.8 - pr) * (0.5 + progress);
        }
    }

    // Residual ladder smoothing.
    if post_residual > 0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        } else if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Stranded-gap accounting: triple-sealed gaps penalized quadratically.
    if post_residual > 0 && post_residual < 20 {
        let pr = post_residual as f64;
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Fragmentation-weighted consolidation: when the fleet is highly
    // fragmented, tighten the squeeze on placements that strand mid-sized
    // dead gaps the next item cannot reuse.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let pr = post_residual as f64;
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Dead-space floor guard — residuals that no realistic item can ever
    // fill are permanent waste.
    if post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if ns > pr {
            let unreachable = (ns - pr).min(pr) as f64;
            score += unreachable * 0.35 * (0.3 + 0.7 * (1.0 - progress));
        }
    }

    // Mutation: quadratic dead-space curvature with fill-efficiency gradient —
    // combine the parent's waste curvature with a fleet-mean fill comparison
    // so consolidation pressure compounds with open-bin count.
    if post_residual > 0 && post_residual < 20 {
        let pr = post_residual as f64;
        score += (20.0 - pr) * (20.0 - pr) * 0.12 * (0.6 + 0.8 * progress);
    }
    if bin_residual < bin_capacity && bin_residual > 0 {
        let fill = item_size as f64 / bin_residual as f64;
        let mean_fill = 1.0 - mean_residual / bin_capacity.max(1) as f64;
        if fill > mean_fill {
            score -= (fill - mean_fill) * 18.0 * (0.5 + open_bins_count.min(12) as f64 * 0.05);
        }
    }

    // Mutation: seal-avoidance with divisibility escape — slivers below
    // mean_residual/3 are penalized late, unless the next item exactly
    // chains into them.
    if post_residual > 0 && progress > 0.5 {
        let sliver = mean_residual / 3.0;
        let chained = next_item_size > 0 && post_residual % next_item_size == 0;
        if (post_residual as f64) < sliver && !chained {
            score += (sliver - post_residual as f64) * (1.0 + 2.0 * (progress - 0.5));
        }
    }

    score
}

