        let sliver = mean_residual / 3.0;
        if (post_residual as f64) < sliver {
            score += (sliver - post_residual as f64) * (1.0 + 2.0 * (progress - 0.5));
        }
    }

    // Mutation: quadratic dead-space curvature on tiny stranded gaps,
    // sharpening the parent's linear tiers with progress weighting.
    if post_residual > 0 && post_residual < 20 {
        let pr = post_residual as f64;
        score += (20.0 - pr) * (20.0 - pr) * 0.12 * (0.6 + 0.8 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
