        if item_size > 60 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        } else if fitting_bins_count == 1 && post_residual >= 8 {
            score += 35.0;
        }
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score += 15.0;
        }
        if fitting_bins_count > 0 {
            let item = item_size as f64;
            let cap = bin_capacity.max(1) as f64;
            if item > 0.6 * cap && item > mean_residual + 8.0 {
                score -= 12.0 * progress;
