    let score = (post_residual as f64) * 0.95;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward if the next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            // reward proportional to how snugly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit: penalize leftover dead space that is too small to be useful
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 150.0; // tiny unusable fragment
            } else {
                score += 0.5 * dead;
            }
        }
    } else {
        // last item: only the immediate fit matters
        score += 0.3 * post_residual as f64;
    }

    // Reward bins with below-average residual (tighter bins get priority for filling)
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if the item is huge relative to
    // typical residuals and many bins are already open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize new bin by default; discount the penalty for large items late in the stream
        score += 400.0 - 250.0 * item_frac * progress;
        // If next item is also large, a fresh bin is more attractive
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 100.0;
        }
    }

    // Slight preference for keeping open-bin count low early on
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

