        }
        if consumed_frac > 0.55 && consumed_frac < 0.7 {
            score -= (consumed_frac - 0.55) * 12.0 * (1.0 - progress);
        }
    }

    // Near-exact residual targeting.
    if post_residual > 0 && post_residual <= 12 {
        score -= 5.0 * (1.0 - progress) + 3.0 * progress;
    }

    // Dead-gap oracle: penalize sealed gaps below typical reusable residual.
    if post_residual > 0 && post_residual < 30 {
        let next_blocks = next_item_size > 0 && (next_item_size as f64) > pr;
        if next_blocks && pr < mean_residual * 0.8 {
            score += (mean_residual * 0.8 - pr) * (0.5 + progress);
        }
    }

    // Residual ladder smoothing.
    if post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
        if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Stranded-gap accounting: triple-sealed gaps penalized quadratically.
    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze — escalate quadratically as stream advances.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness: near the end, only near-exact fits matter.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation — in a fragmented fleet,
    // non-reusable mid-band gaps are punished harder.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction — prefer placements whose post-residual
    // can absorb both the next item and a typical follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze — when the fleet is tight, tiny sealed gaps
    // are pure waste; punish proportionally below the achievable mean.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 0.9 * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Mutation (gen 11): dead-space budget ledger — track the total residual
    // mass across the fleet; when it's low, any placement that leaves a
    // sub-threshold gap in a large-residual bin wastes proportionally more
    // of the remaining budget, so push such bins toward exact closure.
    if bin_residual < bin_capacity && post_residual > 0 {
        let fleet_residue = mean_residual * open_bins_count.max(1) as f64;
        if fleet_residue < cap_f * 1.5 {
            let seal_shortfall = (10.0 - pr).max(0.0);
            score += seal_shortfall * 0.6 * (1.0 - progress) * (1.5 - fleet_residue / (cap_f * 1.5));
        }
        // Exact-closure orbit: bins whose residual is within 2 of the item
        // should almost always be closed now; deepened late.
        if br - item_f <= 2.0 {
            score -= 18.0 + 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is barely consumed.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space quadratically (waste grows superlinearly).
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 0.06 * pr * pr / bin_capacity as f64;
    } else {
        // Perfect closure is excellent.
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward heavily; if next item can't use the residual, penalize.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 18.0 - 0.15 * gap;
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 0.25 * over;
        }
        // If next item also fits in this bin's current residual, mild bonus
        // (keeps optionality open elsewhere).
        if next_item_size <= bin_residual {
            score -= 4.0;
        }
    } else {
        // Last item: closure strongly preferred.
        score -= 15.0;
    }

    // Last-chance dynamics: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate handling: opening a bin is expensive early (many items
    // remain to fill it), cheap late. Scale penalty by remaining stream fraction.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    let remaining = 1.0 - progress;
    if bin_residual == bin_capacity {
        // Reward opening a new bin when existing residuals are large and unusable,
        // penalize when open bins fit well.
        score += 20.0 * remaining + 2.0 * open_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin is natural.
        score -= 0.15 * item_size as f64;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If no other bin fits (fitting_bins_count==1 means only the new bin),
        // opening is mandatory: soften penalty.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    // Global state: prefer filling bins with below-average residual (balance),
    // and prefer packing into bins when many bins are open (consolidation).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 2.0;
        }
        score += 0.5 * open_bins_count as f64 * fit_ratio;
    }

    // Time horizon: as stream ends, tighten packing (favor small post-residual more).
    score += progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

