        let competition = (fitting_bins_count as f64).min(8.0);
        score -= 4.0 * (1.0 - competition / 10.0) * (0.5 + 0.5 * (1.0 - progress));
    }

    // Mutation (gen 12): awkward-gap triage — residuals in the 17..=35 band
    // rarely match item sizes (items ≤ 100, but mid-sized residuals between
    // half-capacity and mean are the classic dead zone). Penalize leaving
    // such gaps when the next item cannot use them, unless the bin is nearly
    // empty (large residual = still flexible).
    if post_residual >= 17 && post_residual <= 35 {
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        if !next_fits {
            let deadness = 1.0 - (pr - 17.0) / 18.0;
            score += deadness * 14.0 * (0.4 + 0.6 * progress);
        }
    }

    // Mutation (gen 12): second-item chain verification — when the next item
    // fits with a leftover that itself matches the fleet mean, the placement
    // seeds a two-step chain; reward proportionally to fleet tightness.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = pr - next_item_size as f64;
        if (after_next - mean_residual).abs() <= 3.0 && after_next > 0.0 {
            score -= 6.0 * (1.0 - after_next / cap_f) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * (1.0 - norm_pr);
    score -= 30.0 * coupling * (0.5 + progress);
    // Penalize large residuals late in the stream (dead space less recoverable)
    score += 20.0 * norm_pr * norm_pr * progress * progress;
    // Reward tight fits, stronger as stream advances
    score -= (item_size as f64 / cap) * (1.0 + 3.0 * progress) * 8.0;
    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }
    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 + 8.0 * progress;
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }
    // New-bin candidate: prefer opening a new bin early or when fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / cap) < 0.35;
        if poor_fit || open_bins_count == 0 {
            score -= 12.0 * (1.0 - progress);
        } else {
            score += 10.0 + 15.0 * progress;
        }
    }
    // Spread factor: mildly favor bins deviating from mean residual (diversity of sizes)
    score += 0.05 * (pr - mean_residual).abs();
    score
}

