    // Residual-entropy squeeze — when the fleet is tight (low mean residual),
    // tiny sealed gaps are pure waste.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 0.9 * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Mutation (gen 12): residual-balance arbitration — when several bins can
    // fit the item, prefer the one whose post-residual leaves a gap closest
    // to half the next item's size, enabling a two-step chain fill; slight
    // sharpening of the best-fit tiebreak for large items.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let chain_res = pr - next_item_size as f64;
        let half_next = next_item_size as f64 * 0.5;
        if chain_res > 0.0 && chain_res <= half_next {
            score -= (half_next - chain_res) * 0.8 * (0.3 + 0.7 * progress);
        }
    }

    // Mutation (gen 12): big-item priority seal — large items should never
    // leave a large non-reusable gap when any open bin fits them tightly.
    if item_size > 50 && post_residual > 0 && post_residual < 10 {
        score -= 10.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions (1/8 steps).
    let eighth = (cap / 8.0).max(1.0);
    let class = (post_residual as f64 / eighth).floor(); // 0..=8

    // Reward small, "clean" post-residuals (near-zero or near-perfect fills).
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize dead space that no future item can plausibly fill:
    // dead space is bad if post_residual < smallest plausible item chunk.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Modulo logic: residuals that are multiples of common item sizes (10, 20, 25, 50)
    // are more "usable" — reward them.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 4.0;
    }
    if pr % 50 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits: the tighter, the better
            score -= 10.0 * (1.0 - (pr - next_item_size) as f64 / cap);
            // harmonic class match: post_residual class equals next_item class
            let nclass = (next_item_size as f64 / eighth).floor();
            if nclass == class {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; slightly penalize unless residual is tiny
            if pr > 15 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline score so it
    // only wins when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        // early in stream or many open bins: opening new bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        if open_bins_count > 8 {
            score -= 5.0;
        }
    } else {
        // Prefer fuller bins: reward proximity of bin_residual usage to capacity.
        let used_frac = 1.0 - bin_residual as f64 / cap;
        score -= 10.0 * used_frac;
    }

    // Mean residual coupling: if this bin's residual is far below the mean
    // (it's one of the fullest), prefer it.
    let resid_diff = mean_residual - bin_residual as f64;
    if resid_diff > 0.0 {
        score -= 2.0 * resid_diff.min(30.0) / 10.0;
    }

    // Small tie-break toward exact harmonic classes 0 and 8 (empty or full).
    if class == 0.0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
