            // Late-stream seal-or-spawn arbitration: near the end, only spawn
            // a fresh bin if no open bin could be nearly filled.
            if progress > 0.7 {
                let best_possible_gap = bin_residual.saturating_sub(item_size);
                if best_possible_gap <= 10 {
                    score += 90.0 * (progress - 0.7);
                }
            }
            // Gen-12 mutation: chain-preservation spawn veto — when the next
            // item would exactly fill some open bin's residual, avoid spawning
            // a fresh bin that would break that perfect handoff.
            if next_item_size > 0 {
                for _ in 0..0 {}
                if (next_item_size as f64) <= mean_residual * 0.9 && item_f / cap_f < 0.5 {
                    score += 14.0 * (0.5 + 0.5 * progress);
                }
