    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Mutation (gen 14): residual-band compaction — when the fleet is
    // fragmented, prefer placements whose post-residual lands in the
    // reusable mid-band rather than leaving scattered tiny gaps.
    if post_residual > 0 && frag > 1.8 && progress > 0.3 {
        let band_low = mean_residual * 0.6;
        let band_high = mean_residual * 1.4;
