            score += (band_low - pr) * 0.55 * (0.4 + 0.6 * progress);
        } else if pr <= band_high {
            score -= (band_high - pr) * 0.35 * (1.0 - 0.4 * progress);
        }
    }

    // Mutation (gen 14): large-item anchor — big items opening a fresh bin
    // when few bins fit them prevents scattering across many bins.
    if bin_residual == bin_capacity && item_f / cap_f > 0.75 && fitting_bins_count > 0 && mean_residual < item_f {
        score -= 14.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction remains?
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Classify post_residual into harmonic bands of capacity.
    let frac = pr / cap;
    if frac <= 0.10 {
        score -= 40.0; // near-perfect fill, tiny dead space
    } else if frac <= 0.25 {
        score -= 15.0;
    } else if frac <= 0.50 {
        score += 10.0;
    } else {
        score += 25.0; // wasteful large residual
    }

    // Modulo-10 class of post_residual: items sizes are multiples of 10
    // in classic streams; residual matching next item's class is valuable.
    let pr_class = post_residual % 10;
    let next_class = if next_item_size > 0 { next_item_size % 10 } else { 0 };
    if next_item_size > 0 && next_item_size <= post_residual {
        // Lookahead: can next item also fit here?
        score -= 30.0;
        // Extra reward if residual classes align (both multiples of 10, etc.)
        if pr_class == next_class {
            score -= 20.0;
        }
        // Harmonic division: residual is a multiple of next item size
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: this residual is likely dead space.
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).min(10.0) * 2.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins
    // are all poor fits (their scores will be high due to large residuals).
    if bin_residual == bin_capacity {
        score += 80.0 + mean_residual * 0.3;
    }

    // Late in stream: push toward tighter packing of remaining bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

