    if post_residual > 0 && post_residual < mean_residual * 0.55 && mean_residual < 30.0 {
        let frag_mod = 1.0 + 0.4 * (frag.min(4.0) / 4.0);
        score += (mean_residual * 0.55 - pr) * 0.25 * frag_mod * (0.5 + 0.5 * progress);
    }

    // Mutation (gen 14): exact next-item residual match earns a
    // fragmentation-scaled bonus, reinforcing chain-building when the fleet
    // has many partially-filled bins competing for future items.
    if next_item_size > 0 && post_residual == next_item_size && open_bins_count >= 3 {
        score -= 4.0 + 0.6 * (open_bins_count.min(15) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    } else {
        // Larger residuals are less harmful; mild reward for tight fits
        score -= (post_residual as f64).sqrt() * 0.5;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open bins pressure: penalize spreading across many bins when a tight fit exists
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.5 * progress);

    // Mean residual coupling: prefer bins whose residual is close to item size (good fit)
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.4;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New bin candidate: penalize unless item is large relative to capacity
    // or no good fit exists (post_residual large means poor fit elsewhere)
    if bin_residual == bin_capacity {
        let base = 15.0 + 0.2 * open_bins_count as f64;
        // discourage new bin when lookahead item could fill leftover space
        if next_item_size > 0 && post_residual >= next_item_size {
            score += base - 8.0;
        } else {
            score += base;
        }
        // late in stream, prefer reusing open bins
        score += progress * 10.0;
    }

    // Lookahead synergy: if the item exactly fills bin so next item fits a fresh bin, fine.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // dead space relative to lookahead
    }

    score
}

