        // Mutation: harmonic density bonus with a gentle knee for mid-density fills.
        if consumed_frac > 0.55 && consumed_frac < 0.7 {
            score -= (consumed_frac - 0.55) * 12.0 * (1.0 - progress);
        }
        // Gen-15 mutation: super-linear density reward near the packing
        // ceiling — pushes residual variance down by sharpening the
        // preference for the densest feasible placement.
        if consumed_frac > 0.85 {
            score -= (consumed_frac - 0.85) * (consumed_frac - 0.85) * 60.0;
