    // non-reusable mid-band gaps are punished harder.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Mutation: two-item lookahead compaction — prefer placements whose
    // post-residual can absorb both the next item and a typical follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Mutation (gen 7): residual-entropy squeeze.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 0.9 * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Gen-15 mutation: last-slot exactness — when few items remain, reward
    // placements whose post-residual matches the next item exactly with
    // extra weight, since each saved bin near the end is final.
    if progress > 0.9 && next_item_size > 0 && post_residual >= next_item_size {
        let exact = (post_residual == next_item_size) as f64;
        score -= exact * 25.0 + (1.0 - exact) * ((post_residual - next_item_size) as f64) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize very small post-residuals only if the next item cannot use them,
    // reward them if the lookahead item fits exactly (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead fits after this placement: reward residual that matches next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 / (1.0 + slack);
        } else {
            // Dead space for the next item: penalize small unusable leftovers.
            score += 0.5 * post_residual as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins whose residual is closest to the item (best fit).
        score += 0.3 * (bin_residual as f64 - item_size as f64);
    }

    // Prefer using bins with below-average residual (consolidate emptier bins).
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Early in the stream, be picky (penalize loose fits) to preserve large residuals;
    // late in the stream, accept imperfection to close bins out.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 0.25 * post_residual as f64;
    score -= t * 10.0 * fit_ratio;

    // When many bins are open, encourage filling existing ones rather than spreading.
    if open_bins_count > 3 {
        score += 2.0 * (open_bins_count as f64).ln() * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive if item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let openness = fitting_bins_count as f64;
        let pressure = item_size as f64 / bin_capacity as f64;
        score += 30.0 * openness - 45.0 * pressure;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // fresh bin can also host the next item
        }
    }

    score
}

