    // items remain, a sealed gap is more likely to be filled by something,
    // so dead-space penalties scale with remaining capacity of the stream;
    // near the end, sealed gaps become permanent and are punished harder.
    let items_left = if total_items > step_index { total_items - step_index } else { 0 };
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3 * (if items_left > total_items / 4 { 0.5 } else { 1.5 });
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fits less aggressively (keep bins flexible);
    // later, drive hard toward small residuals to close bins out.
    let tightness = 1.0 + 2.5 * progress * progress;
    score -= tightness * (cap - pr) * 0.5;

    // Smooth penalty for unusable dead space: residual too small for any
    // plausible future item (min size 1..100 unknown, so penalize very small
    // and very large residuals smoothly via a quadratic bowl).
    let dead = (norm_pr - 0.15).powi(2);
    score += 40.0 * dead * (1.0 + progress);

    // Lookahead coupling: reward residuals that can still fit the next item,
    // penalize when the next item just barely won't fit.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr - nx).max(0.0) / cap;
        score -= 20.0 * fits_next;
        let miss = ((nx - pr).max(0.0) / cap).powi(2);
        score += 30.0 * miss;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for proliferating bins vs. mean residual state.
    score += 0.02 * (open_bins_count as f64) - 0.05 * mean_residual * progress;

    // New-bin candidate: keep it neutral-to-slightly-appealing only when
    // existing residuals are poor (high mean residual, low progress flexibility).
    if bin_residual == bin_capacity {
        let openness = (mean_residual / cap).powi(2);
        score = cap + 10.0 - 30.0 * openness - 20.0 * progress * norm_pr;
    }

    score
}

