        let dev = (pr - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
        if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Stranded-gap accounting: triple-sealed gaps penalized quadratically.
    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze — escalate quadratically as stream advances.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness: near the end, only near-exact fits matter.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation — in a fragmented fleet,
    // non-reusable mid-band gaps are punished harder.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction — prefer placements whose post-residual
    // can absorb both the next item and a typical follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze — when the fleet is tight (low mean residual),
    // tiny sealed gaps are pure waste; reward near-exact chain fits.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 0.9 * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: bucket post_residual into deciles of capacity (1..=100)
    let class = (post_residual * 10) / bin_capacity; // 0..=9
    let next_class = (next_item_size * 10) / bin_capacity;

    // Base: prefer tight fits; dead space scaled superlinearly
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * frac * frac;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize unusable slivers: post_residual below smallest plausible item
        if post_residual < 10 {
            score += 40.0;
        }
        // Harmonic coupling: reward when next item's class matches post_residual class
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
            // Bonus if next item would exactly fill remaining space
            if next_item_size == post_residual {
                score -= 30.0;
            }
        } else if next_item_size > post_residual {
            // Next item can't use this residual: mild penalty proportional to class mismatch
            score += 5.0 + (next_class as f64 - class as f64).abs() * 2.0;
        }
    }

    // Integer-division thresholds on post_residual (harmonic bands)
    let band = post_residual / 20; // 0..=4
    score -= match band {
        0 => 15.0, // residual < 20: very tight, good
        1 => 8.0,  // 20..39
        2 => 0.0,  // 40..59
        3 => -4.0, // 60..79: roomy bin, lower priority
        _ => -8.0, // 80+: nearly empty, deprioritize
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large and no open bin fits well (large item, many open bins with fragmented space)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 85.0
            + 20.0 * (1.0 - progress)
            - 0.5 * item_size as f64
            + (open_bins_count as f64).sqrt() * 3.0;
        // If this bin is the only fitting option, opening a new bin is fine
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Large next item: keep space available in a fresh bin
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Slight preference for filling bins with residual below mean (compactness pressure)
    if (post_residual as f64) < mean_residual {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
