            let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
            if crowded > 3.0 && item / cap_f > 0.45 {
                score -= 8.0 + 6.0 * progress;
            }
            if mean_residual < 12.0 && item / cap_f > 0.7 {
                score -= 10.0 + 8.0 * progress;
            }
            if next_item_size > 0 && next_item_size as f64 > mean_residual && item > next_item_size as f64 {
                score -= 6.0 * (1.0 - progress);
            }
            // Mutation: item-to-mean affinity — spawning is justified when the
            // item matches the fleet's typical residual scale closely.
            if (item - mean_residual).abs() < 3.0 && waste_ratio > 0.25 {
                score -= 9.0 * (1.0 - progress);
            }
            // Late-stream seal-or-spawn arbitration — near the end, only spawn
            // a fresh bin if no open bin could be nearly filled.
            if progress > 0.7 {
                let best_possible_gap = bin_residual.saturating_sub(item_size);
                if best_possible_gap <= 10 {
                    score += 90.0 * (progress - 0.7);
                }
            }
