    // are pure waste; penalize heavily the smaller the leftover gap.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual <= 25 {
            // small gaps are hard to fill later
            score += 15.0 * (1.0 - post_residual as f64 / 25.0);
        } else if post_residual >= 80 {
            // nearly empty bin placement is wasteful unless nothing else fits
            score += 5.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 50.0;
    }

    // Reward tight fits relative to residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

