    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            score += 12.0 + mean_residual * 0.05; // discourage wasting open space
        }
    }

    // Lookahead: if next item could exactly fill this bin's post_residual, reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
