    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        if crowded > 3.0 && item_f / cap_f > 0.45 {
            score -= 8.0 + 6.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (dead-space penalty is superlinear near zero).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize small, hard-to-fill leftovers (fragmentation risk).
    if post_residual > 0 && post_residual < 12 {
        score += 10.0 - 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: bonus if the next item can still fit in the post-residual space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Penalize leaving a residual that just barely fails the next item.
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 15.0 {
                score += 4.0 + 0.4 * miss;
            }
        }
    }

    // Global state: if mean residual is high and this bin is above-average full,
    // favor filling it (consolidate space); time horizon scales exploration.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let rel_full = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    if rel_full > mean_residual / (bin_capacity as f64) {
        score -= 3.0 * (1.0 - progress) * (rel_full - mean_residual / bin_capacity as f64);
    } else {
        score += 2.0 * progress * (mean_residual / bin_capacity as f64 - rel_full);
    }

    // Many open bins: discourage spreading; few open bins: allow exploration.
    score += 0.35 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when no good fit exists or item is large.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        let poor_alternatives = if fitting_bins_count <= 1 { 12.0 } else { 0.0 };
        let big_item = if item_size > bin_capacity / 2 { 8.0 } else { 0.0 };
        score += 30.0 + desperation + poor_alternatives + big_item - 10.0 * progress;
    }

    score
}

