        }
    }

    // Dead-space variance squeeze.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 0.9 * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Gen-16 mutation: dead-space ratio targeting — when the item consumes
    // most of the bin but leaves a residual that no plausible future item
    // (below the fleet mean) can use, penalize proportionally to the
    // fraction of the bin that becomes permanently sealed. Conversely,
    // reward placements whose sealed fraction is near zero.
    if bin_residual < bin_capacity && post_residual > 0 {
        let sealed_frac = pr / cap_f;
        let next_cannot_use = next_item_size == 0 || (next_item_size as f64) > pr;
        if next_cannot_use && sealed_frac > 0.04 {
            score += sealed_frac * 55.0 * (0.35 + 0.65 * progress);
        } else if !next_cannot_use && sealed_frac < 0.02 {
            score -= 10.0 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-16 mutation: bin-capacity-relative residual ladder — replace the
    // absolute small-gap tiers with capacity-scaled tiers so large-capacity
    // streams punish proportionally more dead space, while tiny residuals
    // remain strongly sealed.
    if post_residual > 0 {
        let rel = pr / cap_f;
        if rel < 0.03 {
            score -= 18.0 * (0.6 + 0.4 * progress);
        } else if rel > 0.35 && next_item_size > 0 && (next_item_size as f64) > pr {
            score += rel * 30.0 * (0.4 + 0.6 * progress);
        }
    }

    // Gen-16 mutation: second-fit lookahead — when more than one open bin
    // fits, prefer the one whose post-residual still fits a hypothetical
    // item of size `mean_residual` (fleet-typical filler), sealing chains.
    if fitting_bins_count > 1 && post_residual > 0 && (mean_residual as u32) <= post_residual {
        score -= 4.0 + 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
