        if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Stranded-gap accounting: triple-sealed gaps penalized quadratically.
    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze — escalate quadratically as stream advances.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness: near the end, only near-exact fits matter.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation — in a fragmented fleet,
    // non-reusable mid-band gaps are punished harder.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze — tiny sealed gaps in a tight fleet are waste.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 0.9 * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Mutation (gen 17): chained-fill depth bonus — reward placements whose
    // post-residual is an exact multiple of the next item, since repeated
    // identical items can drain the bin completely (compounding chain).
    if next_item_size > 1 && post_residual >= next_item_size {
        let rem = post_residual % next_item_size;
        if rem == 0 {
            let depth = post_residual / next_item_size;
            if depth >= 2 {
                score -= (depth.min(6) as f64) * 3.5 * (0.6 + 0.4 * progress);
            }
        }
        // Mutation (gen 17): residual-band harmonizer — placements that leave
        // the post-residual inside the fleet's densest reusable band are
        // preferred, tightening the residual variance sigma.
        if pr >= mean_residual * 0.7 && pr <= mean_residual * 1.3 {
            score -= 4.0 * (1.0 - 0.3 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + t * t * 3.0 + t * (1.0 - t) * 2.0;
    score *= poly;

    // Reward tight fits: quadratic bonus for small normalized residual
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * item_size as f64 * 0.5;

    // Penalize residuals that are too small to be useful later (dead space)
    let dead = if next_item_size > 0 && (pr as u32) < next_item_size { 1.0 } else { 0.0 };
    score += dead * pr as f64 * (0.5 + t);

    // Reward saving space when the next item fits
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= (pr - next_item_size as f64).abs().min(20.0) * 0.3;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // Mild penalty for spreading across many bins when residuals are high
    score += (open_bins_count as f64).ln().max(0.0) * mean_residual * 0.02 * (1.0 - t);

    // Smooth preference to fill nearly-full bins harder as stream progresses
    score -= (bin_residual as f64 / cap) * t * 5.0;

    score
}

