        score += 60.0; // tiny unusable sliver -> strong penalty
    } else if post_residual >= 10 && post_residual < 25 {
        score += 18.0; // awkward gap, hard to fill
    } else if post_residual >= 25 && post_residual < 50 {
        score += 4.0; // moderately fillable
    }
    // Perfect or near-perfect fits get a reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Open-bin pressure: the more bins are open, the more we prefer filling
    // existing bins over opening new ones.
    let pressure = open_bins_count as f64 * 1.5;
    score += pressure;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
