        score -= 5.0 * (1.0 - progress) + 3.0 * progress;
    }

    // Dead-gap oracle: penalize sealed gaps below typical reusable residual.
    if post_residual > 0 && post_residual < 30 {
        let next_blocks = next_item_size > 0 && (next_item_size as f64) > pr;
        if next_blocks && pr < mean_residual * 0.8 {
            score += (mean_residual * 0.8 - pr) * (0.5 + progress);
        }
    }

    // Residual ladder smoothing.
    if post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
        if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Stranded-gap accounting: triple-sealed gaps penalized quadratically.
    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze — escalate quadratically as stream advances.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness: near the end, only near-exact fits matter.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation — in a fragmented fleet,
    // non-reusable mid-band gaps are punished harder.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction — prefer placements whose post-residual
    // can absorb both the next item and a typical follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze — tiny sealed gaps in a tight fleet are pure
    // waste; punish proportionally to how far they sit below the mean.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 0.9 * (0.6 + 0.6 * progress);
    }
    // Chain-compounding reward: near-exact next-item handoff on a decent fill.
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Mutation (gen 18): residual-band matching — when the post-residual
    // matches a common reusable band, favor it proportionally to how many
    // open bins exist (more bins = more chances to reuse that band later).
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let band = (post_residual - next_item_size) as f64;
        if band <= 6.0 && open_bins_count >= 3 {
            score -= (6.0 - band) * 0.8 * open_bins_count.min(10) as f64 * 0.4;
        }
    }

    // Mutation (gen 18): waste-floor guard — never leave a residual smaller
    // than the smallest plausible item (1..=3) unless it is exactly zero.
    if post_residual > 0 && post_residual <= 3 && progress < 0.9 {
        score += 9.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference for tight fits: penalize residual above item size itself.
    score += 0.35 * (post_residual as f64 - item_size as f64).max(0.0);

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        let diff = (pr - ni).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect 2-chain: item + next item fill bin
        } else if ni < pr {
            score -= 25.0 * (1.0 - diff / 100.0); // next item fits, reward closeness
        } else {
            // next item won't fit here; penalize large leftover gaps
            score += 0.5 * (pr - (100.0 - ni)).max(0.0);
        }
    }

    // Reward relative fill vs mean residual across open bins.
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-attractive only when
    // no open bin offers a good fit (post_residual large relative to item).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - waste); // prefer new bin when item is large
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= bin_capacity as f64 {
            score -= 15.0; // fresh bin can host a clean 2-item chain
        }
    }

    // Late in stream: consolidate; avoid spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (open_bins_count as f64 / 10.0).min(1.0) * (post_residual as f64 / 100.0);

    score
}

