pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-full fills
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space leftovers harder than moderate ones (nonlinear)
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 12.0 * (1.0 - pr / bin_capacity as f64).powi(3);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
