    // Lookahead coupling: if next item fits in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 25.0 * chain_quality;
    } else if next_item_size > post_residual && post_residual > 0 {
        // leftover too small for next item: penalize, more so early when bins are cheap to keep open
        score += 8.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Scarcity of fitting bins
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: many open bins with high mean residual -> consolidate, favor filling bins
    score += 0.15 * mean_residual;
    score -= 1.5 * open_bins_count as f64;

    // Time horizon: late in stream, prefer tightest packing (reduce score for good fits)
    score -= 20.0 * progress * fit_ratio;

    // New-bin candidate handling: empty bin gets a mild default penalty unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 45.0 - 25.0 * progress;
        // If item is large relative to capacity, opening a fresh bin is more attractive
        score -= 0.2 * item_size as f64;
    }

    // Slight preference for bins with residual close to item (waste minimization)
    score += 0.05 * (bin_residual as f64 - item_size as f64).abs();

    score
}

