}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base cost: wasted space, weighted non-linearly by stream progress.
    // Early on, waste is cheap (bins will be reused); later, tight packing matters.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    let mut score = pr * (0.6 + 0.8 * progress_weight);

    // Smooth penalty for residuals too small to be useful: quadratic "dead zone" curve.
    let dead_threshold = 0.12 + 0.10 * progress;
    let deadness = ((dead_threshold - x).max(0.0) / dead_threshold).powi(2);
    score += 25.0 * deadness * (1.0 + progress);

    // Reward near-perfect fits with a smooth Gaussian-like bump around small residuals.
    let tightness = (-(x * x) / (2.0 * 0.04)).exp();
    score -= 30.0 * tightness * (1.0 + 0.5 * progress);

    // Lookahead coupling: if the next item fits the post-residual, reward this placement
    // (chaining items in the same bin). Smooth interaction term.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).max(0.0);
        let chain = fit_gap / cap;
        score -= 12.0 * (1.0 - chain) * (1.0 - chain) * (1.0 - 0.5 * progress);
        // Penalize if post-residual barely misses the next item (blocks future chaining)
        let near_miss = ((pr - nx) as f64).abs();
        if near_miss < 8.0 {
            score += 6.0 * (1.0 - near_miss / 8.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // New-bin candidate handling: make fresh bins mildly attractive early, expensive late,
    // scaled by how scattered existing residuals are.
    if bin_residual == bin_capacity {
        let scatter = (mean_residual - pr).abs() / cap;
        let openness = (1.0 - progress).powi(2);
        score = 40.0 + 60.0 * progress - 15.0 * openness * scatter - 10.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 5.0)));
    } else {
        // Mild bonus for bins whose residual is close to the mean (keeps residuals uniform)
        score -= 4.0 * (1.0 - ((mean_residual - pr).abs() / cap).min(1.0));
    }

    // Global non-linear coupling: polynomial interaction of residual and progress
    score += 5.0 * x * x * (1.0 - progress) - 3.0 * x * progress * progress;

    score
}

