        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze — escalate quadratically as stream advances.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness: near the end, only near-exact fits matter.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation — in a fragmented fleet,
    // non-reusable mid-band gaps are punished harder.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction — prefer placements whose post-residual
    // can absorb both the next item and a typical follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze: punish tiny sealed gaps in a tight fleet.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 0.9 * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Mutation (gen 20): residual-band harmonization — when several open
    // bins compete, prefer the one whose post-residual lands in the
    // "reusable band" [next_item_size, next_item_size + mean_residual/2],
    // so leftovers stay absorbable by the following stream rather than
    // scattering into odd-sized fragments.
    if next_item_size > 0 && fitting_bins_count > 1 && post_residual >= next_item_size {
        let band_hi = next_item_size as f64 + (mean_residual * 0.5).max(4.0);
        if (pr <= band_hi) && open_bins_count > 2 {
            score -= 4.0 * (1.0 - 0.3 * progress);
        }
    }

    // Mutation (gen 20): fleet-level dead-space budget — when the total
    // open residual across the fleet is large relative to remaining
    // demand, tighten the squeeze on any placement that leaves a gap
    // the next item cannot absorb.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && open_bins_count > 3 {
        score += (next_item_size - post_residual) as f64 * 0.3 * (open_bins_count.min(10) as f64 / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness reward: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else if post_residual > 0 {
            // Dead space if next item can't use it: mild penalty scaled by stream position.
            let t = step_index as f64 / total_items.max(1) as f64;
            score += 8.0 + 12.0 * t;
        }
    } else {
        // Last item: only tightness matters, strongly.
        score += post_residual as f64 * 1.5;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Crowding: with many open bins, prefer consolidating into low-residual bins.
    if open_bins_count > 1 {
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    // New-bin candidate: only attractive when nothing fits well or bin is nearly full.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / total_items.max(1) as f64;
        let desperate = fitting_bins_count == 0
            || (mean_residual < item_size as f64 * 0.5 && open_bins_count > 0);
        if desperate {
            score -= 30.0;
        } else {
            // Penalize opening new bins when decent fits exist; grows late in stream.
            score += 55.0 + 45.0 * t;
        }
    }

    // Prefer filling bins that are already heavily used (low residual before placement).
    score += 0.15 * (bin_capacity as f64 - bin_residual as f64) * -1.0;

    // Small-scale tie-breaker against residual size for near-equal options.
    score += (post_residual % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
