    }

    // Dead-space variance squeeze — escalate quadratically as stream advances.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness: near the end, only near-exact fits matter.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 0.9 * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Mutation (gen 20): exact-cover pair anticipation — when the post-residual
    // equals the sum of the next item and a small follow-up, the bin becomes a
    // perfect two-step target; reward this compounding chain, weighted by how
    // contested the fleet is (few fitting bins = higher reward).
    if next_item_size > 0 && post_residual > next_item_size {
        let pair_gap = post_residual - next_item_size;
        if pair_gap <= 12 && pair_gap >= 1 {
            let contest = (fitting_bins_count.max(1) as f64).recip();
            score -= pair_gap as f64 * (0.9 + 1.6 * progress) * (1.0 + contest * 2.0);
        }
    }

    // Mutation (gen 20): residual-band lock — bins whose post-residual lands in
    // the "golden band" (within 2 of the fleet mean, above the min item size)
    // stay maximally reusable; reward keeping at least one such bin alive.
    if post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        if dev <= 2.0 && pr > 4.0 && open_bins_count >= 3 {
            score -= 6.0 + 4.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; late, penalize dead space more strongly
    let progress_coupling = pr * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += progress_coupling;

    // Dead-space penalty: quadratic in unusable residual relative to next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if pr < next {
            let gap = (next - pr) / cap;
            score += gap * gap * cap * (1.0 + progress);
        } else {
            // reward bins that leave room for the lookahead item
            score -= 3.0 * (1.0 - ((pr - next) / cap));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across too many bins relative to mean residual
    score += (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap) * 2.0;

    // Reward filling bins closer to capacity (cubic shaping)
    score -= (1.0 - norm_pr).powi(3) * item_size as f64 * 0.3;

    // New-bin candidate: neutral-ish score so it's chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score = cap * (1.0 - 0.5 * progress) + 5.0;
    }

    score
}

