        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // New mutation: fleet-balance arbitration — when open bins are few and
    // mean residual is high, gently discourage opening new bins (consolidate
    // into existing slack); when bins are many and slack is thin, tilt the
    // other way. This adapts spawn pressure to fleet state.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let fleet_slack = mean_residual * open_bins_count as f64;
        if fleet_slack > item_f * 2.0 {
            score += 8.0 * (1.0 - progress);
        } else if fleet_slack < item_f * 0.8 {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // New mutation: exact-fill synergy — reward placements that leave a
    // post-residual equal to a common small-item size band (1..=5) since
    // unknown streams frequently contain tiny closing items.
    if post_residual >= 1 && post_residual <= 5 && progress < 0.9 {
        score -= 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: residuals near multiples of common item
    // sizes are more reusable. Reward post_residual that divides cleanly into
    // plausible item sizes (harmonic classes).
    let pr = post_residual;
    if pr > 0 {
        let mut harm = 0.0f64;
        for class in [10u32, 20, 25, 30, 40, 50, 60, 70, 80, 100] {
            if class <= pr {
                let rem = pr % class;
                if rem == 0 {
                    harm += 4.0;
                } else if rem <= 5 {
                    harm += 2.0;
                }
            }
        }
        score -= harm;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (perfect 2-item packing).
    if next_item_size > 0 && next_item_size == pr {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // next item fits but leaves another residual: judge that leftover's
        // harmonic quality
        let nr = pr - next_item_size;
        let mut harm2 = 0.0f64;
        for class in [10u32, 20, 25, 30, 40, 50] {
            if nr % class == 0 && nr > 0 {
                harm2 += 2.0;
            }
        }
        score -= harm2;
        score += nr as f64 * 0.1;
    } else if next_item_size > 0 && next_item_size > pr {
        // post_residual too small for next item: penalize small dead space
        // that can't serve the lookahead (harmonic trap)
        if pr < 10 {
            score += 25.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are all poor for the item. Penalize the fresh bin
    // mildly so it only wins when open bins have big dead space.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
    }

    // Tight fit reward: near-perfect packing.
    if pr == 0 {
        score -= 20.0;
    } else if pr <= 5 {
        score -= 10.0;
    } else if pr <= 10 {
        score -= 5.0;
    }

    // Stream progression: later in the stream, prefer closing bins tightly
    // over spreading (fewer open bins at the end).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 2.0;

    // Prefer bins below mean residual (denser bins) slightly.
    score += (mean_residual - bin_residual as f64).max(-20.0) * 0.05;

    score
}

