    // near-miss dead space; nudge selection away from them.
    if post_residual > 0 {
        for boundary in [10u32, 20u32, 25u32, 40u32, 50u32] {
            if post_residual < boundary && boundary - post_residual <= 2 && boundary - post_residual > 0 {
                score += (boundary - post_residual) as f64 * 2.2 * (0.4 + 0.6 * progress);
            }
        }
    }

    score
}

