    // threshold now adapts to the next item so gaps just below it are
    // punished relative to how much of the next item they could have held.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 0.9 * (0.6 + 0.6 * progress);
