    // barely fails to seal a bin (post_residual in 1..=3), the leftover is
    // almost certainly dead weight; punish proportionally to stream age,
    // unless the next item can still absorb it.
    if post_residual >= 1 && post_residual <= 3 {
        let next_covers = next_item_size > 0 && next_item_size <= post_residual;
        if !next_covers {
            score += 9.0 * (0.35 + 0.65 * progress);
        }
    }

    // Gen-21 mutation: residual-target coupling between fleet state and
    // placement choice — in fleets with high residual variance, prefer
    // placements that push post_residual toward the fleet mean more
    // aggressively, since variance compounds waste across bins.
    if post_residual > 0 && dr_after < dr_before {
        let variance_pressure = frag.min(4.0);
        score -= (dr_before - dr_after) * 0.25 * variance_pressure * 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for the smallest plausible item) are heavily penalized.
    let min_item = 1.0f64;
    let dead_zone = 20.0f64; // gaps below this are rarely reusable
    if (post_residual as f64) < dead_zone {
        // Sharper penalty the smaller the gap (quadratic ramp).
        let gap = dead_zone - post_residual as f64;
        score += 3.0 * gap * gap / dead_zone;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // If the leftover can exactly host the lookahead item, reward it strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // leftover still usable by next item: mild reward
        score -= 5.0;
    } else if next_item_size > 0 {
        // leftover cannot host next item: mild penalty scaled by gap
        score += 0.2 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        // extra reward if fit is decent
        if (post_residual as f64) >= dead_zone {
            score -= 10.0;
        }
    }

    // Open-bin pressure: discourage proliferating bins when many are open.
    score += 0.5 * open_bins_count as f64;

    // A brand-new empty bin is only attractive when current bins fit poorly:
    // penalize the new-bin candidate by its wasted capacity vs mean residual.
    if bin_residual == bin_capacity {
        score += 0.3 * mean_residual;
        // but if all fits would create dead space, opening a bin is fine:
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Slightly favor bins whose residual is below the mean (tighter bins first).
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    // Mild stream-progression term: later in the stream, be more conservative
    // about dead space (waste matters more when the stream is nearly done).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight normalization to keep scales comparable.
    score -= item_size as f64 * 0.05;

    score
}

