        }
    }

    // Residual ladder smoothing.
    if post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
        if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Stranded-gap accounting.
    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 1.1 * (0.7 + 0.5 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Dead-space ratio squeeze — punish placements whose post-residual is a
    // large fraction of the bin's remaining space and cannot chain with the
    // next item; reward high fill fraction on the residual.
    if bin_residual < bin_capacity && post_residual > 0 {
        let dead_ratio = pr / br.max(1.0);
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        if dead_ratio > 0.45 && !chains {
            score += (dead_ratio - 0.45) * 22.0 * (0.5 + 0.5 * progress);
        }
        if dead_ratio < 0.2 {
            score -= (0.2 - dead_ratio) * 15.0 * (0.6 + 0.6 * progress);
        }
    }

    // Gen-21 mutation: chain-exactness bonus — when the post-residual equals
    // the next item size AND the current fill consumed most of the residual,
    // this bin closes out perfectly with zero waste; reward compounding.
    if next_item_size > 0 && post_residual == next_item_size && bin_residual < bin_capacity {
        let fill = item_f / br.max(1.0);
        score -= 10.0 * fill * (0.5 + 0.5 * progress);
    }

    // Gen-21 mutation: multi-chain divisibility — if the post-residual can
    // hold the next item twice (or more) with zero remainder, prefer it as
    // it seals the bin over successive steps without dead space.
    if next_item_size > 1 && post_residual >= 2 * next_item_size && post_residual % next_item_size == 0 {
        score -= 6.0 * (1.0 - 0.4 * progress);
    }

    // Gen-21 mutation: mean-residual alignment for mid-size gaps — gaps
    // sitting just above the next item but near the fleet mean are the most
    // reusable; reward them quadratically as the stream matures.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let mean_dev = (pr - mean_residual).abs();
        if mean_dev < 3.0 {
            score -= (3.0 - mean_dev) * 4.0 * (0.3 + 0.7 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (best-fit core).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot hold the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 6.0 + 0.25 * (post_residual as f64);
        } else if post_residual >= next_item_size {
            // Reward bins that can still host the next item.
            score -= 4.0;
        }
        // Perfect pair: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: prefer zero residual strongly.
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: keep it attractive only when open bins are messy.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual.max(0.0);
        // If open bins are quite full already, opening a fresh bin is reasonable.
        score += 10.0 + 0.5 * avg_waste;
        // Early in the stream, opening bins is cheap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
        // Too many open bins relative to items: discourage fragmentation.
        if open_bins_count as f64 > (step_index as f64).max(1.0) * 0.6 {
            score += 12.0;
        }
        // But if no open bin fits well (large post_residual elsewhere), allow new bin.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 14.0;
        }
    }

    // Mild reward for using bins that are already partially filled (avoid bin sprawl).
    if bin_residual != bin_capacity {
        score -= 2.0 + 0.02 * open_bins_count as f64;
    }

    // Penalize leaving residuals in the awkward 20..40 range (hard to fill later).
    if post_residual >= 20 && post_residual <= 40 {
        score += 5.0;
    }

    // Global balance: if mean residual is high, prefer consolidating into full bins.
    if mean_residual > 40.0 && bin_residual < 40 {
        score -= 3.0;
    }

    score
}

