    // couples fine-grained fitting with chain anticipation.
    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size && (post_residual as f64) < mean_residual * 0.6 {
            score += (next_item_size - post_residual) as f64 * 0.8 * (1.0 - progress);
        }
        if post_residual == next_item_size * 2 || post_residual == next_item_size * 3 {
            score -= 10.0 * (0.6 + 0.4 * progress);
        }
    }

    score
}

