        if gap_to_next <= 2.0 {
            score -= 9.0 * (0.5 + 0.5 * progress);
        } else if pr < next_item_size as f64 && pr > (next_item_size as f64) * 0.5 {
            score += 4.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: penalize residual, with non-linear shaping over stream progress
    let mut score = r * (1.0 + 0.5 * progress * progress);

    // Smooth non-linear coupling: quadratic residual term scaled by progress
    score += norm_r * norm_r * 30.0 * (0.5 + progress);

    // Reward tight fits, stronger as stream progresses
    let tightness = 1.0 - norm_r;
    score -= tightness * tightness * item_size as f64 * (0.5 + progress);

    // Penalize dead space that next item cannot use (smooth interaction)
    let next_fit = (next_item_size as f64 - r).max(0.0);
    score += (next_fit / cap) * 40.0 * (1.0 - progress * 0.5);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    }

    // Mild penalty for spreading across many bins relative to mean residual
    score += (open_bins_count as f64 / (1.0 + mean_residual)) * 2.0;

    // New-bin candidate: neutral-ish, slightly discouraged unless residual is large
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
