    // Prefer the bin whose post-residual best matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / cap_f) * 6.0;
    }

    // Perfect handoff chain reward, deepened late in the stream.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0 * (0.5 + progress);
        if open_bins_count > 4 {
            score -= 8.0;
        }
    }

    // Avoid creating residuals in the unfillable band.
    if post_residual > 0 && post_residual < 40 {
        if next_item_size == 0 || (next_item_size as f64) > pr {
            if pr < mean_residual - 3.0 && pr > 6.0 {
                score += (mean_residual - pr) * (0.6 + 0.8 * progress);
            }
        }
    }

    // Residual-pairing lookahead: near-perfect chain target.
    if next_item_size > 0 && post_residual > next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap <= 3 {
            score -= 12.0 + 10.0 * progress;
        }
        if chain_gap <= 5 && open_bins_count >= 2 {
            score -= (6.0 - chain_gap as f64) * (1.5 + 0.25 * open_bins_count.min(12) as f64);
        }
        if chain_gap as f64 > mean_residual * 1.5 {
            score += (chain_gap as f64 - mean_residual * 1.5) * 0.25 * (1.0 - progress);
        }
    }

    // Residual-divisibility lookahead — perfect chain fill enabled.
    if next_item_size > 1 && post_residual > 0 && post_residual >= next_item_size {
        let q = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= (q as f64).min(4.0) * 4.0 * (1.0 - 0.5 * progress);
        } else if rem <= 2 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Late-stream compaction squeeze.
    if progress > 0.75 && post_residual > 0 {
        score += pr * (progress - 0.75) * 4.0;
    }

    // Discourage spreading small items off near-perfect packs.
    if bin_residual > item_size && bin_residual - item_size <= 2 && item_size <= 10 {
        score -= 8.0;
    }

    // Waste-fraction penalty on open bins.
    if bin_residual < bin_capacity && post_residual > 0 {
        let waste_frac = pr / br.max(1.0);
        score += waste_frac * 6.0 * (1.0 - progress);
    }

    // Density-ratio compaction.
    if bin_residual < bin_capacity {
        let consumed_frac = item_f / br.max(1.0);
        if consumed_frac > 0.7 {
            score -= (consumed_frac - 0.7) * 30.0 * (1.2 - progress);
        }
        // Harmony coupling: density combined with next-item reusability.
        if next_item_size > 0 && post_residual >= next_item_size {
            let reusable = (post_residual - next_item_size) as f64;
            if consumed_frac > 0.5 && reusable <= 10.0 {
                score -= consumed_frac * (10.0 - reusable) * (0.6 + 0.8 * progress);
            }
        }
        // Harmonic density bonus with a gentle knee for mid-density fills.
        if consumed_frac > 0.55 && consumed_frac < 0.7 {
            score -= (consumed_frac - 0.55) * 12.0 * (1.0 - progress);
        }
    }

    // Near-exact residual targeting.
    if post_residual > 0 && post_residual <= 12 {
        score -= 5.0 * (1.0 - progress) + 3.0 * progress;
    }

    // Dead-gap oracle: penalize sealed gaps below typical reusable residual.
    if post_residual > 0 && post_residual < 30 {
        let next_blocks = next_item_size > 0 && (next_item_size as f64) > pr;
        if next_blocks && pr < mean_residual * 0.8 {
            score += (mean_residual * 0.8 - pr) * (0.5 + progress);
        }
    }

    // Residual ladder smoothing.
    if post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
        if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Stranded-gap accounting: triple-sealed gaps penalized quadratically.
    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze — escalate quadratically as stream advances.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness: near the end, only near-exact fits matter.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation — in a fragmented fleet,
    // non-reusable mid-band gaps are punished harder.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction — prefer placements whose post-residual
    // can absorb both the next item and a typical follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze: when the fleet is tight, tiny sealed gaps
    // are pure waste; punish proportionally below achievable mean.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 0.9 * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Mutation (gen 22): tight-fit compaction coupling — combine quadratic
    // dead-space curvature with next-item lookahead so placements that both
    // consume most of the residual and leave a next-item-absorbable gap
    // earn a compounding bonus, sharpening mid-stream consolidation.
    if bin_residual < bin_capacity && bin_residual > 0 && post_residual > 0 {
        let fill = item_f / br;
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        if fill > 0.65 && next_fits {
            let leftover = post_residual - next_item_size;
            score -= (fill - 0.65) * 22.0 * (1.0 - leftover as f64 / cap_f) * (0.5 + progress);
        }
        // Sliver-seal penalty: gaps below mean_residual/3 late in the stream
        // are effectively permanent waste.
        if progress > 0.5 {
            let sliver = mean_residual / 3.0;
            if pr < sliver {
                score += (sliver - pr) * (1.0 + 2.0 * (progress - 0.5));
            }
        }
        // Fill-efficiency gradient vs fleet-mean fill ratio.
        let mean_fill = 1.0 - mean_residual / cap_f;
        if fill > mean_fill {
            score -= (fill - mean_fill) * 18.0 * (0.5 + open_bins_count.min(12) as f64 * 0.05);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of post_residual: exact-fill classes are golden ----
    let c = bin_capacity as f64;
    // Class 0: perfect fit (post_residual == 0) -> huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space harmonic penalty: residual in "unusable" small classes
        // Items are >= 1, but small residuals (< 10) are near-dead unless a
        // tiny next item exists. Penalize per harmonic band.
        let pr = post_residual as f64;
        let band = (pr / 10.0).floor(); // 0..=9 harmonic deciles
        // Dead-space weight grows for low bands (small unusable leftovers)
        let dead_weight = match band as u32 {
            0 => 25.0,           // 0..=9: nearly dead
            1 => 12.0,           // 10..=19
            2 => 6.0,            // 20..=29
            3 => 3.0,
            4 => 1.5,
            _ => 0.5,
        };
        // If lookahead item can use the leftover, cancel the dead penalty
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= dead_weight * 0.9;
        } else {
            score += dead_weight;
        }

        // Modulo-class bonus: post_residual sharing residue classes with
        // common item sizes (divisible by 5 / 10) is more reusable.
        if post_residual % 10 == 0 {
            score -= 8.0;
        } else if post_residual % 5 == 0 {
            score -= 4.0;
        }
    }

    // ---- Tightness: prefer bins where item occupies a large fraction of residual ----
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_frac * fill_frac; // quadratic reward for tight fits

    // ---- Last-chance bin: strongly prefer using it before opening a new one ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; make it attractive only when the
        // current item is large relative to capacity (better to start fresh
        // than fragment a bin) and many bins are already open.
        let item_frac = item_size as f64 / c;
        score = 45.0 - 25.0 * item_frac;
        // Late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If many fitting bins exist, discourage opening a new one
        score += 5.0 * (fitting_bins_count as f64).min(6.0);
    }

    // ---- Lookahead coupling: if next item exactly fills post_residual, big bonus ----
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize if next item won't fit anywhere near this residual class
        if next_item_size > post_residual {
            // next item must go elsewhere; slight penalty proportional to gap
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // ---- Mean-residual context: if this bin's residual is far below mean,
    //      it's a laggard bin; prefer filling laggards to consolidate ----
    let this_residual = post_residual as f64;
    if mean_residual > 0.0 && this_residual < mean_residual {
        score -= 0.3 * (mean_residual - this_residual);
    }

    score
}

