        score -= 15.0 * (0.5 + progress);
        if open_bins_count > 4 {
            score -= 8.0;
        }
    }

    // Avoid creating residuals in the unfillable band.
    if post_residual > 0 && post_residual < 40 {
        if next_item_size == 0 || (next_item_size as f64) > pr {
            if pr < mean_residual - 3.0 && pr > 6.0 {
                score += (mean_residual - pr) * (0.6 + 0.8 * progress);
            }
        }
    }

    // Residual-pairing lookahead.
    if next_item_size > 0 && post_residual > next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap <= 3 {
            score -= 12.0 + 10.0 * progress;
        }
        if chain_gap <= 5 && open_bins_count >= 2 {
            score -= (6.0 - chain_gap as f64) * (1.5 + 0.25 * open_bins_count.min(12) as f64);
        }
        if chain_gap as f64 > mean_residual * 1.5 {
            score += (chain_gap as f64 - mean_residual * 1.5) * 0.25 * (1.0 - progress);
        }
    }

    // Residual-divisibility lookahead.
    if next_item_size > 1 && post_residual > 0 && post_residual >= next_item_size {
        let q = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= (q as f64).min(4.0) * 4.0 * (1.0 - 0.5 * progress);
        } else if rem <= 2 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Late-stream compaction squeeze.
    if progress > 0.75 && post_residual > 0 {
        score += pr * (progress - 0.75) * 4.0;
    }

    // Discourage spreading small items off near-perfect packs.
    if bin_residual > item_size && bin_residual - item_size <= 2 && item_size <= 10 {
        score -= 8.0;
    }

    // Waste-fraction penalty.
    if bin_residual < bin_capacity && post_residual > 0 {
        let waste_frac = pr / br.max(1.0);
        score += waste_frac * 6.0 * (1.0 - progress);
    }

    // Density-ratio compaction with harmony couplings.
    if bin_residual < bin_capacity {
        let consumed_frac = item_f / br.max(1.0);
        if consumed_frac > 0.7 {
            score -= (consumed_frac - 0.7) * 30.0 * (1.2 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let reusable = (post_residual - next_item_size) as f64;
            if consumed_frac > 0.5 && reusable <= 10.0 {
                score -= consumed_frac * (10.0 - reusable) * (0.6 + 0.8 * progress);
            }
        }
        if consumed_frac > 0.55 && consumed_frac < 0.7 {
            score -= (consumed_frac - 0.55) * 12.0 * (1.0 - progress);
        }
    }

    // Near-exact residual targeting.
    if post_residual > 0 && post_residual <= 12 {
        score -= 5.0 * (1.0 - progress) + 3.0 * progress;
    }

    // Dead-gap oracle.
    if post_residual > 0 && post_residual < 30 {
        let next_blocks = next_item_size > 0 && (next_item_size as f64) > pr;
        if next_blocks && pr < mean_residual * 0.8 {
            score += (mean_residual * 0.8 - pr) * (0.5 + progress);
        }
    }

    // Residual ladder smoothing.
    if post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
        if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Stranded-gap accounting.
    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 0.9 * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Quadratic dead-space curvature.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - pr) * (20.0 - pr) * 0.10 * (0.6 + 0.8 * progress);
    }

    // Fill-efficiency gradient vs fleet-mean fill ratio.
    if bin_residual < bin_capacity && bin_residual > 0 {
        let fill = item_f / br;
        let mean_fill = 1.0 - mean_residual / cap_f;
        if fill > mean_fill {
            score -= (fill - mean_fill) * 18.0 * (0.5 + open_bins_count.min(12) as f64 * 0.05);
        }
    }

    // Sliver-seal avoidance late in the stream.
    if post_residual > 0 && progress > 0.5 {
        let sliver = mean_residual / 3.0;
        if pr < sliver {
            score += (sliver - pr) * (1.0 + 2.0 * (progress - 0.5));
        }
    }

    // Exact-chain multiplicity.
    if next_item_size > 1 && post_residual > 0 && post_residual >= next_item_size {
        let q = post_residual / next_item_size;
        if post_residual % next_item_size == 0 && q >= 2 {
            score -= (q as f64).min(5.0) * 3.5 * (0.6 + 0.6 * progress);
        }
    }

    // Next-item wedge guard.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let fleet_slack = mean_residual / cap_f;
        score += (next_item_size - post_residual) as f64 * fleet_slack * 1.2 * progress;
    }

    // Big-item spawn arbitration.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && item_f / cap_f > 0.8 {
        score -= 14.0 * (1.0 - 0.5 * progress);
    }

    // Mutation (gen 24): dual-fit lookahead — reward placements whose
    // post-residual can hold the next item AND still leave a gap the mean
    // residual could fill, compounding chain savings in tight fleets.
    if next_item_size > 0 && post_residual >= next_item_size && mean_residual > 1.0 {
        let after_next = pr - next_item_size as f64;
        if after_next >= mean_residual - 2.0 {
            score -= 6.0 + 8.0 * progress;
        }
        // Mutation (gen 24): reward bins whose post-residual is within the
        // reach band of the next item plus a small tolerance, enabling
        // slightly-oversized items to still chain.
        let tol = after_next + (mean_residual * 0.3).min(4.0);
        if after_next > 0.0 && after_next <= tol && fitting_bins_count > 2 {
            score -= 4.0 * (1.0 - progress);
        }
    }

    // Mutation (gen 24): fleet-level bin budget pressure — as the number of
    // open bins grows relative to remaining items, escalate the cost of
    // leaving moderate dead space, pushing items into tighter fits.
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    if remaining > 0.0 && open_bins_count as f64 > remaining * 0.35 && post_residual > 10 {
        score += (pr - 10.0) * 0.6 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead coupling ---
    if next_item_size > 0 {
        // Perfect match: post_residual exactly equals next item -> strong reward.
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward tight lookahead match (subtracted from score).
        score -= 18.0 * (1.0 - gap / bin_capacity as f64).max(0.0) * (bin_capacity as f64 - gap) / bin_capacity as f64;

        // If next item fits into post_residual, extra reward proportional to tightness.
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize large leftover dead space.
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: minimize final residual hard.
        score *= 1.5;
    }

    // --- Relative to mean residual: prefer bins tighter than average ---
    score -= 4.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // --- Last-chance bin bonus: only one bin fits; use it rather than open new ---
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is discouraged unless it enables a perfect 2-step chain
        // or no good fitting bin exists (large post_residual penalty elsewhere).
        let perfect_chain = next_item_size > 0
            && bin_capacity >= item_size + next_item_size
            && (bin_capacity - item_size - next_item_size) as f64 <= 10.0;
        if perfect_chain {
            score -= 15.0;
        } else {
            score += 8.0 + 6.0 * progress;
        }
    }

    // Slight preference for filling larger items into fuller bins.
    score -= 2.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

