    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 10.0 + open_bins_count.min(15) as f64 * 1.5 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Near-perfect fit reward
    if post_residual <= 5 {
        score -= 200.0 * (6 - post_residual) as f64;
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: reward bins whose residual can host the next item too
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 + 0.5 * next_item_size as f64;
    }
    // Penalize leaving a residual that just barely cannot fit the next item (dead zone)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Penalize large leftovers in small-residual regimes (waste awareness)
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += 0.3 * post_residual as f64 * tightness;

    // Global state: with many open bins, prefer consolidation (avoid opening new bins)
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins are open or late in stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 + 80.0 * progress + 5.0 * open_bins_count as f64;
        // but allow new bin if mean residual is small (all bins nearly full)
        score -= 3.0 * mean_residual;
    }

    // Prefer bins below mean residual (fill emptier bins first to compact them)
    if bin_residual != bin_capacity {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    score
}

