    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness: near the end, only near-exact fits matter.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation — in a fragmented fleet,
    // non-reusable mid-band gaps are punished harder.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction — prefer placements whose post-residual
    // can absorb both the next item and a typical follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze — when the fleet is tight (low mean residual),
    // tiny sealed gaps are pure waste.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 0.9 * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Mutation (gen 25): dead-space floor arbitration — among open bins, the
    // bin whose post-residual sits in the "unfillable band" (below the
    // smallest plausible item share, here approximated by mean_residual/3)
    // is punished progressively; bins escaping that band entirely get a
    // mild reward, sharpening the choice between near-equal fits.
    let dead_floor = (mean_residual / 3.0).max(2.0);
    if post_residual > 0 && pr < dead_floor && bin_residual < bin_capacity {
        score += (dead_floor - pr) * 2.2 * (0.5 + 0.7 * progress);
    } else if post_residual >= dead_floor && post_residual > 0 && pr < mean_residual {
        score -= 2.0 * (1.0 - progress);
    }

    // Mutation (gen 25): gap-shape continuity — reward placements whose
    // post-residual keeps a reusable band (>= next item and <= mean + slack)
    // so the gap stays serviceable for future mid-size items.
    if next_item_size > 0 && post_residual >= next_item_size {
        let band_hi = mean_residual + 12.0;
        if pr >= band_hi {
            score += (pr - band_hi) * 0.35 * (0.4 + 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, but with a smooth non-linear penalty
    // on very small residuals (dead space) and very large residuals (waste).
    let mut score = pr;

    // Non-linear polynomial coupling of post residual with stream progress.
    // Early on (progress ~ 0): tolerate larger residuals to keep bins flexible.
    // Later (progress ~ 1): aggressively minimize post residual (tight packing).
    let tightness = 0.5 + 0.5 * progress;
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep shape
    score += tightness * 60.0 * poly * x;
    score -= (1.0 - tightness) * 20.0 * (1.0 - poly) * (1.0 - x);

    // Reward filling a bin nearly exactly, smoothly scaled by progress.
    let perfect = (x <= 0.0) as i32 as f64;
    score -= 80.0 * perfect * (0.3 + 0.7 * progress);

    // Penalize dead space that no plausible next item can use: couple with
    // lookahead item size via a smooth interaction term.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).abs() as f64;
        let fit_quality = 1.0 - (gap / cap).min(1.0);
        score -= 25.0 * fit_quality * fit_quality;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress);
    }

    // Mild coupling with mean residual: prefer bins below average residual
    // (they are tighter) via smooth quadratic term.
    let diff = (mean_residual - bin_residual as f64) / cap;
    score += 15.0 * diff * diff - 10.0 * diff;

    // Encourage consolidating when many bins are open (smooth in open count).
    let oc = open_bins_count as f64;
    score += (oc / (oc + 5.0)) * 8.0 * (1.0 - poly);

    score
}

