        let chain_gap = post_residual - next_item_size;
        if chain_gap <= 3 {
            score -= 12.0 + 10.0 * progress;
        }
        if chain_gap <= 5 && open_bins_count >= 2 {
            score -= (6.0 - chain_gap as f64) * (1.5 + 0.25 * open_bins_count.min(12) as f64);
        }
        if chain_gap as f64 > mean_residual * 1.5 {
            score += (chain_gap as f64 - mean_residual * 1.5) * 0.25 * (1.0 - progress);
        }
    }

    if next_item_size > 1 && post_residual > 0 && post_residual >= next_item_size {
        let q = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= (q as f64).min(4.0) * 4.0 * (1.0 - 0.5 * progress);
        } else if rem <= 2 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    if progress > 0.75 && post_residual > 0 {
        score += pr * (progress - 0.75) * 4.0;
    }

    if bin_residual > item_size && bin_residual - item_size <= 2 && item_size <= 10 {
        score -= 8.0;
    }

    if bin_residual < bin_capacity && post_residual > 0 {
        let waste_frac = pr / br.max(1.0);
        score += waste_frac * 6.0 * (1.0 - progress);
    }

    if bin_residual < bin_capacity {
        let consumed_frac = item_f / br.max(1.0);
        if consumed_frac > 0.7 {
            score -= (consumed_frac - 0.7) * 30.0 * (1.2 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let reusable = (post_residual - next_item_size) as f64;
            if consumed_frac > 0.5 && reusable <= 10.0 {
                score -= consumed_frac * (10.0 - reusable) * (0.6 + 0.8 * progress);
            }
        }
        if consumed_frac > 0.55 && consumed_frac < 0.7 {
            score -= (consumed_frac - 0.55) * 12.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 && post_residual <= 12 {
        score -= 5.0 * (1.0 - progress) + 3.0 * progress;
    }

    if post_residual > 0 && post_residual < 30 {
        let next_blocks = next_item_size > 0 && (next_item_size as f64) > pr;
        if next_blocks && pr < mean_residual * 0.8 {
            score += (mean_residual * 0.8 - pr) * (0.5 + progress);
        }
    }

    if post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
        if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 0.9 * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    if post_residual > 0 && mean_residual < 30.0 {
        let floor = (mean_residual * 0.35).max(3.0);
        if pr < floor {
            score += (floor - pr) * 1.4 * (0.5 + 0.7 * progress);
        }
    }
    if post_residual > 0 && open_bins_count > 2 && mean_residual > 4.0 {
        let cluster = (pr - mean_residual).abs() / mean_residual;
        if cluster < 0.25 {
            score -= (0.25 - cluster) * 14.0 * (0.6 + 0.4 * progress);
        }
    }
    if post_residual > 0 && post_residual <= 5 && next_item_size > 0 && next_item_size > post_residual {
        score += (6.0 - pr) * 9.0 * (0.4 + 0.6 * progress);
    }

    // Mutation (gen 25): waste-floor escalation — the diagnosed weakness is
    // residual dead space. When the fleet's mean residual is small, any
    // leftover that cannot hold the next item is nearly permanent; punish it
    // proportionally to how much of the bin's remaining space it strands,
    // with a sharper knee as progress advances.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let stranded_frac = pr / br.max(1.0);
        score += stranded_frac * stranded_frac * 22.0 * (0.5 + 0.9 * progress);
    }

    // Mutation (gen 25): dual-item lookahead — reward placements whose
    // post-residual can still host the next item AND a plausible follow-up
    // (mean residual), keeping chains alive two steps ahead.
    if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 + mean_residual {
        score -= 10.0 * (0.6 + 0.6 * progress);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        let tail = post_residual - next_item_size;
        if tail as f64 >= mean_residual * 0.75 {
            score -= 4.0 * (1.0 - progress);
        }
    }

    // Mutation (gen 25): exact-closure arbitration — when multiple bins could
    // take the item, the one that closes fully should dominate; add a graded
    // bonus for how close post_residual is to zero relative to capacity.
    if post_residual > 0 && fitting_bins_count > 1 {
        let closeness = 1.0 - pr / cap_f;
        if closeness > 0.93 {
            score -= (closeness - 0.93) * 120.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10-unit classes.
    let post_class = post_residual / 10;
    let next_class = next_item_size / 10;

    // Base: reward tight fits (small post_residual).
    score = post_residual as f64 * 0.9;

    // Reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Harmonic coupling: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Reward proportionally when next item nests into this bin.
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * fit_ratio;
        // Penalize leaving a sliver the next item can't use.
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next < 10 {
            score += 8.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize dead space creation mildly.
        score += 6.0;
    }

    // Modulo-harmonic bonus: post_residual divisible by common item classes (10, 20, 25).
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0) {
        score -= 7.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when nothing fits well.
    if bin_residual == bin_capacity {
        // Penalize opening new bins generally, more so early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 20.0 * (1.0 - progress);
        // But if existing bins would leave large unusable residuals, new bin becomes viable.
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    } else {
        // Slight preference for bins tighter than average.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Class-distance penalty: mismatch between post class and next item class wastes space.
    if next_item_size > 0 && post_class > next_class {
        score += 2.0 * (post_class - next_class) as f64;
    }

    // Many open bins: encourage consolidation (closing bins out).
    if open_bins_count > 4 && post_residual < 20 {
        score -= 6.0;
    }

    score
}

