        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to item size
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
