        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze — escalate quadratically as stream advances.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness: near the end, only near-exact fits matter.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 0.9 * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Gen-26 mutation: residual-match arbitration among competing open bins.
    // When several bins fit, favor the one whose post-residual is closest to
    // the fleet mean of residuals — this keeps the residual distribution tight
    // and reduces the count of odd-sized dead gaps.
    if bin_residual < bin_capacity && fitting_bins_count > 1 && post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        score += dev * 0.15 * (0.5 + 0.5 * progress);
        // Gen-26: bonus for exact two-step closure — item + next item exactly
        // filling this bin's residual.
        if next_item_size > 0 && item_size + next_item_size == bin_residual {
            score -= 22.0 + 14.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect chain), penalize near-misses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let next = next_item_size as f64;

    if next > 0.0 {
        let diff = (post_residual as f64 - next).abs();
        if diff == 0.0 {
            // Perfect 2-step chain: strongly reward.
            score -= 40.0 + 20.0 * (1.0 - progress);
        } else if diff <= 5.0 {
            // Near-perfect chain: moderate reward.
            score -= 15.0 - diff * 2.0;
        } else {
            // Poor chain potential: penalize proportionally to mismatch.
            score += diff * 0.3;
        }
        // If the next item could also fit in the leftover, small bonus.
        if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // Leftover too small for next item: dead-space penalty scaled
            // by how much of the residual is wasted.
            score += (post_residual as f64) * 0.25;
        }
    }

    // Prefer bins whose residual is already small (tight packing).
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strong incentive to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item fits
    // perfectly or very few bins are open / stream is early.
    if bin_residual == bin_capacity {
        let perfect = item_size == bin_capacity;
        let early = progress < 0.2;
        if perfect {
            score -= 50.0;
        } else if early || open_bins_count == 0 {
            score -= 10.0;
        } else {
            // Penalize new bins more as the stream progresses.
            score += 15.0 + 20.0 * progress;
        }
    }

    // Slight preference to keep number of open bins low.
    score += open_bins_count as f64 * 0.05;

    score
}

