    // non-reusable mid-band gaps are punished harder.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction — prefer placements whose post-residual
    // can absorb both the next item and a typical follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze (refined gen 26): tiny sealed gaps below the
    // achievable mean are pure waste; punish proportionally, sharpened late.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * (0.9 + 0.5 * progress) * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Mutation (gen 26): exact-fill chain anticipation — when the next item
    // would seal this bin perfectly, the current placement is a chain link;
    // reward it more when the fleet is fragmented so sealing matters most.
    if next_item_size > 0 && post_residual == 0 && open_bins_count > 3 {
        score -= (open_bins_count.min(15) as f64) * 0.8 * (0.5 + 0.5 * progress);
    }

    // Mutation (gen 26): sub-mean residual guard — placements leaving a
    // residual just below the smallest plausible item (1..=3) are dead space
    // with no chain potential; punish with a hard tier.
    if post_residual > 0 && post_residual <= 3 && next_item_size > post_residual {
        score += 12.0 + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fit (residual exactly consumed) gets a large bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits in the post residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Chain compatibility: post residual can hold next item snugly.
        if post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate logic: penalize opening a new bin unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; relax when many bins are open with high mean residual.
        let mut penalty = 35.0;
        if open_bins_count > 0 {
            let waste_factor = mean_residual / bin_capacity as f64;
            // If open bins have lots of fragmented residual, new bin is more attractive.
            penalty -= 20.0 * waste_factor;
        }
        // Early in stream, be more willing to open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty -= 10.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 60 {
            penalty -= 8.0;
        }
        score += penalty.max(0.0);
    }

    // Penalize bins whose residual is much above the mean (underused bins) slightly,
    // to spread load toward balanced fills.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Small penalty for very small unusable post-residual gaps that waste capacity.
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    score
}

