    // Sharper dead-space tiers, tuned by stream progress.
    if post_residual > 0 && post_residual < 8 {
        score += 80.0 + 10.0 * progress;
    } else if post_residual < 16 {
        score += 25.0;
    } else if post_residual < 25 {
        score += 8.0;
    }

    // Tight-fit rewards, deepened slightly for large items.
    if post_residual == 0 {
        score -= 120.0 + item_f * 0.15;
        if open_bins_count > 6 {
            score -= 6.0 + open_bins_count.min(20) as f64 * 0.5;
        }
    } else if post_residual <= 4 {
        score -= 55.0;
    }

    // Two-step lookahead on the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size < post_residual {
            let future_gap = post_residual - next_item_size;
            if future_gap < 8 {
                score += 20.0;
            } else {
                score -= 10.0;
            }
        } else {
            score += pr * 0.25;
        }
    }

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Progress-driven consolidation pressure.
    score += open_bins_count as f64 * (1.0 + progress);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 20.0 + 40.0 * progress;
        if item_f > mean_residual {
            score -= 25.0;
        }
        if item_size > 60 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        } else if fitting_bins_count == 1 && post_residual >= 8 {
            score += 35.0;
        }
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score += 15.0;
        }
        if fitting_bins_count > 0 {
            let waste_ratio = (br - item_f) / cap_f;
            if item_f > 0.6 * cap_f && item_f > mean_residual + 8.0 {
                score -= 12.0 * progress;
            }
            if waste_ratio > 0.30 && item_f / cap_f > 0.5 {
                score -= 18.0;
            }
            if waste_ratio > 0.45 && next_item_size > 0 && (bin_residual - item_size) < next_item_size {
                score -= 10.0 * (1.0 - progress);
            }
            if waste_ratio > 0.38 && (br - item_f) > mean_residual * 1.6 {
                score -= 16.0 * (1.0 - 0.5 * progress);
            }
            if (item_f - mean_residual).abs() < 3.0 && waste_ratio > 0.25 {
                score -= 9.0 * (1.0 - progress);
            }
            let fleet_fragmentation = open_bins_count as f64 * mean_residual / cap_f;
            if fleet_fragmentation > 1.5 && item_f / cap_f > 0.55 {
                score -= (fleet_fragmentation - 1.5) * 4.5 * (1.0 - 0.6 * progress);
            }
            let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
            if crowded > 3.0 && item_f / cap_f > 0.45 {
                score -= 8.0 + 6.0 * progress;
            }
            if mean_residual < 12.0 && item_f / cap_f > 0.7 {
                score -= 10.0 + 8.0 * progress;
            }
            if next_item_size > 0 && next_item_size as f64 > mean_residual && item_f > next_item_size as f64 {
                score -= 6.0 * (1.0 - progress);
            }
            if progress > 0.7 {
                let best_possible_gap = bin_residual.saturating_sub(item_size);
                if best_possible_gap <= 10 {
                    score += 90.0 * (progress - 0.7);
                }
            }
            // Mutation (gen 27): fresh-bin spawn arbitration — a new bin is
            // justified when the best fitting open bin would leave a gap the
            // next item cannot absorb, but the fresh bin's post-residual can.
            if next_item_size > 0 {
                let fresh_gap = bin_capacity.saturating_sub(item_size);
                if fresh_gap >= next_item_size && fresh_gap.saturating_sub(next_item_size) <= 4 {
                    score -= 22.0 * (1.0 - 0.5 * progress);
                }
                if fresh_gap > 0 && fresh_gap < next_item_size {
                    score += 18.0;
                }
            }
            // Mutation (gen 27): big-item squeeze — very large items relative
            // to capacity deserve their own bin when the fleet is tight.
            if item_f / cap_f > 0.85 && mean_residual < 20.0 {
                score -= 14.0 + 10.0 * (1.0 - progress);
            }
        }
    } else {
        score += (br - mean_residual).abs() * 0.35;
        score -= progress * 8.0;
    }

    // Reward placements moving residual toward the fleet mean.
    let dr_before = (br - mean_residual).abs();
    let dr_after = (pr - mean_residual).abs();
    if dr_after < dr_before {
        score -= (dr_before - dr_after) * 0.4;
    }

    // Penalize gaps that neither fit the next item nor typical residuals.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * (0.5 + 1.5 * progress);
        let unreachable = (next_item_size as f64 - pr).min(pr);
        score += unreachable * 0.35 * (0.3 + 0.7 * (1.0 - progress));
    }

    // Prefer the bin whose post-residual best matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / cap_f) * 6.0;
    }

    // Perfect handoff chain reward, deepened late in the stream.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0 * (0.5 + progress);
        if open_bins_count > 4 {
            score -= 8.0;
        }
    }

    // Avoid creating residuals in the unfillable band.
    if post_residual > 0 && post_residual < 40 {
        if next_item_size == 0 || (next_item_size as f64) > pr {
            if pr < mean_residual - 3.0 && pr > 6.0 {
                score += (mean_residual - pr) * (0.6 + 0.8 * progress);
            }
        }
    }

    // Residual-pairing lookahead: near-perfect chain target.
    if next_item_size > 0 && post_residual > next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap <= 3 {
            score -= 12.0 + 10.0 * progress;
        }
        if chain_gap <= 5 && open_bins_count >= 2 {
            score -= (6.0 - chain_gap as f64) * (1.5 + 0.25 * open_bins_count.min(12) as f64);
        }
        if chain_gap as f64 > mean_residual * 1.5 {
            score += (chain_gap as f64 - mean_residual * 1.5) * 0.25 * (1.0 - progress);
        }
    }

    // Residual-divisibility lookahead — perfect chain fill enabled.
    if next_item_size > 1 && post_residual > 0 && post_residual >= next_item_size {
        let q = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= (q as f64).min(4.0) * 4.0 * (1.0 - 0.5 * progress);
        } else if rem <= 2 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Late-stream compaction squeeze.
    if progress > 0.75 && post_residual > 0 {
        score += pr * (progress - 0.75) * 4.0;
    }

    // Discourage spreading small items off near-perfect packs.
    if bin_residual > item_size && bin_residual - item_size <= 2 && item_size <= 10 {
        score -= 8.0;
    }

    // Waste-fraction penalty on open bins.
    if bin_residual < bin_capacity && post_residual > 0 {
        let waste_frac = pr / br.max(1.0);
        score += waste_frac * 6.0 * (1.0 - progress);
    }

    // Density-ratio compaction.
    if bin_residual < bin_capacity {
        let consumed_frac = item_f / br.max(1.0);
        if consumed_frac > 0.7 {
            score -= (consumed_frac - 0.7) * 30.0 * (1.2 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let reusable = (post_residual - next_item_size) as f64;
            if consumed_frac > 0.5 && reusable <= 10.0 {
                score -= consumed_frac * (10.0 - reusable) * (0.6 + 0.8 * progress);
            }
        }
        if consumed_frac > 0.55 && consumed_frac < 0.7 {
            score -= (consumed_frac - 0.55) * 12.0 * (1.0 - progress);
        }
    }

    // Near-exact residual targeting.
    if post_residual > 0 && post_residual <= 12 {
        score -= 5.0 * (1.0 - progress) + 3.0 * progress;
    }

    // Dead-gap oracle: penalize sealed gaps below typical reusable residual.
    if post_residual > 0 && post_residual < 30 {
        let next_blocks = next_item_size > 0 && (next_item_size as f64) > pr;
        if next_blocks && pr < mean_residual * 0.8 {
            score += (mean_residual * 0.8 - pr) * (0.5 + progress);
        }
    }

    // Residual ladder smoothing.
    if post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
        if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Stranded-gap accounting: triple-sealed gaps penalized quadratically.
    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze — escalate quadratically as stream advances.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness: near the end, only near-exact fits matter.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation — in a fragmented fleet,
    // non-reusable mid-band gaps are punished harder.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction — prefer placements whose post-residual
    // can absorb both the next item and a typical follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze: tiny sealed gaps below the achievable mean
    // are pure waste; punish proportionally, sharpened late.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * (0.9 + 0.5 * progress) * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Mutation (gen 26): exact-fill chain anticipation.
    if next_item_size > 0 && post_residual == 0 && open_bins_count > 3 {
        score -= (open_bins_count.min(15) as f64) * 0.8 * (0.5 + 0.5 * progress);
    }

    // Mutation (gen 26): sub-mean residual guard.
    if post_residual > 0 && post_residual <= 3 && next_item_size > post_residual {
        score += 12.0 + 8.0 * progress;
    }

    // Mutation (gen 27): dead-zone consolidation — when a placement leaves a
    // gap in the awkward 4..8 band that the next item cannot use, steer the
    // item toward bins whose post-residual stays above that dead zone or
    // seals exactly, reducing residual fragmentation late in the stream.
    if post_residual >= 4 && post_residual <= 8 && next_item_size > post_residual {
        score += 10.0 + 14.0 * progress;
    }
    if post_residual > 8 && next_item_size > 0 && next_item_size > post_residual
        && (post_residual as f64) >= mean_residual * 0.9 {
        score -= 6.0 * (0.4 + 0.6 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;

    // Base: waste term, non-linearly scaled by stream progress.
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Smooth polynomial coupling between post_residual and progress:
    // penalize mid-range residuals early, tiny residuals late.
    let coupling = post_norm * (1.0 - post_norm) * (1.0 - progress);
    score -= 30.0 * coupling;

    // Reward near-perfect fits more strongly as stream progresses.
    if post <= 2.0 {
        score -= 15.0 + 20.0 * progress;
    }

    // Penalize large dead space quadratically.
    if post_norm > 0.5 {
        score += 10.0 * (post_norm - 0.5) * (post_norm - 0.5) * cap * (0.5 + progress);
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a new bin only when no good fit exists.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score = 60.0 + 40.0 * scarcity * (1.0 - progress) - 5.0 * progress;
        if fitting_bins_count == 0 {
            score = -100.0;
        }
    }

    // Mild preference for bins tighter than average.
    score += 0.05 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity.max(1) as f64;
    let item_f = item_size as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;

    // Sharper dead-space tiers, tuned by stream progress.
    if post_residual > 0 && post_residual < 8 {
        score += 80.0 + 10.0 * progress;
    } else if post_residual < 16 {
        score += 25.0;
    } else if post_residual < 25 {
        score += 8.0;
    }

    // Tight-fit rewards, deepened slightly for large items.
    if post_residual == 0 {
        score -= 120.0 + item_f * 0.15;
        if open_bins_count > 6 {
            score -= 6.0 + open_bins_count.min(20) as f64 * 0.5;
        }
    } else if post_residual <= 4 {
        score -= 55.0;
    }

    // Two-step lookahead on the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size < post_residual {
            let future_gap = post_residual - next_item_size;
            if future_gap < 8 {
                score += 20.0;
            } else {
                score -= 10.0;
            }
        } else {
            score += pr * 0.25;
        }
    }

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Progress-driven consolidation pressure.
    score += open_bins_count as f64 * (1.0 + progress);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 20.0 + 40.0 * progress;
        if item_f > mean_residual {
            score -= 25.0;
        }
        if item_size > 60 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        } else if fitting_bins_count == 1 && post_residual >= 8 {
            score += 35.0;
        }
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score += 15.0;
        }
        if fitting_bins_count > 0 {
            let waste_ratio = (br - item_f) / cap_f;
            if item_f > 0.6 * cap_f && item_f > mean_residual + 8.0 {
                score -= 12.0 * progress;
            }
            if waste_ratio > 0.30 && item_f / cap_f > 0.5 {
                score -= 18.0;
            }
            if waste_ratio > 0.45 && next_item_size > 0 && (bin_residual - item_size) < next_item_size {
                score -= 10.0 * (1.0 - progress);
            }
            if waste_ratio > 0.38 && (br - item_f) > mean_residual * 1.6 {
                score -= 16.0 * (1.0 - 0.5 * progress);
            }
            if (item_f - mean_residual).abs() < 3.0 && waste_ratio > 0.25 {
                score -= 9.0 * (1.0 - progress);
            }
            // Spawn-bias calibration: fresh bins attractive when the fleet is
            // fragmented and the item is big; fades as stream matures.
            let fleet_fragmentation = open_bins_count as f64 * mean_residual / cap_f;
            if fleet_fragmentation > 1.5 && item_f / cap_f > 0.55 {
                score -= (fleet_fragmentation - 1.5) * 4.5 * (1.0 - 0.6 * progress);
            }
            // Mutation: crowded-fleet fresh-bin justification.
            let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
            if crowded > 3.0 && item_f / cap_f > 0.45 {
                score -= 8.0 + 6.0 * progress;
            }
            if mean_residual < 12.0 && item_f / cap_f > 0.7 {
                score -= 10.0 + 8.0 * progress;
            }
            if next_item_size > 0 && next_item_size as f64 > mean_residual && item_f > next_item_size as f64 {
                score -= 6.0 * (1.0 - progress);
            }
            // Late-stream seal-or-spawn arbitration: near the end, only spawn
            // a fresh bin if no open bin could be nearly filled.
            if progress > 0.7 {
                let best_possible_gap = bin_residual.saturating_sub(item_size);
                if best_possible_gap <= 10 {
                    score += 90.0 * (progress - 0.7);
                }
            }
        }
    } else {
        // Prefer bins with residual close to the fleet mean.
        score += (br - mean_residual).abs() * 0.35;
        score -= progress * 8.0;
    }

    // Reward placements moving residual toward the fleet mean.
    let dr_before = (br - mean_residual).abs();
    let dr_after = (pr - mean_residual).abs();
    if dr_after < dr_before {
        score -= (dr_before - dr_after) * 0.4;
    }

    // Penalize gaps that neither fit the next item nor typical residuals.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * (0.5 + 1.5 * progress);
        // Dead-space floor guard: unreachable gaps are permanent waste.
        let unreachable = (next_item_size as f64 - pr).min(pr);
        score += unreachable * 0.35 * (0.3 + 0.7 * (1.0 - progress));
    }

    // Prefer the bin whose post-residual best matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / cap_f) * 6.0;
    }

    // Perfect handoff chain reward, deepened late in the stream.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0 * (0.5 + progress);
        if open_bins_count > 4 {
            score -= 8.0;
        }
    }

    // Avoid creating residuals in the unfillable band.
    if post_residual > 0 && post_residual < 40 {
        if next_item_size == 0 || (next_item_size as f64) > pr {
            if pr < mean_residual - 3.0 && pr > 6.0 {
                score += (mean_residual - pr) * (0.6 + 0.8 * progress);
            }
        }
    }

    // Residual-pairing lookahead: near-perfect chain target.
    if next_item_size > 0 && post_residual > next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap <= 3 {
            score -= 12.0 + 10.0 * progress;
        }
        if chain_gap <= 5 && open_bins_count >= 2 {
            score -= (6.0 - chain_gap as f64) * (1.5 + 0.25 * open_bins_count.min(12) as f64);
        }
        if chain_gap as f64 > mean_residual * 1.5 {
            score += (chain_gap as f64 - mean_residual * 1.5) * 0.25 * (1.0 - progress);
        }
    }

    // Residual-divisibility lookahead — perfect chain fill enabled.
    if next_item_size > 1 && post_residual > 0 && post_residual >= next_item_size {
        let q = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= (q as f64).min(4.0) * 4.0 * (1.0 - 0.5 * progress);
        } else if rem <= 2 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Late-stream compaction squeeze.
    if progress > 0.75 && post_residual > 0 {
        score += pr * (progress - 0.75) * 4.0;
    }

    // Discourage spreading small items off near-perfect packs.
    if bin_residual > item_size && bin_residual - item_size <= 2 && item_size <= 10 {
        score -= 8.0;
    }

    // Waste-fraction penalty on open bins.
    if bin_residual < bin_capacity && post_residual > 0 {
        let waste_frac = pr / br.max(1.0);
        score += waste_frac * 6.0 * (1.0 - progress);
    }

    // Density-ratio compaction.
    if bin_residual < bin_capacity {
        let consumed_frac = item_f / br.max(1.0);
        if consumed_frac > 0.7 {
            score -= (consumed_frac - 0.7) * 30.0 * (1.2 - progress);
        }
        // Harmony coupling: density combined with next-item reusability.
        if next_item_size > 0 && post_residual >= next_item_size {
            let reusable = (post_residual - next_item_size) as f64;
            if consumed_frac > 0.5 && reusable <= 10.0 {
                score -= consumed_frac * (10.0 - reusable) * (0.6 + 0.8 * progress);
            }
        }
        // Mutation: harmonic density bonus with a gentle knee for mid-density fills.
        if consumed_frac > 0.55 && consumed_frac < 0.7 {
            score -= (consumed_frac - 0.55) * 12.0 * (1.0 - progress);
        }
    }

    // Near-exact residual targeting.
    if post_residual > 0 && post_residual <= 12 {
        score -= 5.0 * (1.0 - progress) + 3.0 * progress;
    }

    // Dead-gap oracle: penalize sealed gaps below typical reusable residual.
    if post_residual > 0 && post_residual < 30 {
        let next_blocks = next_item_size > 0 && (next_item_size as f64) > pr;
        if next_blocks && pr < mean_residual * 0.8 {
            score += (mean_residual * 0.8 - pr) * (0.5 + progress);
        }
    }

    // Residual ladder smoothing.
    if post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
        if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Stranded-gap accounting: triple-sealed gaps penalized quadratically.
    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze — escalate quadratically as stream advances.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness: near the end, only near-exact fits matter.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Mutation: fragmentation-weighted consolidation — in a fragmented fleet,
    // non-reusable mid-band gaps are punished harder.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Mutation: two-item lookahead compaction — prefer placements whose
    // post-residual can absorb both the next item and a typical follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Mutation (gen 7): residual-entropy squeeze — when the fleet is tight
    // (low mean residual), tiny sealed gaps are pure waste; punish them
    // proportionally to how far they sit below the achievable mean, and
    // reward bins whose post-residual matches the next item exactly even
    // when the fit is loose, since chains compound savings.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 0.9 * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Mutation (gen 27): chain-dominance squeeze — extend the entropy squeeze
    // direction. When a placement leaves a residual that exactly chains into
    // the next item AND the fleet is fragmented, deepen the reward so that
    // chain-forming placements win over merely "mean-close" ones, since
    // compounding chains are what recover the last bins near the optimum.
    if next_item_size > 0 && post_residual == next_item_size && open_bins_count > 3 {
        score -= (open_bins_count.min(16) as f64) * 0.6 * (0.5 + 0.5 * progress);
    }
    // Mutation (gen 27): dead-band gradient — instead of a flat cliff below 8,
    // apply a smooth quadratic gradient from 8 down to 0 so that placements
    // leaving residuals of 1–3 are distinguished from those leaving 6–7,
    // sharpening selection among near-full fits.
    if post_residual > 0 && post_residual < 8 {
        score += (8.0 - pr) * (8.0 - pr) * 0.9 * (0.7 + 0.6 * progress);
    }
    // Mutation (gen 27): exact-fill bonus scaled by consumed fraction —
    // a perfect seal on a mostly-empty bin is worth less than one that
    // caps a dense bin; couple post_residual==0 with density.
    if post_residual == 0 && bin_residual < bin_capacity {
        let density = item_f / br.max(1.0);
        score -= density * 14.0 * (0.6 + 0.8 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by which
    // "harmonic" (mod-10 class) it falls into. Leftovers in classes that
    // commonly match future item sizes are valuable; odd/dead classes are not.
    let post_class = (post_residual % 10) as f64;
    let post_bucket = post_residual / 10; // integer division threshold tier

    // Reward post-residuals that are either 0 (perfect fit) or large enough
    // to be reusable (>= 30), penalize tiny dead leftovers.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else if post_residual >= 30 {
        score -= 18.0 + 0.6 * post_bucket as f64; // reusable leftover
        // Harmonic alignment: leftover whose mod-10 class matches a "common"
        // class (0, 5) is more likely to be filled later.
        if post_class == 0.0 { score -= 6.0; }
        else if post_class == 5.0 { score -= 3.0; }
        else { score += 2.0; }
    } else {
        // Dead space: 1..29 leftover is hard to use for items in 10..80 range
        score += (30 - post_residual) as f64 * 1.2;
        if post_class != 0.0 { score += 3.0; }
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let nxt_left = post_residual - next_item_size;
            if nxt_left >= 10 {
                score -= 12.0 - 0.3 * nxt_left as f64;
            } else {
                score += 8.0; // next item would strand us near-full with dead space
            }
        }
        // If next item is huge, keep bins with big residuals free for it.
        if next_item_size >= 50 && post_residual < next_item_size && post_residual < 20 {
            score += 10.0;
        }
    }

    // Tightness reward: prefer bins that the item fills a large fraction of.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_frac * fill_frac;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (pristine bin): only attractive when no open bin fits
    // well or mean residual across open bins is low. Penalize opening new bins
    // when existing capacity is plentiful.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of a new bin; reduced when open bins are nearly full.
        score += 35.0 - 30.0 * pressure - 10.0 * progress;
        if fitting_bins_count == 0 { score -= 25.0; } // no alternative: must open
        if next_item_size > 0 && next_item_size >= 60 { score -= 8.0; } // big item coming
    }

    // Mild global balancing: nudge toward bins with residuals near the mean
    // to keep the bin population homogeneous (harmonic class coherence).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

