    // Residual-entropy squeeze.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * (0.9 + 0.5 * progress) * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Exact-fill chain anticipation.
    if next_item_size > 0 && post_residual == 0 && open_bins_count > 3 {
        score -= (open_bins_count.min(15) as f64) * 0.8 * (0.5 + 0.5 * progress);
    }

    // Sub-mean residual guard: dead space with no chain potential.
    if post_residual > 0 && post_residual <= 3 && next_item_size > post_residual {
        score += 12.0 + 8.0 * progress;
    }

    // Gen-28 mutation A: dead-space ratio squeeze — punish placements whose
    // post-residual is a large non-chainable fraction of remaining space;
    // reward low dead ratios that close bins out completely.
    if bin_residual < bin_capacity && post_residual > 0 {
        let dead_ratio = pr / br.max(1.0);
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        if dead_ratio > 0.45 && !chains {
            score += (dead_ratio - 0.45) * 22.0 * (0.5 + 0.5 * progress);
        }
        if dead_ratio < 0.2 {
            score -= (0.2 - dead_ratio) * 15.0 * (0.6 + 0.6 * progress);
        }
    }

    // Gen-28 mutation B: exact-closure arbitration — a perfect seal on an
    // open bin beats both other open bins and the fresh-bin candidate.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    // Gen-28 mutation C: fine-grained residual fitting — reward placements
    // whose post-residual lands within a tight band above the next item,
    // anticipating a chain fill without leaving slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        if chain_gap <= 2.0 {
            score -= 9.0 * (1.0 - 0.3 * progress);
        } else if chain_gap <= 6.0 {
            score -= (6.0 - chain_gap) * 1.8 * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable dead space (< 10) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose post-residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 2.0;
        }
        // Bonus if post-residual matches next item exactly (chain packing).
        if post_residual == next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    // or the item is large and many bins are already open.
    if bin_residual == bin_capacity {
        let base_penalty = 20.0;
        let fit_ratio_pen = 25.0 * fit_ratio; // poor fit into open bins -> new bin more attractive
        let open_pen = (open_bins_count as f64).ln().max(0.0) * 2.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += base_penalty - fit_ratio_pen - open_pen - 3.0 * progress;
    }

    // Mild preference for bins below mean residual (spread load evenly).
    score += 0.05 * ((bin_residual as f64) - mean_residual).max(-50.0);

    score
}

