    // residual so bins close out completely.
    if bin_residual < bin_capacity && post_residual > 0 {
        let dead_ratio = pr / br.max(1.0);
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        if dead_ratio > 0.45 && !chains {
            score += (dead_ratio - 0.45) * 22.0 * (0.5 + 0.5 * progress);
        }
        if dead_ratio < 0.2 {
            score -= (0.2 - dead_ratio) * 15.0 * (0.6 + 0.6 * progress);
        }
    }

    // Gen-28 mutation: exact-closure arbitration — when an open bin can be
    // sealed perfectly by this item, treat it as a near-free win over both
    // other open bins and the fresh-bin candidate, scaled by fleet size.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    // Gen-28 mutation: fine-grained residual fitting — reward placements
    // whose post-residual lands within a tight band around the next item,
    // anticipating a chain fill without leaving slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        if chain_gap <= 2.0 {
            score -= 9.0 * (1.0 - 0.3 * progress);
        } else if chain_gap <= 6.0 {
            score -= (6.0 - chain_gap) * 1.8 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-29 mutation: harvestable-residual valuation — score the leftover
    // by how much of it the fleet can realistically still consume, using a
    // saturating coverage estimate over the mean residual as a proxy for the
    // remaining item-size distribution. Leftovers far above what the fleet
    // typically absorbs are dead weight and get punished progressively.
    if post_residual > 0 {
        let harvest = (pr / (mean_residual.max(1.0) * 1.6)).min(1.0);
        score += pr * (1.0 - harvest) * (0.35 + 0.45 * progress);
        // Complementary reward: leftovers within one mean-residual of zero
        // are nearly closed bins — nudge them toward full closure.
        if pr <= mean_residual && next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= (mean_residual - pr) * 0.5 * progress;
        }
    }

    // Gen-29 mutation: parity-aware multi-fill lookahead — when the
    // post-residual is an exact multiple of the next item, the bin can be
    // sealed by a run of identical items; deepen the existing divisibility
    // reward when the fleet is fragmented (closing bins reduces spread).
    if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
        let q = (post_residual / next_item_size) as f64;
        if q >= 2.0 {
            score -= q.min(5.0) * 3.5 * (0.5 + 0.5 * progress) * (1.0 + 0.05 * open_bins_count.min(10) as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
