    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    // Gen-29 mutation: fine-grained residual fitting — reward placements
    // whose post-residual lands within a tight band around the next item,
    // anticipating a chain fill without leaving slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        if chain_gap <= 2.0 {
            score -= 9.0 * (1.0 - 0.3 * progress);
        } else if chain_gap <= 6.0 {
            score -= (6.0 - chain_gap) * 1.8 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-29 addition: chain-continuity coupling — when the next item fits
    // the post-residual with zero or minimal slack AND the fleet is crowded,
    // deepen the reward to consolidate rather than spawn new bins.
    if next_item_size > 0 && post_residual >= next_item_size && open_bins_count > 3 {
        let slack2 = (post_residual - next_item_size) as f64;
        if slack2 <= 1.0 {
            score -= 4.0 * (open_bins_count.min(10) as f64) * 0.3;
        }
    }

    score
}

