    // nearly seals a bin (post-residual <= 3), escalate the reward as the
    // stream matures so late bins close out instead of dribbling slack.
    if bin_residual < bin_capacity && post_residual > 0 && post_residual <= 3 {
        score -= 18.0 + 26.0 * progress + item_f * 0.05;
    }

    // Gen-31 mutation: anti-fragmentation spawn gate — a new bin should only
    // win when its implied post-residual (capacity - item) is a "clean"
    // target for the next item; otherwise penalize spawning harder than
