    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let fresh_post = cap_f - item_f;
        if fresh_post < next_item_size as f64 && fresh_post > 0.0 {
            score += (next_item_size as f64 - fresh_post) * (0.8 + 0.6 * progress);
        }
        if fresh_post >= next_item_size as f64 && fresh_post - next_item_size as f64 <= 4.0 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    score
}

