        let after_chain = post_residual - next_item_size;
        if after_chain as f64 <= mean_residual * 0.8 && after_chain > 0 {
            score -= (mean_residual * 0.8 - after_chain as f64) * 1.6 * (0.5 + 0.5 * progress);
        }
    }

    score
}

