    }

    // Gen-31 mutation: quadratic waste curvature — small stranded gaps
    // punished super-linearly, sharpening the parent's linear tiers.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - pr) * (20.0 - pr) * 0.12 * (0.6 + 0.8 * progress);
    }

    // Gen-31 mutation: fill-efficiency gradient — reward placements whose
    // fill fraction exceeds the fleet-mean fill ratio, scaled by fleet size.
