    // Gen-28 mutation: exact-closure arbitration — when an open bin can be
    // sealed perfectly by this item, treat it as a near-free win over both
    // other open bins and the fresh-bin candidate, scaled by fleet size.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    // Gen-28 mutation: fine-grained residual fitting — reward placements
    // whose post-residual lands within a tight band around the next item,
    // anticipating a chain fill without leaving slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        if chain_gap <= 2.0 {
            score -= 9.0 * (1.0 - 0.3 * progress);
        } else if chain_gap <= 6.0 {
            score -= (6.0 - chain_gap) * 1.8 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-31 mutation: stranded-residual chain audit — a placement whose
    // post-residual cannot hold the next item AND is too small for typical
    // future items (below half the mean residual) is a stranded pocket;
    // escalate the penalty quadratically as the pocket shrinks, so bins
    // either close exactly or leave a reusable residual.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let pocket = pr.min(mean_residual * 0.5);
        if pocket < mean_residual * 0.5 {
            let deficit = mean_residual * 0.5 - pocket;
            score += deficit * deficit * 0.22 * (0.6 + 0.4 * progress);
        }
    }

    // Gen-31 mutation: near-closure preference — when the item nearly seals
    // a bin (residual 1..=3 left) but not exactly, reward it proportionally
    // so tiny residuals are preferred over mid-size leftovers; this targets
    // the residual-variance weakness directly.
    if post_residual >= 1 && post_residual <= 3 && bin_residual < bin_capacity {
        score -= 14.0 - (post_residual as f64) * 3.0 + 6.0 * progress;
    }

    // Gen-31 mutation: chain-depth arbitration — if the next item exactly
    // consumes the post-residual AND the item after that pattern repeats
    // (post-residual divisible into next-item-sized chunks), deepen the
    // existing divisibility reward with a progress-scaled bonus.
    if next_item_size > 1 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
        let depth = (post_residual / next_item_size) as f64;
        if depth >= 2.0 {
            score -= (depth - 1.0).min(3.0) * 5.0 * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity.max(1) as f64;
    let item_f = item_size as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;

    // Sharper dead-space tiers, tuned by stream progress.
    if post_residual > 0 && post_residual < 8 {
        score += 80.0 + 10.0 * progress;
    } else if post_residual < 16 {
        score += 25.0;
    } else if post_residual < 25 {
        score += 8.0;
    }

    // Tight-fit rewards, deepened slightly for large items.
    if post_residual == 0 {
        score -= 120.0 + item_f * 0.15;
        if open_bins_count > 6 {
            score -= 6.0 + open_bins_count.min(20) as f64 * 0.5;
        }
    } else if post_residual <= 4 {
        score -= 55.0;
    }

    // Two-step lookahead on the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size < post_residual {
            let future_gap = post_residual - next_item_size;
            if future_gap < 8 {
                score += 20.0;
            } else {
                score -= 10.0;
            }
        } else {
            score += pr * 0.25;
        }
    }

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Progress-driven consolidation pressure.
    score += open_bins_count as f64 * (1.0 + progress);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 20.0 + 40.0 * progress;
        if item_f > mean_residual {
            score -= 25.0;
        }
        if item_size > 60 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        } else if fitting_bins_count == 1 && post_residual >= 8 {
            score += 35.0;
        }
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score += 15.0;
        }
        if fitting_bins_count > 0 {
            let waste_ratio = (br - item_f) / cap_f;
            if item_f > 0.6 * cap_f && item_f > mean_residual + 8.0 {
                score -= 12.0 * progress;
            }
            if waste_ratio > 0.30 && item_f / cap_f > 0.5 {
                score -= 18.0;
            }
            if waste_ratio > 0.45 && next_item_size > 0 && (bin_residual - item_size) < next_item_size {
                score -= 10.0 * (1.0 - progress);
            }
            if waste_ratio > 0.38 && (br - item_f) > mean_residual * 1.6 {
                score -= 16.0 * (1.0 - 0.5 * progress);
            }
            if (item_f - mean_residual).abs() < 3.0 && waste_ratio > 0.25 {
                score -= 9.0 * (1.0 - progress);
            }
            // Spawn-bias calibration: fresh bins attractive when the fleet is
            // fragmented and the item is big; fades as stream matures.
            let fleet_fragmentation = open_bins_count as f64 * mean_residual / cap_f;
            if fleet_fragmentation > 1.5 && item_f / cap_f > 0.55 {
                score -= (fleet_fragmentation - 1.5) * 4.5 * (1.0 - 0.6 * progress);
            }
            // Crowded-fleet fresh-bin justification.
            let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
            if crowded > 3.0 && item_f / cap_f > 0.45 {
                score -= 8.0 + 6.0 * progress;
            }
            if mean_residual < 12.0 && item_f / cap_f > 0.7 {
                score -= 10.0 + 8.0 * progress;
            }
            if next_item_size > 0 && next_item_size as f64 > mean_residual && item_f > next_item_size as f64 {
                score -= 6.0 * (1.0 - progress);
            }
            // Late-stream seal-or-spawn arbitration.
            if progress > 0.7 {
                let best_possible_gap = bin_residual.saturating_sub(item_size);
                if best_possible_gap <= 10 {
                    score += 90.0 * (progress - 0.7);
                }
            }
            // Spawn only if the fresh bin promises a post-residual the next
            // item can chain into; otherwise the open fleet should absorb.
            if next_item_size > 0 && (bin_residual.saturating_sub(item_size) as f64) < next_item_size as f64 * 0.5 {
                score += 14.0 * (1.0 - progress);
            }
        }
    } else {
        // Prefer bins with residual close to the fleet mean.
        score += (br - mean_residual).abs() * 0.35;
        score -= progress * 8.0;
    }

    // Reward placements moving residual toward the fleet mean.
    let dr_before = (br - mean_residual).abs();
    let dr_after = (pr - mean_residual).abs();
    if dr_after < dr_before {
        score -= (dr_before - dr_after) * 0.4;
    }

    // Penalize gaps that neither fit the next item nor typical residuals.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * (0.5 + 1.5 * progress);
        let unreachable = (next_item_size as f64 - pr).min(pr);
        score += unreachable * 0.35 * (0.3 + 0.7 * (1.0 - progress));
    }

    // Prefer the bin whose post-residual best matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / cap_f) * 6.0;
    }

    // Perfect handoff chain reward, deepened late in the stream.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0 * (0.5 + progress);
        if open_bins_count > 4 {
            score -= 8.0;
        }
    }

    // Avoid creating residuals in the unfillable band.
    if post_residual > 0 && post_residual < 40 {
        if next_item_size == 0 || (next_item_size as f64) > pr {
            if pr < mean_residual - 3.0 && pr > 6.0 {
                score += (mean_residual - pr) * (0.6 + 0.8 * progress);
            }
        }
    }

    // Residual-pairing lookahead: near-perfect chain target.
    if next_item_size > 0 && post_residual > next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap <= 3 {
            score -= 12.0 + 10.0 * progress;
        }
        if chain_gap <= 5 && open_bins_count >= 2 {
            score -= (6.0 - chain_gap as f64) * (1.5 + 0.25 * open_bins_count.min(12) as f64);
        }
        if chain_gap as f64 > mean_residual * 1.5 {
            score += (chain_gap as f64 - mean_residual * 1.5) * 0.25 * (1.0 - progress);
        }
    }

    // Residual-divisibility lookahead — perfect chain fill enabled.
    if next_item_size > 1 && post_residual > 0 && post_residual >= next_item_size {
        let q = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= (q as f64).min(4.0) * 4.0 * (1.0 - 0.5 * progress);
        } else if rem <= 2 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Late-stream compaction squeeze.
    if progress > 0.75 && post_residual > 0 {
        score += pr * (progress - 0.75) * 4.0;
    }

    // Discourage spreading small items off near-perfect packs.
    if bin_residual > item_size && bin_residual - item_size <= 2 && item_size <= 10 {
        score -= 8.0;
    }

    // Waste-fraction penalty on open bins.
    if bin_residual < bin_capacity && post_residual > 0 {
        let waste_frac = pr / br.max(1.0);
        score += waste_frac * 6.0 * (1.0 - progress);
    }

    // Density-ratio compaction.
    if bin_residual < bin_capacity {
        let consumed_frac = item_f / br.max(1.0);
        if consumed_frac > 0.7 {
            score -= (consumed_frac - 0.7) * 30.0 * (1.2 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let reusable = (post_residual - next_item_size) as f64;
            if consumed_frac > 0.5 && reusable <= 10.0 {
                score -= consumed_frac * (10.0 - reusable) * (0.6 + 0.8 * progress);
            }
        }
        if consumed_frac > 0.55 && consumed_frac < 0.7 {
            score -= (consumed_frac - 0.55) * 12.0 * (1.0 - progress);
        }
    }

    // Near-exact residual targeting.
    if post_residual > 0 && post_residual <= 12 {
        score -= 5.0 * (1.0 - progress) + 3.0 * progress;
    }

    // Dead-gap oracle.
    if post_residual > 0 && post_residual < 30 {
        let next_blocks = next_item_size > 0 && (next_item_size as f64) > pr;
        if next_blocks && pr < mean_residual * 0.8 {
            score += (mean_residual * 0.8 - pr) * (0.5 + progress);
        }
    }

    // Residual ladder smoothing.
    if post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
        if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Stranded-gap accounting.
    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze (stronger early-phase pull).
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 1.1 * (0.7 + 0.5 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Gen-28 mutation: dead-space ratio squeeze — punish placements whose
    // post-residual is a large fraction of the bin's remaining space and
    // cannot chain with the next item; reward high fill fraction on the
    // residual so bins close out completely.
    if bin_residual < bin_capacity && post_residual > 0 {
        let dead_ratio = pr / br.max(1.0);
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        if dead_ratio > 0.45 && !chains {
            score += (dead_ratio - 0.45) * 22.0 * (0.5 + 0.5 * progress);
        }
        if dead_ratio < 0.2 {
            score -= (0.2 - dead_ratio) * 15.0 * (0.6 + 0.6 * progress);
        }
    }

    // Gen-28 mutation: exact-closure arbitration — when an open bin can be
    // sealed perfectly by this item, treat it as a near-free win over both
    // other open bins and the fresh-bin candidate, scaled by fleet size.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    // Gen-28 mutation: fine-grained residual fitting — reward placements
    // whose post-residual lands within a tight band around the next item,
    // anticipating a chain fill without leaving slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        if chain_gap <= 2.0 {
            score -= 9.0 * (1.0 - 0.3 * progress);
        } else if chain_gap <= 6.0 {
            score -= (6.0 - chain_gap) * 1.8 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-32 mutation: residual-harvest arbitration — when the remaining
    // residual after placement is small enough that the next item (or a
    // typical fleet residual) can absorb it, prefer this bin aggressively;
    // when the leftover is stranded in the awkward 1..=6 band with no
    // chaining prospect, penalize it harder as stream matures.
    if bin_residual < bin_capacity && post_residual > 0 {
        let chains_next = next_item_size > 0 && next_item_size <= post_residual;
        if chains_next && pr <= mean_residual * 1.3 {
            score -= (mean_residual * 1.3 - pr) * 1.6 * (0.6 + 0.6 * progress);
        }
        if !chains_next && pr <= 6.0 && progress > 0.4 {
            score += (7.0 - pr) * (2.0 + 3.0 * progress);
        }
        // Harvest bias: bins whose residual is exactly consumable by the
        // item plus the next item in two steps (perfect two-chain).
        if next_item_size > 0 && item_size + next_item_size == bin_residual {
            score -= 22.0 * (1.0 - 0.4 * progress);
        }
    }

    // Gen-32 mutation: fleet-residual matching for spawn arbitration — a
    // fresh bin is only worth opening when its post-residual aligns with
    // the fleet's typical leftover size, otherwise consolidation wins.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let fresh_pr = (bin_capacity - item_size) as f64;
        let align = (fresh_pr - mean_residual).abs();
        if align > 8.0 && fresh_pr > mean_residual {
            score += (align - 8.0) * 0.9 * (0.5 + 0.5 * progress);
        } else if align < 4.0 {
            score -= (4.0 - align) * 2.2 * (1.0 - 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" modular classes (multiples of common item sizes) deserve reward.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Class A: post_residual divisible by 10/20/25 -> highly reusable.
    let harmonic_bonus = if post_residual > 0 {
        if post_residual % 25 == 0 { -18.0 }
        else if post_residual % 20 == 0 { -14.0 }
        else if post_residual % 10 == 0 { -10.0 }
        else if post_residual % 5 == 0 { -5.0 }
        else { 0.0 }
    } else {
        -30.0 // perfect fill
    };
    score += harmonic_bonus * (1.0 - 0.5 * progress);

    // Dead-space penalty: tiny unusable leftovers (1..10) are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 + 8.0 * (10.0 - post) / 10.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chaining
        } else if next_item_size < post_residual {
            // harmonic class of the double leftover
            let double = post_residual - next_item_size;
            if double % 10 == 0 && double > 0 { score -= 8.0; }
            score -= 4.0 * (1.0 - (double as f64 / cap).min(1.0));
        } else {
            // next item cannot use the leftover: mild penalty proportional to slack
            score += 3.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    } else {
        // last item: strongly prefer tightest fill
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let mean_fit = (mean_residual - item_size as f64).max(0.0);
        score = cap * 0.85 + open_pressure * 2.0 - mean_fit * 0.5;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        }
    } else {
        // Prefer bins tighter relative to the mean residual (best-fit flavor).
        score += 3.0 * (bin_residual as f64 - mean_residual).max(0.0) / cap;
    }

    // Integer-division threshold on residual class: chunked waste measure.
    let chunk = post_residual / 10;
    score += chunk as f64 * 1.5;

    score
}

