            if progress > 0.7 {
                let best_possible_gap = bin_residual.saturating_sub(item_size);
                if best_possible_gap <= 10 {
                    score += 90.0 * (progress - 0.7);
                }
            }
            // Spawn only if the fresh bin promises a post-residual the next
            // item can chain into; otherwise the open fleet should absorb.
            if next_item_size > 0 && (bin_residual.saturating_sub(item_size) as f64) < next_item_size as f64 * 0.5 {
                score += 14.0 * (1.0 - progress);
            }
            // Gen-32 mutation: chain-quality spawn gate — when spawning, prefer
            // fresh bins whose post-residual exactly equals the next item (a
            // guaranteed future seal) and penalize spawns whose post-residual
            // is a small unchainable remainder.
            if next_item_size > 0 {
                let fresh_gap = bin_residual.saturating_sub(item_size);
                if fresh_gap == next_item_size {
                    score -= 18.0 * (1.0 - 0.5 * progress);
                } else if fresh_gap < next_item_size && fresh_gap > 0 {
                    score += 10.0 * (1.0 - progress);
                }
            }
        }
    } else {
        score += (br - mean_residual).abs() * 0.35;
        score -= progress * 8.0;
    }

    // Reward placements moving residual toward the fleet mean.
    let dr_before = (br - mean_residual).abs();
    let dr_after = (pr - mean_residual).abs();
    if dr_after < dr_before {
        score -= (dr_before - dr_after) * 0.4;
    }

    // Penalize gaps that neither fit the next item nor typical residuals.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * (0.5 + 1.5 * progress);
        let unreachable = (next_item_size as f64 - pr).min(pr);
        score += unreachable * 0.35 * (0.3 + 0.7 * (1.0 - progress));
    }

    // Prefer the bin whose post-residual best matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 1 {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / cap_f) * 6.0;
    }

    // Perfect handoff chain reward, deepened late in the stream.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0 * (0.5 + progress);
        if open_bins_count > 4 {
            score -= 8.0;
        }
    }

    // Avoid creating residuals in the unfillable band.
    if post_residual > 0 && post_residual < 40 {
        if next_item_size == 0 || (next_item_size as f64) > pr {
            if pr < mean_residual - 3.0 && pr > 6.0 {
                score += (mean_residual - pr) * (0.6 + 0.8 * progress);
            }
        }
    }

    // Residual-pairing lookahead: near-perfect chain target.
    if next_item_size > 0 && post_residual > next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap <= 3 {
            score -= 12.0 + 10.0 * progress;
        }
        if chain_gap <= 5 && open_bins_count >= 2 {
            score -= (6.0 - chain_gap as f64) * (1.5 + 0.25 * open_bins_count.min(12) as f64);
        }
        if chain_gap as f64 > mean_residual * 1.5 {
            score += (chain_gap as f64 - mean_residual * 1.5) * 0.25 * (1.0 - progress);
        }
    }

    // Residual-divisibility lookahead — perfect chain fill enabled.
    if next_item_size > 1 && post_residual > 0 && post_residual >= next_item_size {
        let q = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= (q as f64).min(4.0) * 4.0 * (1.0 - 0.5 * progress);
        } else if rem <= 2 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Late-stream compaction squeeze.
    if progress > 0.75 && post_residual > 0 {
        score += pr * (progress - 0.75) * 4.0;
    }

    // Discourage spreading small items off near-perfect packs.
    if bin_residual > item_size && bin_residual - item_size <= 2 && item_size <= 10 {
        score -= 8.0;
    }

    // Waste-fraction penalty on open bins.
    if bin_residual < bin_capacity && post_residual > 0 {
        let waste_frac = pr / br.max(1.0);
        score += waste_frac * 6.0 * (1.0 - progress);
    }

    // Density-ratio compaction.
    if bin_residual < bin_capacity {
        let consumed_frac = item_f / br.max(1.0);
        if consumed_frac > 0.7 {
            score -= (consumed_frac - 0.7) * 30.0 * (1.2 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let reusable = (post_residual - next_item_size) as f64;
            if consumed_frac > 0.5 && reusable <= 10.0 {
                score -= consumed_frac * (10.0 - reusable) * (0.6 + 0.8 * progress);
            }
        }
        if consumed_frac > 0.55 && consumed_frac < 0.7 {
            score -= (consumed_frac - 0.55) * 12.0 * (1.0 - progress);
        }
    }

    // Near-exact residual targeting.
    if post_residual > 0 && post_residual <= 12 {
        score -= 5.0 * (1.0 - progress) + 3.0 * progress;
    }

    // Dead-gap oracle: penalize sealed gaps below typical reusable residual.
    if post_residual > 0 && post_residual < 30 {
        let next_blocks = next_item_size > 0 && (next_item_size as f64) > pr;
        if next_blocks && pr < mean_residual * 0.8 {
            score += (mean_residual * 0.8 - pr) * (0.5 + progress);
        }
    }

    // Residual ladder smoothing.
    if post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
        if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Stranded-gap accounting: triple-sealed gaps penalized quadratically.
    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze — escalate quadratically as stream advances.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness: near the end, only near-exact fits matter.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * (0.9 + 0.5 * progress) * (0.6 + 0.6 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Exact-fill chain anticipation.
    if next_item_size > 0 && post_residual == 0 && open_bins_count > 3 {
        score -= (open_bins_count.min(15) as f64) * 0.8 * (0.5 + 0.5 * progress);
    }

    // Sub-mean residual guard: dead space with no chain potential.
    if post_residual > 0 && post_residual <= 3 && next_item_size > post_residual {
        score += 12.0 + 8.0 * progress;
    }

    // Gen-28 mutation A: dead-space ratio squeeze.
    if bin_residual < bin_capacity && post_residual > 0 {
        let dead_ratio = pr / br.max(1.0);
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        if dead_ratio > 0.45 && !chains {
            score += (dead_ratio - 0.45) * 22.0 * (0.5 + 0.5 * progress);
        }
        if dead_ratio < 0.2 {
            score -= (0.2 - dead_ratio) * 15.0 * (0.6 + 0.6 * progress);
        }
    }

    // Gen-28 mutation B: exact-closure arbitration.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    // Gen-28 mutation C: fine-grained residual fitting.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        if chain_gap <= 2.0 {
            score -= 9.0 * (1.0 - 0.3 * progress);
        } else if chain_gap <= 6.0 {
            score -= (6.0 - chain_gap) * 1.8 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-32 mutation: two-step chain anticipation — combine fine-grained
    // residual fitting with lookahead by rewarding placements whose
    // post-residual can absorb the next item AND leave a residual that
    // still matches the fleet mean (a second chain hop), while penalizing
    // placements that chain once but strand a tiny unusable remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let hop2 = post_residual - next_item_size;
        if (hop2 as f64 - mean_residual).abs() <= 2.0 && item_f / br.max(1.0) > 0.35 {
            score -= 6.0 * (0.6 + 0.4 * progress);
        }
        if hop2 > 0 && hop2 < 4 && (next_item_size as f64) > mean_residual + 6.0 {
            score += 5.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: a residual that cannot hold the next
    // lookahead item is unusable dead space -> penalize proportionally
    // to how far short it falls.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 2.5;
        // Extra harsh penalty for tiny stranded gaps (< 10% capacity).
        if post_residual < bin_capacity / 10 {
            score += 40.0;
        }
    }

    // Reward tight fits: item consuming most of the bin's current space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many bins open, consolidate into existing
    // bins; with few bins, tolerate spreading.
    score += open_bins_count as f64 * 0.8;

    // Slight nudge toward bins whose residual deviates below the mean
    // (prefer filling the emptiest-relative bins).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Late in the stream, tighten up: penalize wasteful placements more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // New-bin candidate: make empty bins moderately attractive only when
    // the item is large (would leave a workable residual anyway) or when
    // it would strand a tiny gap elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    score
}

