    if bin_residual < bin_capacity && post_residual > 0 {
        let seal_ratio = pr / br.max(1.0);
        if seal_ratio < 0.12 {
            score -= (0.12 - seal_ratio) * 40.0 * (0.8 + 0.4 * progress);
