    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = (1.0 - gap / bin_capacity as f64).max(0.0);
        score -= 20.0 * match_bonus * match_bonus;

        // Penalize residuals too small for the next item only mildly (dead space).
        if post_residual < next_item_size {
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
        // Perfect chain: post_residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: minimize waste absolutely.
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins that end below-average residual
    // (concentrating fullness) unless it's a near-perfect fit.
    let rel = (post_residual as f64 - mean_residual).max(0.0);
    score += 0.6 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.5 {
            score -= 15.0 * fit_ratio;
        }
    }

