        // Late in stream, prefer closing out bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Slight preference for filling larger residual bins to keep small ones flexible.
    score -= 0.05 * bin_residual as f64;

    score
}

