        if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Stranded-gap accounting.
    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze (stronger early-phase pull).
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 1.1 * (0.7 + 0.5 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Gen-28 mutation: dead-space ratio squeeze.
    if bin_residual < bin_capacity && post_residual > 0 {
        let dead_ratio = pr / br.max(1.0);
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        if dead_ratio > 0.45 && !chains {
            score += (dead_ratio - 0.45) * 22.0 * (0.5 + 0.5 * progress);
        }
        if dead_ratio < 0.2 {
            score -= (0.2 - dead_ratio) * 15.0 * (0.6 + 0.6 * progress);
        }
    }

    // Gen-28 mutation: exact-closure arbitration.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    // Gen-28 mutation: fine-grained residual fitting.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        if chain_gap <= 2.0 {
            score -= 9.0 * (1.0 - 0.3 * progress);
        } else if chain_gap <= 6.0 {
            score -= (6.0 - chain_gap) * 1.8 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-34 mutation: two-step dead-space arbitration — when the item cannot
    // fully close a bin, prefer the bin whose leftover dead space is smallest
    // in absolute terms relative to the fleet's typical residual, squeezing
    // the residual variance that limits compaction.
    if bin_residual < bin_capacity && post_residual > 0 {
        let dead = pr;
        if dead <= mean_residual {
            score -= (mean_residual - dead) * 0.9 * (1.0 - 0.5 * progress);
        } else {
            score += (dead - mean_residual) * 0.45 * (0.6 + 0.6 * progress);
        }
        // Absolute dead-space floor: residuals under 3 units are nearly
        // always unrecoverable waste unless the next item chains exactly.
        if dead < 3 && !(next_item_size > 0 && next_item_size == post_residual) {
            score += 6.0 * (1.0 - progress);
        }
        // Mid-band dead space (5..=9) with no chain partner is the main
        // fragmentation source late in the stream — penalize harder.
        if dead >= 5 && dead <= 9 && progress > 0.6 {
            let chained = next_item_size > 0 && next_item_size <= post_residual;
            if !chained {
                score += (9.0 - dead) * 3.0 * (progress - 0.6) * 5.0;
            }
        }
    }

    // Gen-34 mutation: residual-harvest lookahead — reward bins whose
    // post-residual can absorb the next item AND whose chain gap stays under
    // the fleet mean, creating dense two-item handoffs.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        if chain_gap < mean_residual * 0.6 {
            score -= (mean_residual * 0.6 - chain_gap) * 1.2 * (1.0 - 0.4 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward perfect match of post_residual to next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-item fill
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            // chain-fit bonus: next item leaves a small usable remainder
            let chain = post_residual - next_item_size;
            if chain >= 1 && chain <= 20 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let miss = (next_item_size - post_residual) as f64;
            score += 15.0 + 0.5 * miss;
        }
    } else {
        // last item: prefer minimal residual strongly
        score += 0.0;
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    let resid = post_residual as f64;
    let dev = resid - mean_residual;
    score += 0.35 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating dead space below typical minimum item size.
    if resid > 0 && resid < 10 {
        score += 30.0;
    }

    // Mild preference for keeping many bins consolidated when few are open.
    if open_bins_count > 1 {
        score -= 2.0;
    }

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        score += 18.0;
        if item_size >= 70 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    score
}

