        let chain_gap = post_residual - next_item_size;
        if chain_gap <= 3 {
            score -= 12.0 + 10.0 * progress;
        }
        if chain_gap <= 5 && open_bins_count >= 2 {
            score -= (6.0 - chain_gap as f64) * (1.5 + 0.25 * open_bins_count.min(12) as f64);
        }
        if chain_gap as f64 > mean_residual * 1.5 {
            score += (chain_gap as f64 - mean_residual * 1.5) * 0.25 * (1.0 - progress);
        }
    }

    // Residual-divisibility lookahead — perfect chain fill enabled.
    if next_item_size > 1 && post_residual > 0 && post_residual >= next_item_size {
        let q = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= (q as f64).min(4.0) * 4.0 * (1.0 - 0.5 * progress);
        } else if rem <= 2 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Late-stream compaction squeeze.
    if progress > 0.75 && post_residual > 0 {
        score += pr * (progress - 0.75) * 4.0;
    }

    // Discourage spreading small items off near-perfect packs.
    if bin_residual > item_size && bin_residual - item_size <= 2 && item_size <= 10 {
        score -= 8.0;
    }

    // Waste-fraction penalty on open bins.
    if bin_residual < bin_capacity && post_residual > 0 {
        let waste_frac = pr / br.max(1.0);
        score += waste_frac * 6.0 * (1.0 - progress);
    }

    // Density-ratio compaction.
    if bin_residual < bin_capacity {
        let consumed_frac = item_f / br.max(1.0);
        if consumed_frac > 0.7 {
            score -= (consumed_frac - 0.7) * 30.0 * (1.2 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let reusable = (post_residual - next_item_size) as f64;
            if consumed_frac > 0.5 && reusable <= 10.0 {
                score -= consumed_frac * (10.0 - reusable) * (0.6 + 0.8 * progress);
            }
        }
        if consumed_frac > 0.55 && consumed_frac < 0.7 {
            score -= (consumed_frac - 0.55) * 12.0 * (1.0 - progress);
        }
    }

    // Near-exact residual targeting.
    if post_residual > 0 && post_residual <= 12 {
        score -= 5.0 * (1.0 - progress) + 3.0 * progress;
    }

    // Dead-gap oracle.
    if post_residual > 0 && post_residual < 30 {
        let next_blocks = next_item_size > 0 && (next_item_size as f64) > pr;
        if next_blocks && pr < mean_residual * 0.8 {
            score += (mean_residual * 0.8 - pr) * (0.5 + progress);
        }
    }

    // Residual ladder smoothing.
    if post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
        if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Stranded-gap accounting.
    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze (stronger early-phase pull).
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 1.1 * (0.7 + 0.5 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Gen-28 mutation: dead-space ratio squeeze — punish placements whose
    // post-residual is a large fraction of the bin's remaining space and
    // cannot chain with the next item; reward high fill fraction on the
    // residual so bins close out completely.
    if bin_residual < bin_capacity && post_residual > 0 {
        let dead_ratio = pr / br.max(1.0);
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        if dead_ratio > 0.45 && !chains {
            score += (dead_ratio - 0.45) * 22.0 * (0.5 + 0.5 * progress);
        }
        if dead_ratio < 0.2 {
            score -= (0.2 - dead_ratio) * 15.0 * (0.6 + 0.6 * progress);
        }
    }

    // Gen-28 mutation: exact-closure arbitration — when an open bin can be
    // sealed perfectly by this item, treat it as a near-free win over both
    // other open bins and the fresh-bin candidate, scaled by fleet size.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    // Gen-28 mutation: fine-grained residual fitting — reward placements
    // whose post-residual lands within a tight band around the next item,
    // anticipating a chain fill without leaving slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        if chain_gap <= 2.0 {
            score -= 9.0 * (1.0 - 0.3 * progress);
        } else if chain_gap <= 6.0 {
            score -= (6.0 - chain_gap) * 1.8 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-34 mutation: multi-item residual amortization — when the
    // post-residual can absorb the next item AND the leftover after that
    // chain stays tiny or divisible, grant an escalating bonus; this
    // targets the diagnosed dead-space weakness by preferring bins whose
    // remaining space is fully amortizable across the lookahead horizon.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_chain = post_residual - next_item_size;
        let chain_frac = next_item_size as f64 / pr.max(1.0);
        if after_chain == 0 {
            score -= 14.0 * (0.6 + 0.6 * progress);
        } else if after_chain <= 3 {
            score -= (4.0 - after_chain as f64) * 2.2 * chain_frac * (0.7 + 0.5 * progress);
        } else if chain_frac > 0.6 {
            score -= 5.0 * chain_frac * (1.0 - progress);
        }
    }

    // Gen-34 mutation: near-closure threshold refinement — widen the
    // "almost sealed" band from 2 to 3 and scale by item size so that
    // near-perfect packs are not broken by small items mid-stream.
    if bin_residual > item_size && bin_residual - item_size <= 3 && item_size <= 14 {
        score -= 6.0 + (3 - (bin_residual - item_size)) as f64 * 2.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional tightness: how completely the item fills the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    let tight = item_size as f64 / bin_residual as f64; // 0..1

    // Reward tight fits (near-perfect fills) strongly.
    score -= 40.0 * tight * tight * fill;

    // Penalize large dead space quadratically, but soften for big items.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * dead * dead / (0.3 + fill);
    }

    // Perfect fill gets a huge bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it, scaled by how tight the fit is.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 50.0 * tight;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward leaving room usable by the next item, scaled by how snug.
            let snug = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * snug * snug;
        } else {
            // Post-residual too small for next item: penalize wasted slivers.
            let sliver = post_residual as f64 / bin_capacity as f64;
            if sliver < next_item_size as f64 / bin_capacity as f64 {
                score += 15.0 * (1.0 - sliver);
            }
        }
    } else {
        // Last item: greedily prefer fullest packing.
        score -= 50.0 * fill;
    }

    // New-bin candidate logic: an empty bin is a blank slate.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin when the item is large and few bins fit it,
        // or when open-bin residuals are on average poor fits.
        let poor_open = if open_bins_count > 0 {
            (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64
        } else { 0.0 };
        let pressure = (0.5 * (1.0 - fill) + 0.5 * poor_open) * (1.0 + (open_bins_count as f64).ln().max(0.0) * 0.15);
        score = score.max(0.0) * 0.0 + 45.0 - 70.0 * pressure;
        // Slight time decay: later in the stream, reusing bins matters more.
        let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * t;
    } else {
        // Mild preference to consolidate into fewer bins early on.
        let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - t) * 5.0 * (1.0 - (open_bins_count as f64 / 20.0).min(1.0));
    }

    // Coupling: if this bin's residual deviates far below the mean residual,
    // it's a scarce small gap — prefer using it for small items.
    let gap_deficit = mean_residual - bin_residual as f64;
    if gap_deficit > 0.0 && item_size <= bin_residual {
        score -= 10.0 * (gap_deficit / bin_capacity as f64).min(1.0) * (1.0 - tight);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
