            // Gen-34: spawn only if the fresh bin promises a post-residual the
            // next item can chain into; otherwise the open fleet absorbs.
            if next_item_size > 0 && (bin_residual.saturating_sub(item_size) as f64) < next_item_size as f64 * 0.5 {
