        }
    }

    // Exact-closure arbitration: perfect seal beats other open bins and the
    // fresh-bin candidate, scaled by fleet size.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    // Fine-grained residual fitting: reward post-residuals landing in a
    // tight band around the next item, anticipating a chain fill.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        if chain_gap <= 2.0 {
            score -= 9.0 * (1.0 - 0.3 * progress);
        } else if chain_gap <= 6.0 {
            score -= (6.0 - chain_gap) * 1.8 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-34 mutation: near-exact fill arbitration — when an open bin's
    // residual matches the item exactly, seal it decisively regardless of
    // fleet fragmentation; this prevents exact fits from being outrun by
    // consolidation noise elsewhere in the score.
    if bin_residual < bin_capacity && bin_residual == item_size {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // Gen-34 mutation: chain-depth lookahead — prefer placements whose
    // post-residual can absorb both the next item and a plausible follow-up
    // near the fleet mean, rewarding two-deep compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next as f64 >= mean_residual * 0.6 && after_next as f64 <= mean_residual * 1.4 {
            score -= 5.0 * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
