        let waste_frac = pr / br.max(1.0);
        score += waste_frac * 6.0 * (1.0 - progress);
    }

    // Density-ratio compaction.
    if bin_residual < bin_capacity {
        let consumed_frac = item_f / br.max(1.0);
        if consumed_frac > 0.7 {
            score -= (consumed_frac - 0.7) * 30.0 * (1.2 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let reusable = (post_residual - next_item_size) as f64;
            if consumed_frac > 0.5 && reusable <= 10.0 {
                score -= consumed_frac * (10.0 - reusable) * (0.6 + 0.8 * progress);
            }
        }
        if consumed_frac > 0.55 && consumed_frac < 0.7 {
            score -= (consumed_frac - 0.55) * 12.0 * (1.0 - progress);
        }
    }

    // Near-exact residual targeting.
    if post_residual > 0 && post_residual <= 12 {
        score -= 5.0 * (1.0 - progress) + 3.0 * progress;
    }

    // Dead-gap oracle.
    if post_residual > 0 && post_residual < 30 {
        let next_blocks = next_item_size > 0 && (next_item_size as f64) > pr;
        if next_blocks && pr < mean_residual * 0.8 {
            score += (mean_residual * 0.8 - pr) * (0.5 + progress);
        }
    }

    // Residual ladder smoothing.
    if post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
        if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Stranded-gap accounting.
    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze (stronger early-phase pull).
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 1.1 * (0.7 + 0.5 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Gen-28 mutation: dead-space ratio squeeze — punish placements whose
    // post-residual is a large fraction of the bin's remaining space and
    // cannot chain with the next item; reward high fill fraction on the
    // residual so bins close out completely.
    if bin_residual < bin_capacity && post_residual > 0 {
        let dead_ratio = pr / br.max(1.0);
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        if dead_ratio > 0.45 && !chains {
            score += (dead_ratio - 0.45) * 22.0 * (0.5 + 0.5 * progress);
        }
        if dead_ratio < 0.2 {
            score -= (0.2 - dead_ratio) * 15.0 * (0.6 + 0.6 * progress);
        }
    }

    // Gen-28 mutation: exact-closure arbitration — when an open bin can be
    // sealed perfectly by this item, treat it as a near-free win over both
    // other open bins and the fresh-bin candidate, scaled by fleet size.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    // Gen-28 mutation: fine-grained residual fitting — reward placements
    // whose post-residual lands within a tight band around the next item,
    // anticipating a chain fill without leaving slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        if chain_gap <= 2.0 {
            score -= 9.0 * (1.0 - 0.3 * progress);
        } else if chain_gap <= 6.0 {
            score -= (6.0 - chain_gap) * 1.8 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-35 mutation: absolute dead-space budget — cap the tolerated
    // leftover regardless of ratio; small absolute leftovers are cheap,
    // mid-range leftovers (8..=30) that nothing can chain into are the
    // primary source of wasted bins, so tax them quadratically.
    if bin_residual < bin_capacity && post_residual > 0 {
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        if !chains && pr >= 8.0 && pr <= 30.0 {
            let mid = (pr - 8.0) * (30.0 - pr);
            score += mid * 0.12 * (0.6 + 0.6 * progress);
        }
        // Reward leaving a residual that is itself reusable by the item
        // after next via divisibility, weighted by how tight the fit is.
        if chains && pr > 0 {
            let chain_util = item_f / br.max(1.0);
            score -= (chain_util - 0.5).max(0.0) * 10.0 * (0.4 + 0.6 * progress);
        }
    }

    // Gen-35 mutation: second-order lookahead — when the next item exactly
    // consumes the post-residual, the resulting bin closes perfectly; boost
    // this reward when the fleet is small (fewer bins = tighter packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= (open_bins_count.min(10) as f64) * 1.2 * (0.5 + 0.5 * progress);
    }

    // Gen-35 mutation: residual band alignment — prefer post-residuals that
    // sit inside the most common reusable band (near mean residual), since
    // those gaps are most likely to be absorbed by future items.
    if post_residual > 0 && mean_residual > 4.0 {
        let band_dev = (pr - mean_residual).abs() / mean_residual;
        if band_dev < 0.15 {
            score -= 6.0 * (1.0 - band_dev / 0.15) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64 / cap;               // normalized post residual
    let fill = 1.0 - (bin_residual as f64 / cap);     // normalized current fill
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let next = next_item_size as f64 / cap;           // normalized lookahead

    // Base: reward tight fits via a non-linear (quadratic) coupling of residual and fill.
    let mut score = r * (1.0 + 2.0 * fill * fill);

    // Smooth stream-progress coupling: as the stream advances, penalize large residuals more.
    let progress_term = 3.0 * t * r * r;
    score += progress_term;

    // Lookahead interaction: smooth polynomial reward if the next item fits the post-residual.
    let fit_next = if next > 0.0 {
        let slack = r - next;
        -2.0 * (slack.max(0.0) / (slack.max(0.0) + 0.05)) * (1.0 - r)
    } else {
        0.0
    };
    score += fit_next;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it (smooth saturating).
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 - (post_residual as f64 / cap));
    }

    // Mild penalty for spreading across many bins when residuals are large.
    score += 0.05 * (open_bins_count as f64) * (r - mean_residual / cap).abs();

    // New-bin candidate handling: make an empty bin attractive only when it beats poor fits.
    if bin_residual == bin_capacity {
        // Prefer a new bin when the item is large relative to capacity and stream is early/mid.
        score = 0.9 + 0.5 * (1.0 - item_size as f64 / cap) - 0.3 * t;
    }

    score
}

