    // Avoid creating residuals in the unfillable band.
    if post_residual > 0 && post_residual < 40 {
        if next_item_size == 0 || (next_item_size as f64) > pr {
            if pr < mean_residual - 3.0 && pr > 6.0 {
                score += (mean_residual - pr) * (0.6 + 0.8 * progress);
            }
        }
    }

    // Residual-pairing lookahead: near-perfect chain target.
    if next_item_size > 0 && post_residual > next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap <= 3 {
            score -= 12.0 + 10.0 * progress;
        }
        if chain_gap <= 5 && open_bins_count >= 2 {
            score -= (6.0 - chain_gap as f64) * (1.5 + 0.25 * open_bins_count.min(12) as f64);
        }
        if chain_gap as f64 > mean_residual * 1.5 {
            score += (chain_gap as f64 - mean_residual * 1.5) * 0.25 * (1.0 - progress);
        }
    }

    // Residual-divisibility lookahead — perfect chain fill enabled.
    if next_item_size > 1 && post_residual > 0 && post_residual >= next_item_size {
        let q = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= (q as f64).min(4.0) * 4.0 * (1.0 - 0.5 * progress);
        } else if rem <= 2 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Late-stream compaction squeeze.
    if progress > 0.75 && post_residual > 0 {
        score += pr * (progress - 0.75) * 4.0;
    }

    // Discourage spreading small items off near-perfect packs.
    if bin_residual > item_size && bin_residual - item_size <= 2 && item_size <= 10 {
        score -= 8.0;
    }

    // Waste-fraction penalty on open bins.
    if bin_residual < bin_capacity && post_residual > 0 {
        let waste_frac = pr / br.max(1.0);
        score += waste_frac * 6.0 * (1.0 - progress);
    }

    // Density-ratio compaction.
    if bin_residual < bin_capacity {
        let consumed_frac = item_f / br.max(1.0);
        if consumed_frac > 0.7 {
            score -= (consumed_frac - 0.7) * 30.0 * (1.2 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let reusable = (post_residual - next_item_size) as f64;
            if consumed_frac > 0.5 && reusable <= 10.0 {
                score -= consumed_frac * (10.0 - reusable) * (0.6 + 0.8 * progress);
            }
        }
        if consumed_frac > 0.55 && consumed_frac < 0.7 {
            score -= (consumed_frac - 0.55) * 12.0 * (1.0 - progress);
        }
    }

    // Near-exact residual targeting.
    if post_residual > 0 && post_residual <= 12 {
        score -= 5.0 * (1.0 - progress) + 3.0 * progress;
    }

    // Dead-gap oracle.
    if post_residual > 0 && post_residual < 30 {
        let next_blocks = next_item_size > 0 && (next_item_size as f64) > pr;
        if next_blocks && pr < mean_residual * 0.8 {
            score += (mean_residual * 0.8 - pr) * (0.5 + progress);
        }
    }

    // Residual ladder smoothing.
    if post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
        if dev <= 6.0 && post_residual >= 5 {
            score -= 3.0 + 2.0 * (1.0 - progress);
        }
    }

    // Stranded-gap accounting.
    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Dead-space variance squeeze.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15.0 - pr).max(0.0);
        score += gap * gap * 0.05 * progress * progress;
    }

    // Endgame exactness.
    if progress > 0.85 && post_residual > 6 {
        score += (post_residual - 6) as f64 * 2.0;
    }

    // Fragmentation-weighted consolidation.
    let frag = open_bins_count as f64 / (1.0 + mean_residual / 8.0);
    if post_residual > 4 && post_residual < 20 && frag > 2.0 {
        let reusable = next_item_size > 0 && next_item_size <= post_residual;
        if !reusable {
            score += (20.0 - pr) * 0.12 * frag.min(6.0) * (0.5 + 0.5 * progress);
        }
    }

    // Two-item lookahead compaction.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
    }

    // Residual-entropy squeeze (stronger early-phase pull).
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 1.1 * (0.7 + 0.5 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Gen-28 mutation: dead-space ratio squeeze.
    if bin_residual < bin_capacity && post_residual > 0 {
        let dead_ratio = pr / br.max(1.0);
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        if dead_ratio > 0.45 && !chains {
            score += (dead_ratio - 0.45) * 22.0 * (0.5 + 0.5 * progress);
        }
        if dead_ratio < 0.2 {
            score -= (0.2 - dead_ratio) * 15.0 * (0.6 + 0.6 * progress);
        }
    }

    // Gen-28 mutation: exact-closure arbitration.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    // Gen-28 mutation: fine-grained residual fitting.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        if chain_gap <= 2.0 {
            score -= 9.0 * (1.0 - 0.3 * progress);
        } else if chain_gap <= 6.0 {
            score -= (6.0 - chain_gap) * 1.8 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-35 mutation: fill-fraction residual compaction — reward placements
    // that consume a very high fraction of the bin's remaining space, with an
    // extra pull when the leftover residual is small enough to be closed by
    // any plausible future item; penalize mid-band consumption that strands
    // residual near the awkward 3..9 gap.
    if bin_residual < bin_capacity {
        let fill_frac = item_f / br.max(1.0);
        if fill_frac > 0.85 {
            score -= (fill_frac - 0.85) * 26.0 * (1.0 - 0.5 * progress);
        }
        if post_residual >= 3 && post_residual <= 9 && next_item_size > 0 && next_item_size as f64 > pr {
            score += (5.0 - (post_residual as f64 - 3.0).abs()) * 2.2 * (0.6 + 0.6 * progress);
        }
        // Harvestable-residual arbitration: if the post-residual matches the
        // fleet's mean residual, a future item of that size can close it —
        // mild reward scaled by how fragmented the fleet currently is.
        if post_residual > 0 && (pr - mean_residual).abs() < 1.5 && open_bins_count > 3 {
            score -= 4.0 * (1.0 - 0.5 * progress);
        }
    }

    // Gen-35 mutation: spawn arbitration refinement — when a fresh bin is the
    // candidate and the item would leave a residual the next item can nearly
    // fill, tilt toward opening; but when an open bin's post-residual equals
    // the next item exactly, tilt hard against spawning.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_pr = bin_residual.saturating_sub(item_size);
        if fresh_pr >= next_item_size && fresh_pr.saturating_sub(next_item_size) <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: classify leftover space ---
    // Classes: 0 (perfect fit), tiny (1..=5), small (6..=15), medium (16..=30), large (>30)
    let class_bonus: f64 = if post_residual == 0 {
        -40.0 // perfect fit is ideal
    } else if post_residual <= 5 {
        -20.0
    } else if post_residual <= 15 {
        -8.0
    } else if post_residual <= 30 {
        5.0
    } else {
        12.0
    };
    score += class_bonus;

    // --- Modulo arithmetic on post_residual: residues of 10 (capacity fractions) ---
    let r10 = post_residual % 10;
    // Residuals that are multiples of 10 are more likely reusable by future items
    let residue_bonus: f64 = match r10 {
        0 => -6.0,
        1 | 2 => 4.0,   // awkward slivers
        3 | 4 => 2.0,
        5 => -2.0,      // half-of-ten chunks moderately useful
        _ => 1.0,
    };
    score += residue_bonus;

    // --- Integer-division threshold coupling: can next item fit in post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains nicely: reward proportional to how well it fills
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * chain_fill;
        } else {
            // Next item cannot use leftover: penalize dead space
            score += 6.0;
        }
        // Harmonic class of next item size (decile of capacity)
        let next_class = next_item_size / 10;
        if next_class >= 5 && post_residual >= next_item_size {
            score -= 4.0; // big next item fits: strongly prefer keeping this bin viable
        }
    } else {
        // Last item: any bin is fine, slightly prefer exact fills
        score -= 5.0;
    }

    // --- Last-chance bin: if this is the only bin that fits, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate: penalize opening a new bin unless current fits are bad ---
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        // New bin is penalized more when few bins are open (prefer consolidating)
        score += 18.0 + 2.0 * openness;
        // But if item would leave a tiny unusable remainder elsewhere, new bin ok:
        if post_residual == bin_capacity - item_size {
            let leftover = bin_capacity - item_size;
            if leftover > 0 && leftover < 10 {
                score -= 30.0; // item is huge (91..100): fresh bin is the only sane option
            }
        }
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter packing) ---
    let dev = mean_residual - post_residual as f64;
    score += 0.5 * dev;

    // --- Stream progression: later in stream, be greedier about tight fits ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity.max(1) as f64;
    let item_f = item_size as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;

    // Sharper dead-space tiers.
    if post_residual > 0 && post_residual < 8 {
        score += 80.0 + 10.0 * progress;
    } else if post_residual < 16 {
        score += 25.0;
    } else if post_residual < 25 {
        score += 8.0;
    }

    // Tight-fit rewards.
