        }
    }

    // Residual-entropy squeeze.
    if post_residual > 0 && post_residual < mean_residual * 0.45 && mean_residual < 25.0 {
        score += (mean_residual * 0.45 - pr) * 1.1 * (0.7 + 0.5 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Quadratic dead-space curvature.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - pr) * (20.0 - pr) * 0.10 * (0.6 + 0.8 * progress);
    }

    // Sliver-seal avoidance late in the stream.
    if post_residual > 0 && progress > 0.5 {
        let sliver = mean_residual / 3.0;
        if pr < sliver {
            score += (sliver - pr) * (1.0 + 2.0 * (progress - 0.5));
        }
    }

    // Exact-closure arbitration: sealing a bin perfectly is a near-free win.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item are wasted.
    if post_residual < 10 {
        score -= 40.0; // perfect or near-perfect fill is excellent
    } else if post_residual < 20 {
        score -= 15.0;
    } else if post_residual < 40 {
        score += 8.0;
    } else if post_residual < 60 {
        score += 20.0;
    } else {
        score += 35.0;
    }

    // Exact fit is ideal regardless of everything else.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space is worse late in the stream (less chance to fill it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score -= 20.0 * progress;
    } else if post_residual >= 60 {
        score += 15.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 25.0;
    }
    // If next item cannot fit here and dead space is large, mild penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over spreading.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (compactness).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let bad_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 45.0 + bad_fits * -60.0 + open_bins_count as f64 * 0.5
            - if post_residual == bin_capacity { 0.0 } else { 0.0 };
        // If the next item is huge, a fresh bin is fine.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    score
}

