            // (<= 8) is nearly guaranteed waste.
            if pr < 8.0 {
                score += (8.0 - pr) * 3.0 * progress;
            }
        }
        if dead_ratio < 0.2 {
            score -= (0.2 - dead_ratio) * 15.0 * (0.6 + 0.6 * progress);
        }
    }

    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        if chain_gap <= 2.0 {
            score -= 9.0 * (1.0 - 0.3 * progress);
        } else if chain_gap <= 6.0 {
            score -= (6.0 - chain_gap) * 1.8 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-35 mutation: multi-item chain projection — estimate how many
    // consecutive next-item-sized fills the post-residual can absorb;
    // reward long chains, penalize residuals that only half-fit one item.
    if next_item_size > 0 && post_residual >= next_item_size && next_item_size > 0 {
        let chain_count = post_residual / next_item_size;
        if chain_count >= 2 {
            score -= (chain_count.min(3) as f64) * 5.0 * (0.6 + 0.4 * progress);
        }
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // The gap is stranded for the next item; check whether it still
        // matches the fleet mean (a future item may take it) before taxing.
        if (pr - mean_residual).abs() > 3.0 {
            score += (next_item_size - post_residual) as f64 * 0.35 * (1.0 - progress);
        }
    }

    // Gen-35 mutation: bin-closure priority under fragmentation — when many
    // bins are open, favor placements that drive a bin's residual to near
    // zero, consolidating the fleet instead of spreading slack.
    if post_residual > 0 && open_bins_count > 5 {
        let close_bonus = (1.0 - pr / (br.max(1.0))) * (1.0 - pr / cap_f.max(1.0));
        if pr <= 10 {
            score -= close_bonus * 9.0 * (0.4 + 0.6 * progress);
        }
    }

    score
}

