    }

    // Gen-36 mutation: fill-fraction ladder — deepen the reward for
    // placements that consume a very large share of the bin's residual,
    // with a sharper knee near full absorption; this directly targets the
    // diagnosed dead-space weakness by making near-closing bins win ties.
    if bin_residual < bin_capacity {
        let fill_frac = item_f / br.max(1.0);
        if fill_frac >= 0.9 {
            score -= 14.0 * (1.0 - 0.4 * progress);
        } else if fill_frac >= 0.8 {
            score -= 7.0 * (1.0 - 0.3 * progress);
        }
        // Penalize leaving a residual that no plausible future item can
        // absorb: gaps below the smallest conceivable item are pure waste,
        // and gaps just under the next item are stranded.
        if post_residual > 0 && post_residual < 4 {
            score += 10.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && (next_item_size - post_residual) <= 3 {
            score += 12.0 * (0.6 + 0.4 * progress);
        }
    }

    // Gen-36 mutation: mid-stream consolidation arbitration — when many bins
    // are open and mean residual is small, tilt slightly against placements
    // that leave residuals far above the fleet mean, pushing compaction of
    // scattered low-value space without disturbing exact-fit behavior.
    if progress > 0.35 && open_bins_count > 8 && post_residual > 0 {
        let above = pr - mean_residual;
        if above > 6.0 {
            score += above * 0.22 * (progress - 0.35).min(1.0);
        }
    }

    // Gen-36 mutation: fresh-bin residual promise check — a new bin should
    // only win when its post-placement residual is either zero or large
    // enough to remain useful; avoid spawning bins that immediately strand
    // a small unusable remainder.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let new_pr = bin_capacity.saturating_sub(item_size);
        if new_pr > 0 && new_pr < 6 {
            score += 18.0;
        }
        if next_item_size > 0 && new_pr > 0 && new_pr < next_item_size {
            score += 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fit = item_size as f64 / bin_residual.max(1) as f64;

    // Reward tight fits
    score -= 8.0 * fit * fit * (bin_residual as f64);

    // Penalize small dead space that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 3.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // Global pressure: many open bins with low mean residual -> consolidate
    if open_bins_count > 2 {
        let spread = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * spread;
        score -= 0.02 * mean_residual;
    }

    // New-bin candidate handling: penalize early, allow late or when fit is bad
    if is_new_bin {
        let fit_ok = fit >= 0.6 || (fitting_bins_count <= 1);
        let late = progress > 0.7;
        if fit_ok && (late || fitting_bins_count == 0) {
            score -= 4.0;
        } else {
            score += 20.0 + 30.0 * (1.0 - progress);
        }
    }

    // Mild time horizon coupling: prefer filling existing bins as stream ends
    score -= 5.0 * progress * (1.0 - fit);

    score
}

