            score -= (0.2 - dead_ratio) * 15.0 * (0.6 + 0.6 * progress);
        }
    }

    // Gen-28: exact-closure arbitration.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    // Gen-28: fine-grained residual fitting.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        if chain_gap <= 2.0 {
            score -= 9.0 * (1.0 - 0.3 * progress);
        } else if chain_gap <= 6.0 {
            score -= (6.0 - chain_gap) * 1.8 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-36 mutation A: residual-decay projection — estimate how much
    // residual mass the fleet can still absorb and punish placements that
    // strand gaps unlikely to be filled by remaining stream volume.
    if post_residual > 0 && total_items > step_index {
        let items_left = (total_items - step_index) as f64;
        let expected_left = items_left * (item_f.max(1.0) * 0.9);
        let fleet_absorb = open_bins_count as f64 * mean_residual;
        if expected_left > fleet_absorb {
            // Stream still large relative to fleet: small residuals are
            // valuable, big stranded gaps are costly.
            if pr > mean_residual * 1.3 {
                score += (pr - mean_residual * 1.3) * 0.55 * (0.4 + 0.6 * progress);
            }
        } else {
            // End-phase: residuals that the remaining small items can
            // consume are premium; reward exact divisibility harder.
            if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
    }

    // Gen-36 mutation B: pair-sum closure — when the next item cannot fit
    // alone but a small item could top off the residual later, mildly favor
    // leaving residuals in the [next, next+small] band rather than tiny
    // unfillable slivers.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let sliver = pr;
        if sliver < 5.0 && sliver < (next_item_size as f64) * 0.4 {
            score += (5.0 - sliver) * 1.6 * (1.0 - 0.5 * progress);
        }
    }

    // Gen-36 mutation C: fill-fraction gradient on open bins — sharpen the
    // compaction signal by rewarding bins whose fill fraction after this
    // placement approaches 1.0, with a mild mid-stream boost.
    if bin_residual < bin_capacity {
        let fill_after = 1.0 - pr / cap_f;
        if fill_after > 0.85 {
            score -= (fill_after - 0.85) * 40.0 * (0.7 + 0.5 * progress);
        }
    }

    // Gen-36 mutation D: new-bin arbitration refinement — when the fresh-bin
    // candidate is compared, penalize it if the item would leave a chained
    // residual in an existing bin but only a bare residual in the fresh one.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let fresh_post = bin_residual.saturating_sub(item_size);
        if (fresh_post as f64) > next_item_size as f64 && fresh_post < next_item_size + 4 {
            score -= 10.0 * (1.0 - progress);
        } else if fresh_post > 0 && (fresh_post as f64) < next_item_size as f64 {
            score += 12.0 * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - (pr / cap);

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    let poly = 0.6 * prog + 1.8 * prog2 + 2.4 * prog3;

    // Penalize dead space more aggressively as stream progresses
    score += poly * tightness * tightness * cap * 0.15;

    // Smooth reward for near-perfect fills (small post_residual), stronger later
    let perfect = 1.0 - tightness;
    score -= perfect * perfect * perfect * (1.0 + 3.0 * progress) * 10.0;

    // Coupling with mean residual: prefer bins whose residual deviates smoothly
    let dev = (pr - mean_residual) / cap;
    score += 0.5 * dev * dev * cap * (0.3 + progress);

    // Last-chance bonus: only bin that fits, smooth ramp with progress
    if fitting_bins_count == 1 {
        score -= 8.0 + 12.0 * progress;
    }

    // Lookahead: penalize leaving residual that barely misses next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            let r = gap / cap;
            score += 6.0 * r * (1.0 - r) * (0.5 + progress);
        } else {
            // residual too small for next item: mild penalty scaled by waste
            score += 2.0 * tightness * (1.0 - progress);
        }
    }

    // Smooth penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
