            }
            // Gen-36: fresh-bin parity check — if the best open-bin option
            // would strand a residual larger than the item itself while the
            // fresh bin leaves a chainable remainder, tilt toward spawning.
            let open_strand = bin_residual.saturating_sub(item_size);
            if next_item_size > 0 && open_strand > next_item_size * 3 && item_f > 0.5 * cap_f {
