        }
    }

    // Gen-37 mutation: combined fine-fitting + lookahead squeeze — when the
    // item nearly empties a bin AND the next item fits the leftover, apply a
    // compounding bonus that scales with fleet fragmentation.
    if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual && item_f as f64 / br.max(1.0) > 0.75 {
        let chain_gap = (post_residual - next_item_size) as f64;
        if chain_gap <= 4.0 {
            score -= (4.0 - chain_gap) * 3.0 + frag.min(5.0) * 1.5 * (1.0 - 0.5 * progress);
        }
    }

    // Gen-37 mutation: residual-variance control — mildly penalize
    // post-residuals far from the fleet mean when many bins are open,
    // pushing residuals toward a uniform, chainable band.
    if post_residual > 0 && open_bins_count > 8 {
        let dev = (pr - mean_residual).abs();
        if dev > 8.0 {
            score += (dev - 8.0) * 0.35 * (0.4 + 0.6 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    // Class 1: post_residual divisible by small harmonics (fits common sizes).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else {
        // Harmonic divisibility: residuals divisible by 10/20/25/50 pair well
        // with a broad range of item sizes.
        let mut harm = 0.0;
        if pr % 10 == 0 { harm += 6.0; }
        if pr % 20 == 0 { harm += 4.0; }
        if pr % 25 == 0 { harm += 4.0; }
        if pr % 50 == 0 { harm += 6.0; }
        score -= harm;

        // Dead-space penalty: tiny unusable leftovers (below smallest plausible item).
        if pr < 10 {
            score += 25.0 * (10 - pr) as f64;
        }

        // Harmonic match: does next item fit exactly into post residual?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 30.0; // chain of perfect fits
            } else if next_item_size < pr {
                // next item leaves a harmonic residual again?
                let nr = pr - next_item_size;
                if nr % 10 == 0 { score -= 8.0; }
                if nr == 0 { score -= 20.0; }
                if nr < 10 && nr > 0 { score += 10.0; }
            } else {
                // next item cannot use this residual at all
                score += 5.0;
            }
        }
    }

    // Tightness reward: bins that are nearly full are good targets.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has neutral-ish utility; penalize
    // opening one unless the item is large and no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0; // base cost of opening a new bin
        if item_size > 50 && (fitting_bins_count == 0 || (fitting_bins_count == 1 && bin_residual == bin_capacity)) {
            score -= 25.0; // large items justify fresh bins
        }
        if item_size <= 20 {
            score += 20.0; // small items should go into existing space
        }
    }

    // Progress modulation: early in the stream, be conservative with bins;
    // later, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress) * (bin_residual == bin_capacity) as i32 as f64;

    // Mean residual coupling: if open bins are already slack, avoid spreading.
    if mean_residual > (item_size as f64) * 1.5 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

