        score += (mean_residual * 0.45 - pr) * 1.1 * (0.7 + 0.5 * progress);
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual <= next_item_size + 1 && item_f / br.max(1.0) > 0.4 {
        score -= 7.0 * (1.0 - 0.4 * progress);
    }

    // Dead-space ratio squeeze — punish placements whose post-residual is a
    // large fraction of remaining space and cannot chain with the next item.
    if bin_residual < bin_capacity && post_residual > 0 {
        let dead_ratio = pr / br.max(1.0);
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        if dead_ratio > 0.45 && !chains {
            score += (dead_ratio - 0.45) * 22.0 * (0.5 + 0.5 * progress);
        }
        if dead_ratio < 0.2 {
            score -= (0.2 - dead_ratio) * 15.0 * (0.6 + 0.6 * progress);
        }
    }

    // Exact-closure arbitration — sealing a bin is a near-free win.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    // Fine-grained residual fitting: reward post-residuals within a tight
    // band around the next item, anticipating a chain fill without slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = (post_residual - next_item_size) as f64;
        if chain_gap <= 2.0 {
            score -= 9.0 * (1.0 - 0.3 * progress);
        } else if chain_gap <= 6.0 {
            score -= (6.0 - chain_gap) * 1.8 * (0.5 + 0.5 * progress);
        }
    }

    // Mutation (gen 37): chain-continuity lookahead — combine fine-grained
    // residual fitting with two-step anticipation. When the next item fits a
    // post-residual almost exactly AND the fleet is fragmented, deepen the
    // reward so bins close out in pairs rather than leaving half-slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 && open_bins_count > 3 {
            score -= 5.0 + 0.8 * open_bins_count.min(16) as f64 * (1.0 - 0.5 * progress);
        } else if gap <= 4 && mean_residual > 8.0 {
            score -= 4.0 * (1.0 - 0.4 * progress) * (open_bins_count as f64).min(6.0) * 0.25;
        }
    }

    // Mutation (gen 37): sliver-seal arbitration — late in the stream, any
    // post-residual below the smallest reusable band is dead weight; punish
    // it super-linearly so near-closing bins are chosen over leaving slivers.
    if post_residual > 0 && progress > 0.5 {
        let sliver = (mean_residual / 3.0).max(3.0);
        if pr < sliver {
            score += (sliver - pr) * (sliver - pr) * 0.10 * (1.0 + 2.0 * (progress - 0.5));
        }
    }

    // Mutation (gen 37): mean-fill gradient — reward placements whose fill
    // fraction of the residual beats the fleet mean fill, compounding
    // consolidation pressure with fleet size.
    if bin_residual < bin_capacity && bin_residual > 0 {
        let fill = item_f / br;
        let mean_fill = 1.0 - mean_residual / cap_f;
        if fill > mean_fill {
            score -= (fill - mean_fill) * 18.0 * (0.5 + open_bins_count.min(12) as f64 * 0.05);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit, strongly favored
    } else if post_residual <= 10 {
        score += 40.0; // near-perfect fit
    } else if post_residual < item_size.min(next_item_size.max(1)) && next_item_size > 0 && post_residual < next_item_size {
        // gap unusable by the lookahead item: potential dead space
        score += 25.0;
    } else if post_residual <= 30 {
        score += 5.0;
    }

    // Reward tight fits relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Pressure from many open bins: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 2.0 * pressure;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New empty bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * (fitting_bins_count as f64);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large stream items: fresh bins useful
        }
    }

    // Favor bins below mean residual (consolidating fuller bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Lookahead pairing: reward leaving a gap that fits the next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    score
}

