    }

    if post_residual >= 16 && post_residual < 25 {
        let next_blocks = next_item_size == 0 || (next_item_size as f64) > pr;
        if next_blocks {
            score += 6.0 + (25.0 - pr) * 0.55 * (0.4 + 0.6 * progress);
        }
    }

    if open_bins_count > 1 && bin_residual < bin_capacity {
        let fleet_slack = open_bins_count as f64 * mean_residual;
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if remaining > 0.0 {
            let slack_per_item = fleet_slack / remaining;
            let consumed_frac = item_f / br.max(1.0);
            if slack_per_item < 0.9 && consumed_frac < 0.6 {
                score += (0.9 - slack_per_item) * 14.0 * (1.0 - consumed_frac);
            }
            // Gen-41: endgame slack conservation — when the remaining item
            // count is small, residual slack is precious; prefer placements
            // that leave a post-residual matching the *next* item exactly,
            // and penalize leaving slack the remaining stream can't use.
            if remaining < 8.0 && post_residual > 0 {
                let fits_next = next_item_size > 0 && next_item_size <= post_residual;
                if !fits_next {
                    score += (post_residual as f64) * 1.5 * (8.0 - remaining) / 8.0;
                }
            }
        }
    }

    // Gen-41: mid-band dead-space refinement — residuals in (25, 40) that
    // cannot host the next item are soft-dead; apply a gentle quadratic
    // squeeze scaled by how far above the fleet mean they sit.
    if post_residual >= 25 && post_residual < 40 {
        let next_blocks = next_item_size == 0 || (next_item_size as f64) > pr;
        if next_blocks {
            let excess = pr - mean_residual;
            if excess > 0.0 {
                score += excess * excess * 0.03 * (0.5 + 0.5 * progress);
            }
        }
    }

    // Gen-41: triple-chain lookahead — if the post-residual can host the next
    // item AND the remainder after that still fits a mean-sized filler, this
    // bin is a strong chain anchor; reward it proportionally to progress.
    if next_item_size > 0 && post_residual > next_item_size && fitting_bins_count > 1 {
        let after_next = post_residual - next_item_size;
        if (after_next as f64) >= mean_residual {
            let filler_gap = after_next as f64 - mean_residual;
            if filler_gap <= 6.0 {
                score -= (6.0 - filler_gap) * 1.4 * (0.5 + 0.5 * progress);
            }
        }
    }

    score
}

