    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    // Sliver-seal avoidance late in the stream.
    if post_residual > 0 && progress > 0.5 {
        let sliver = mean_residual / 3.0;
        if pr < sliver {
            score += (sliver - pr) * (1.0 + 2.0 * (progress - 0.5));
        }
    }

    // Exact-sum decomposition probe — guaranteed two-step closure.
    if next_item_size > 0 && post_residual > next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == item_size {
            score -= 22.0 * (0.7 + 0.6 * progress);
        } else if item_size > 0 && two_step % item_size == 0 && two_step / item_size >= 2 && two_step / item_size <= 3 {
            score -= 9.0 * (1.0 - 0.4 * progress);
        }
    }

    // Dead-zone band refinement — residuals in (16, 25) that cannot host
    // the next item nor a mean-sized filler are true dead weight.
    if post_residual >= 16 && post_residual < 25 {
        let next_blocks = next_item_size == 0 || (next_item_size as f64) > pr;
        if next_blocks {
            score += 6.0 + (25.0 - pr) * 0.55 * (0.4 + 0.6 * progress);
        }
    }

    // Fleet-residual budget guard — avoid burning slack on loose fits.
    if open_bins_count > 1 && bin_residual < bin_capacity {
        let fleet_slack = open_bins_count as f64 * mean_residual;
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if remaining > 0.0 {
            let slack_per_item = fleet_slack / remaining;
            let consumed_frac = item_f / br.max(1.0);
            if slack_per_item < 0.9 && consumed_frac < 0.6 {
                score += (0.9 - slack_per_item) * 14.0 * (1.0 - consumed_frac);
            }
        }
    }

    // Gen-41: dead-space salvage ranking — among open bins that leave a
    // stranded residual (next item doesn't fit), prefer the one whose
    // stranded gap is smallest relative to the fleet mean; this steers
    // waste into the fewest, deepest pockets instead of spreading it.
    if post_residual > 0 && next_item_size > 0 && (next_item_size as f64) > pr {
        let stranded_deficit = next_item_size as f64 - pr;
        score += stranded_deficit * 0.9 * (0.5 + 0.5 * (1.0 - progress));
        if pr < next_item_size as f64 - pr {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Gen-41: pair-closure probe with next-item pairing — if post-residual
    // exactly equals the fleet mean residual, the gap remains reusable by
    // the average incoming item; reward keeping gaps in the reusable band.
    if post_residual > 0 && (pr - mean_residual).abs() <= 1.0 {
        score -= 6.0 * (0.5 + 0.5 * progress);
    }

    score
}

