            // is more reusable than the average open-bin residual it would
            // otherwise displace; otherwise keep consolidating.
            if fitting_bins_count > 0 {
                let fresh_gap = bin_residual.saturating_sub(item_size);
                let reusability = |r: f64, nxt: u32| -> f64 {
                    if nxt > 0 && (r as u32) >= nxt { 1.0 + (r - nxt as f64).min(10.0) / 20.0 } else { (r / 30.0).min(1.0) }
                };
                let fresh_util = reusability(fresh_gap as f64, next_item_size);
                let mean_util = reusability(mean_residual, next_item_size);
                if fresh_util < mean_util * 0.75 {
                    score += 10.0 * (1.0 - 0.4 * progress);
                } else if fresh_util > mean_util * 1.25 {
                    score -= 8.0 * (0.5 + 0.5 * progress);
                }
            }
        }
    } else {
        // Prefer bins with residual close to the fleet mean.
        score += (br - mean_residual).abs() * 0.35;
