            // is very tight, push toward bins that leave near-zero waste even
            // if the fill ratio is only moderate; loose fits burn slack that
            // the tail of the stream will need.
            if slack_per_item < 0.45 && post_residual > 0 {
                score += (0.45 - slack_per_item) * pr * 0.9;
            }
        }
    }

    // Gen-41: residual-gap histogram squeeze — residuals that are exactly
    // one unit below the next item are the most painful near-misses; give
    // them a dedicated sharp penalty so near-fitting bins lose priority
    // against bins that chain cleanly.
    if next_item_size > 0 && post_residual > 0 && post_residual + 1 == next_item_size {
        score += 10.0 + 14.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
