            score += 5.0 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-43 mutation: adaptive dead-band scaled by remaining demand.
    // When many items remain, residuals just below the next item's size are
    // far more damaging than late in the stream; scale the penalty by the
    // remaining item pressure instead of progress alone.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let remaining_frac = 1.0 - progress;
        let pressure = (remaining_frac * (total_items.max(1) as f64).sqrt()).min(3.0);
