                score -= 9.0 * (1.0 - 0.4 * progress);
            }
        }
    }

    // Dead-zone band refinement — residuals in (16, 25) that cannot host
    // the next item nor a mean-sized filler are true dead weight.
    if post_residual >= 16 && post_residual < 25 {
        let next_blocks = next_item_size == 0 || (next_item_size as f64) > pr;
        if next_blocks {
            score += 6.0 + (25.0 - pr) * 0.55 * (0.4 + 0.6 * progress);
        }
    }

    // Fleet-residual budget guard — when total open slack is tight relative
    // to remaining items, avoid burning slack on loose fits.
    if open_bins_count > 1 && bin_residual < bin_capacity {
        let fleet_slack = open_bins_count as f64 * mean_residual;
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if remaining > 0.0 {
            let slack_per_item = fleet_slack / remaining;
            let consumed_frac = item_f / br.max(1.0);
            if slack_per_item < 0.9 && consumed_frac < 0.6 {
                score += (0.9 - slack_per_item) * 14.0 * (1.0 - consumed_frac);
            }
        }
    }

    // Gen-42 chain-continuation depth probe.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let after_next = post_residual - next_item_size;
        let dev = (after_next as f64 - mean_residual).abs();
        if dev < 5.0 {
            score -= (5.0 - dev) * 1.6 * (0.6 + 0.4 * progress);
        }
        if after_next >= 16 && after_next < 25 {
            score += 5.0 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-43 mutation: gap-band synergy probe — combine fine residual fitting
    // with a two-step lookahead: reward placements whose post-residual can
    // host the next item AND whose leftover after that still hosts a
    // mean-sized filler; penalize loose fits that strand the fleet mean.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if (after_next as f64) >= mean_residual - 1.5 && (after_next as f64) <= mean_residual + 1.5 {
            score -= 6.0 * (0.5 + 0.5 * progress);
        }
        // Loose-fit penalty: consumed less than half the residual while the
        // leftover gap is neither next-item nor mean-hostable.
        let consumed_frac = item_f / br.max(1.0);
        let hostable = (after_next as f64 - mean_residual).abs() < 3.0
            || (next_item_size as f64 - after_next as f64).abs() < 3.0;
        if consumed_frac < 0.5 && !hostable && after_next > 4 {
            score += (after_next as f64) * 0.35 * (0.4 + 0.6 * progress);
        }
    }

    // Gen-43: fresh-bin pair-sum probe — open a new bin only if the fresh
    // post-residual equals a plausible two-item sum (next + mean), which
    // guarantees a two-step chain; otherwise lean on the existing fleet.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let fresh_gap = bin_residual.saturating_sub(item_size);
        let pair_target = next_item_size as f64 + mean_residual;
        let dev = (fresh_gap as f64 - pair_target).abs();
        if dev <= 2.0 {
            score -= 14.0 * (1.0 - 0.5 * progress);
        } else if dev > mean_residual * 1.2 {
            score += 8.0 * (1.0 - progress);
        }
    }

    score
}

