    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let after_next = post_residual - next_item_size;
        let dev = (after_next as f64 - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 1.9 * (0.6 + 0.4 * progress);
        }
        if after_next >= 16 && after_next < 25 {
            score += 6.0 * (0.5 + 0.5 * progress);
        }
        // New: reward residual states that remain exactly reusable by the
        // item after next (two-hop divisibility).
        if after_next > 0 && after_next % item_size.max(1) == 0 {
            score -= 4.0 * (1.0 - progress);
        }
    }

    // Gen-45 mutation: mean-residual exact-state bonus when the next item
    // seals a bin down to the fleet mean — keeps the fleet in a reusable state.
    if next_item_size as f64 == mean_residual && post_residual as f64 == mean_residual {
        score -= 12.0;
    }

    score
}

