            }
        }
    }

    // Residual-pairing lookahead.
    if next_item_size > 0 && post_residual > next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap <= 3 {
            score -= 12.0 + 10.0 * progress;
        }
        if chain_gap <= 5 && open_bins_count >= 2 {
            score -= (6 - chain_gap) as f64 * (1.5 + 0.25 * open_bins_count.min(12) as f64);
        }
        if chain_gap as f64 > mean_residual * 1.5 {
            score += (chain_gap as f64 - mean_residual * 1.5) * 0.25 * (1.0 - progress);
        }
    }

    // Divisibility lookahead — residual divisible by next item enables full chain fill.
    if next_item_size > 1 && post_residual > 0 && post_residual >= next_item_size {
        let q = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        if rem == 0 {
            score -= (q as f64).min(4.0) * 4.0 * (1.0 - 0.5 * progress);
            if q >= 2 {
                score -= (q as f64).min(5.0) * 3.5 * (0.6 + 0.6 * progress);
            }
        } else if rem <= 2 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Late-stream compaction squeeze.
    if progress > 0.75 && post_residual > 0 {
        score += pr * (progress - 0.75) * 4.0;
    }

    // Near-perfect pack protection.
    if bin_residual > item_size && bin_residual - item_size <= 2 && item_size <= 10 {
        score -= 8.0;
    }

    // Waste-fraction penalty with chain-aware squeeze.
    if bin_residual < bin_capacity && post_residual > 0 {
        let waste_frac = pr / br.max(1.0);
        score += waste_frac * 6.0 * (1.0 - progress);
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        if waste_frac > 0.45 && !chains {
            score += (waste_frac - 0.45) * 22.0 * (0.5 + 0.5 * progress);
        }
        if waste_frac < 0.2 {
            score -= (0.2 - waste_frac) * 15.0 * (0.6 + 0.6 * progress);
        }
    }

    // Density-ratio compaction + fill-efficiency gradient.
    if bin_residual < bin_capacity {
        let consumed_frac = item_f / br.max(1.0);
        if consumed_frac > 0.7 {
            score -= (consumed_frac - 0.7) * 30.0 * (1.2 - progress);
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            let reusable = (post_residual - next_item_size) as f64;
            if consumed_frac > 0.5 && reusable <= 10.0 {
                score -= consumed_frac * (10.0 - reusable) * (0.6 + 0.8 * progress);
            }
        }
        let mean_fill = 1.0 - mean_residual / cap_f;
        if consumed_frac > mean_fill {
            score -= (consumed_frac - mean_fill) * 18.0 * (0.5 + open_bins_count.min(12) as f64 * 0.05);
        }
    }

    // Near-exact residual targeting.
    if post_residual > 0 && post_residual <= 12 {
        score -= 5.0 * (1.0 - progress) + 3.0 * progress;
    }

    // Dead-gap oracle.
    if post_residual > 0 && post_residual < 30 {
        let next_blocks = next_item_size > 0 && (next_item_size as f64) > pr;
        if next_blocks && pr < mean_residual * 0.8 {
            score += (mean_residual * 0.8 - pr) * (0.5 + progress);
        }
    }

    // Residual ladder smoothing.
    if post_residual > 0 {
        let dev = (pr - mean_residual).abs();
        if dev < 4.0 {
            score -= (4.0 - dev) * 2.5;
        }
    }

    // Stranded-gap quadratic accounting.
    if post_residual > 0 && post_residual < 20 {
        let can_take_next = next_item_size > 0 && next_item_size <= post_residual;
        let can_take_mean = (pr - mean_residual).abs() < 2.0;
        if !can_take_next && !can_take_mean {
            let deficit = (20.0 - pr).max(0.0);
            score += deficit * deficit * 0.08 * (0.4 + progress);
        }
    }

    // Exact-closure arbitration.
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 30.0 + (open_bins_count.min(14) as f64) * 1.5;
    }

    // Sliver-seal avoidance late in the stream.
    if post_residual > 0 && progress > 0.5 {
        let sliver = mean_residual / 3.0;
        if pr < sliver {
            score += (sliver - pr) * (1.0 + 2.0 * (progress - 0.5));
        }
    }

    // Exact-sum two-step closure probe.
    if next_item_size > 0 && post_residual > next_item_size {
        let two_step = post_residual - next_item_size;
        if two_step == item_size {
            score -= 22.0 * (0.7 + 0.6 * progress);
        }
    }

    // Gen-46 mutation: chain-continuation depth probe — reward placements whose
    // post-residual absorbs the next item AND leaves a residual near the fleet
    // mean, keeping future fill options alive; penalize stranding mid-band gaps.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let after_next = post_residual - next_item_size;
        let dev = (after_next as f64 - mean_residual).abs();
        if dev < 5.0 {
            score -= (5.0 - dev) * 1.6 * (0.6 + 0.4 * progress);
        }
        if after_next >= 16 && after_next < 25 {
            score += 5.0 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-46 mutation: fine-grained two-item gap compaction — when the residual
    // after the next item is small but nonzero, reward near-closure proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_gap = post_residual - next_item_size;
        if two_gap as f64 <= mean_residual * 1.2 && two_gap > 0 {
            score -= (mean_residual * 1.2 - two_gap as f64) * 0.5 * (0.4 + 0.6 * progress);
        }
        if two_gap <= 2 {
            score -= 9.0 * (1.0 - 0.3 * progress);
        } else if two_gap <= 6 {
            score -= (6 - two_gap) as f64 * 1.8 * (0.5 + 0.5 * progress);
        }
    }

    // Gen-46 mutation: fleet-residual budget guard — when open slack per remaining
    // item is tight, penalize loose fits that burn reusable space.
    if open_bins_count > 1 && bin_residual < bin_capacity {
        let fleet_slack = open_bins_count as f64 * mean_residual;
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if remaining > 0.0 {
            let slack_per_item = fleet_slack / remaining;
            let consumed_frac = item_f / br.max(1.0);
            if slack_per_item < 0.9 && consumed_frac < 0.6 {
                score += (0.9 - slack_per_item) * 14.0 * (1.0 - consumed_frac);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin before placement
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);

    // Reward tight fits: squash post_residual so small remainders are heavily favored
    let tight = (post_residual as f64).powf(0.65);
    score = tight * 1.6;

    // Perfect fit: massive reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a great chain placement; if the post residual is stranded
    // (too small for next item but large enough to be wasted), penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // next item can also go here: slight bonus proportional to how well it fills
            let chain_waste = pr - nxt;
            score -= 6.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // stranded residual: penalize proportionally to stranded size,
            // worse late in the stream when closing bins matters more
            let stranded = pr;
            score += 0.9 * stranded * (0.5 + 0.5 * t);
        }
        // If next item is large, prefer keeping big-residual bins free for it
        if nxt > bin_residual as f64 && bin_residual > item_size {
            // this bin consumes residual the next item might need elsewhere
            score += 0.25 * (bin_residual as f64 - item_size as f64);
        }
    } else {
        // Last item: only absolute tightness matters
        score = post_residual as f64;
        if post_residual == 0 { score -= 50.0; }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * fill;
        if post_residual > 30 {
            score += 10.0; // terrible fit in the only bin: let new-bin compete
        }
    }

    // Prefer filling bins that are already relatively full (best-fit-like bias)
    score -= 6.0 * fill;

    // Global state coupling: when mean residual across open bins is high,
    // prefer consolidating into existing space rather than opening bins.
    if mean_residual > 0.0 {
        score += 0.05 * (mean_residual - post_residual as f64);
    }

    // Many open bins: discourage spreading; few open bins: allow slack.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 0.8 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Late in the stream, tighten everything: dead space costs more.
    score *= 1.0 + 0.5 * t;

    // NEW-BIN CANDIDATE handling: an empty bin has bin_residual == bin_capacity.
    // Give it a baseline cost so it's only chosen when open bins fit badly.
    if bin_residual == bin_capacity {
        score = 55.0
            + 20.0 * (1.0 - t)                       // cheaper to open early
            - 10.0 * open_pressure.min(4.0);          // but if many bins open, prefer reusing? no: keep new-bin costly
        if next_item_size > 0 && next_item_size >= item_size {
            // opening fresh space for a stream of large-ish items can be good
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing else fits: must open
        }
        // If the only fitting bin leaves a huge remainder, opening fresh wins.
        if fitting_bins_count == 1 && post_residual > 40 {
            score -= 25.0;
        }
    }

    score
}

